/// `Compiler::try_emit_box_hash_equals_prefix`, the single-pass twin of the
/// optimizing tier's nio20 wave 5 arm. Also off under
/// `CRATONVM_JIT_SP_IDENTITY_HASH_INLINE=0` /
/// `CRATONVM_JIT_IR_IDENTITY_HASH_INLINE=0`. Read per site compile, so it adds
/// no process global.
pub(super) fn sp_box_hash_class_arm_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SP_BOX_HASH_CLASS_ARM")
}

/// `CRATONVM_JIT_SP_SCOPED_ACCESS_PREFIX` (nio21 wave 3, lane L3, proposal
/// W2L3-3; **default ON**, `=0` keeps every single-pass thin-bound
/// `ScopedMemoryAccess.{get,put}{Short,Char,Int,Long}Unaligned{,Internal}`
/// site on its helper call alone): the single-pass twin of the optimizing
/// tier's scoped fold, as a guarded prefix of that unchanged CALL
/// (`Compiler::try_emit_sp_scoped_access_prefix`). Also off under
/// `CRATONVM_JIT_SP_THIN_PREFIX=0`. Read per site compile, so it adds no
/// process global.
pub(super) fn sp_scoped_access_prefix_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SP_SCOPED_ACCESS_PREFIX")
}

/// `CRATONVM_JIT_SP_UNSAFE_OFFHEAP_PREFIX` (nio21 wave 3, lane L3, proposal
/// W2L3-3; **default ON**, `=0` restores the nio20 prefix exactly: a null base
/// declines to the call): the single-pass `Unsafe` primitive-array prefix
/// (`Compiler::emit_sp_unsafe_access_core`) also serves a NULL base -- a raw
/// off-heap address, or an `Unsafe.allocateMemory` arena handle resolved
/// through the JIT-readable arena table (absent under
/// `CRATONVM_JIT_IR_SCOPED_ARENA_FOLD=0` / `CRATONVM_UNSAFE_ARENA_JIT_TABLE=0`,
/// when a handle declines). Read per site compile.
pub(super) fn sp_unsafe_offheap_prefix_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SP_UNSAFE_OFFHEAP_PREFIX")
}

/// `CRATONVM_JIT_SP_UNSAFE_BIG_ENDIAN_PREFIX` (JIT round 20, lane memory; page
/// `r20-unsafe-accessor-inline-is-optimizing-tier-only-FIXED-20261012.md`; **default
/// OFF** since round 20 wave 2, opt-in `=1`; off declines every four-operand
/// form as before. The JDK's callers never reach it: the four-operand forms
/// are `final` Java methods, so a single-pass site binds their compiled body
/// (or splices it) and never takes the dispatch arm, where this prefix sits;
/// the host A/B on `ZipUtils` showed no gain): the single-pass
/// `Unsafe` dispatch prefix (`Compiler::try_emit_sp_unsafe_dispatch_prefix`)
/// also serves `{get,put}{Short,Char,Int,Long}Unaligned(Object, long, [V,]
/// boolean bigEndian)`, swapping the bytes when the operand is non-zero, as
/// the optimizing tier's `Unsafe` prefix and the single-pass
/// `ScopedMemoryAccess` prefix already do. Read per site compile.
pub(super) fn sp_unsafe_big_endian_prefix_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_SP_UNSAFE_BIG_ENDIAN_PREFIX")
}

/// `CRATONVM_JIT_SP_SCOPED_NEVER_CLOSING_SESSION` (nio21 wave 4, lane L3,
/// proposal W3L3-1; **default ON**, `=0` restores the wave-3 prefix exactly:
/// every non-null session declines to the call): the single-pass
/// `ScopedMemoryAccess` prefix (`Compiler::try_emit_sp_scoped_access_prefix`)
/// also serves a session whose exact class the optimizing fold admits as
/// never closing (`ir_lower::scoped_session_never_closing_class_ids`, itself
/// off under `CRATONVM_JIT_IR_SCOPED_SESSION_FOLD=0`). Read per site compile.
pub(super) fn sp_scoped_never_closing_session_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SP_SCOPED_NEVER_CLOSING_SESSION")
}

/// The shape of a thin-bound `ScopedMemoryAccess` multi-byte accessor the
/// single-pass prefix serves (nio21 wave 3 L3): its width, whether a 2-byte
/// read sign-extends (`short`) or zero-extends (`char`), and whether it is a
/// put. Every one carries a trailing `bigEndian` operand.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct SpScopedAccess {
    pub(super) width: u8,
    pub(super) signed: bool,
    pub(super) is_put: bool,
}

impl SpScopedAccess {
    /// Declared parameters after the receiver: `(session, base, offset,
    /// [value,] bigEndian)`.
    pub(super) const fn num_params(self) -> usize {
        if self.is_put {
            5
        } else {
            4
        }
    }

    /// The JVM return type tag.
    pub(super) const fn ret_type(self) -> u8 {
        match (self.is_put, self.width, self.signed) {
            (true, _, _) => b'V',
            (false, 2, true) => b'S',
            (false, 2, false) => b'C',
            (false, 4, _) => b'I',
            _ => b'J',
        }
    }

    /// The `UnsafeInlineAccess::GATE_BITS` bit of the `Unsafe` capability
    /// gate the helper asks for this width (`scoped_memory_{read,write}_bytes`
    /// map 2 / 4 / 8 bytes to the `{get,put}{Short,Int,Long}` gates, `char`
    /// included).
    pub(super) const fn unsafe_gate_bit(self) -> usize {
        let row = match self.width {
            2 => 1,
            4 => 3,
            _ => 4,
        };
        1usize << (row + if self.is_put { 5 } else { 0 })
    }
}

/// The [`SpScopedAccess`] of the thin helper `callee_entry` names: one of the
/// sixteen multi-byte `ScopedMemoryAccess` cells of `dh` (the public
/// `*Unaligned` binds and their `*Internal` twins). `None` for anything else,
/// an unwired `0` included. The byte accessors are left out: the helpers'
/// shared core declines every 1-byte access.
pub(super) fn sp_scoped_access_of(
    dh: &crate::DirectHelperTable,
    callee_entry: usize,
) -> Option<SpScopedAccess> {
    if callee_entry == 0 {
        return None;
    }
    let get = |width: u8, signed: bool| SpScopedAccess {
        width,
        signed,
        is_put: false,
    };
    let put = |width: u8, signed: bool| SpScopedAccess {
        width,
        signed,
        is_put: true,
    };
    let rows = [
        (dh.scoped_memory_get_short, get(2, true)),
        (dh.scoped_memory_get_char, get(2, false)),
        (dh.scoped_memory_get_int, get(4, true)),
        (dh.scoped_memory_get_long, get(8, true)),
        (dh.scoped_memory_put_short, put(2, true)),
        (dh.scoped_memory_put_char, put(2, false)),
        (dh.scoped_memory_put_int, put(4, true)),
        (dh.scoped_memory_put_long, put(8, true)),
        (dh.scoped_memory_get_short_internal, get(2, true)),
        (dh.scoped_memory_get_char_internal, get(2, false)),
        (dh.scoped_memory_get_int_internal, get(4, true)),
        (dh.scoped_memory_get_long_internal, get(8, true)),
        (dh.scoped_memory_put_short_internal, put(2, true)),
        (dh.scoped_memory_put_char_internal, put(2, false)),
        (dh.scoped_memory_put_int_internal, put(4, true)),
        (dh.scoped_memory_put_long_internal, put(8, true)),
    ];
    rows.into_iter()
        .find(|&(cell, _)| cell == callee_entry)
        .map(|(_, access)| access)
}

/// nio20 wave 3, lane L3 (W2L2-1): the guarded prefixes a single-pass plain
/// direct arm may emit in front of its thin-helper CALL, one per
/// [`SP_THIN_PREFIX_ROWS`] family. Every one keeps the CALL unchanged behind
/// it and joins the result push on a hit (see
/// `Compiler::sp_thin_helper_prefix_admitted`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum SpThinPrefix {
    /// `Integer.valueOf(I)`: an out-of-cache box from the TLAB (round 12).
    IntegerValueOfBox,
    /// `Long.valueOf(J)`: the same, round 12 wave 2 (C12-2).
    LongValueOfBox,
    /// `Object.getClass()`: two loads from the per-VM word table (nio20 w2).
    ObjectGetClass,
    /// The eight thin-bound `Unsafe` primitive-array accessors (nio20 w2).
    UnsafeAccess,
    /// `Integer.intValue()`: one compact/legacy load (nio20 w3, W2L2-2).
    IntegerIntValue,
    /// `Long.longValue()`: the same, 8 bytes (nio20 w3, W2L2-2).
    LongLongValue,
    /// `Thread.currentThread()`: the TLS thread word and one load (nio20 w4,
    /// lane L3; `DirectHelperTable::thread_java_obj_offset`).
    ThreadCurrentThread,
    /// The sixteen multi-byte `ScopedMemoryAccess` thin binds: a null-session
    /// heap or off-heap access, arena handles through the JIT-readable table
    /// (nio21 w3, lane L3, W2L3-3; [`sp_scoped_access_of`]).
    ScopedAccess,
}

impl SpThinPrefix {
    /// Is this row's single-pass prefix switched on? The `valueOf` rows ask
    /// their own switches inside their emitters; the rest share
    /// [`sp_thin_prefix_enabled`].
    fn enabled(self) -> bool {
        match self {
            SpThinPrefix::IntegerValueOfBox | SpThinPrefix::LongValueOfBox => true,
            SpThinPrefix::ObjectGetClass
            | SpThinPrefix::UnsafeAccess
            | SpThinPrefix::IntegerIntValue
            | SpThinPrefix::LongLongValue
            | SpThinPrefix::ThreadCurrentThread => sp_thin_prefix_enabled(),
            SpThinPrefix::ScopedAccess => {
                sp_thin_prefix_enabled() && sp_scoped_access_prefix_enabled()
            }
        }
    }
}

/// One row of [`SP_THIN_PREFIX_ROWS`].
pub(super) struct SpThinPrefixRow {
    pub(super) prefix: SpThinPrefix,
    /// The `DirectHelperTable` cell the site's `callee_entry` must equal.
    pub(super) helper: fn(&crate::DirectHelperTable) -> usize,
    /// The instance arm (`true`, receiver first in the arguments) or the
    /// static arm.
    pub(super) receiver: bool,
    /// The declared parameter count (receiver excluded); `None` when the
    /// prefix's emitter screens the shape itself (`Unsafe`).
    pub(super) params: Option<usize>,
    /// The return type tag; `None` as above.
    pub(super) ret: Option<u8>,
}

/// nio20 wave 3, lane L3 (W2L2-1): THE table of single-pass thin-helper
/// prefixes, consulted by both plain direct arms (`invokestatic` and the
/// instance `invokespecial`/`invokevirtual` arm) after the one admission
/// screen (`sp_thin_helper_prefix_admitted`). A new prefix is one row here
/// plus its emitter in `Compiler::try_emit_sp_thin_prefix`.
pub(super) const SP_THIN_PREFIX_ROWS: &[SpThinPrefixRow] = &[
    SpThinPrefixRow {
        prefix: SpThinPrefix::IntegerValueOfBox,
        helper: |dh: &crate::DirectHelperTable| dh.integer_value_of,
        receiver: false,
        params: Some(1),
        ret: Some(b'L'),
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::LongValueOfBox,
        helper: |dh: &crate::DirectHelperTable| dh.long_value_of,
        receiver: false,
        params: Some(1),
        ret: Some(b'L'),
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::ObjectGetClass,
        helper: |dh: &crate::DirectHelperTable| dh.object_get_class,
        receiver: true,
        params: Some(0),
        ret: Some(b'L'),
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::IntegerIntValue,
        helper: |dh: &crate::DirectHelperTable| dh.integer_int_value,
        receiver: true,
        params: Some(0),
        ret: Some(b'I'),
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::LongLongValue,
        helper: |dh: &crate::DirectHelperTable| dh.long_long_value,
        receiver: true,
        params: Some(0),
        ret: Some(b'J'),
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::ThreadCurrentThread,
        helper: |dh: &crate::DirectHelperTable| dh.thread_current_thread,
        receiver: false,
        params: Some(0),
        ret: Some(b'L'),
    },
    // nio21 wave 3, lane L4: `Thread.currentCarrierThread()`. Its registered
    // native is `currentThread`'s, so the helper's fast arm answers the same
    // mirror word and the same prefix serves it (published only where the
    // per-call gate can never refuse: `thread_java_obj_offset`).
    SpThinPrefixRow {
        prefix: SpThinPrefix::ThreadCurrentThread,
        helper: |dh: &crate::DirectHelperTable| dh.thread_current_carrier_thread,
        receiver: false,
        params: Some(0),
        ret: Some(b'L'),
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_get_byte,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_get_short,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_get_int,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_get_long,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_put_byte,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_put_short,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_put_int,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_put_long,
        receiver: true,
        params: None,
        ret: None,
    },
    // nio21 wave 4 L4: the volatile int/long thin binds; the prefix serves an
    // aligned primitive-array element and declines everything else (a field
    // offset, a null base) to the unchanged CALL.
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_get_int_volatile,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_get_long_volatile,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_put_int_volatile,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_put_long_volatile,
        receiver: true,
        params: None,
        ret: None,
    },
    // nio21 wave 5 L3: the `compareAndSet{Int,Long}` thin binds; the prefix
    // serves an aligned primitive-array element with one `LOCK CMPXCHG` and
    // declines everything else to the unchanged CALL.
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_cas_int,
        receiver: true,
        params: None,
        ret: None,
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_cas_long,
        receiver: true,
        params: None,
        ret: None,
    },
    // JIT round 20 wave 12, lane qUnsafe (AT-4): the `compareAndSetReference`
    // thin bind; the prefix serves a published compact reference field whose
    // barriers the published gates rule out, and declines everything else to
    // the unchanged CALL.
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        helper: |dh: &crate::DirectHelperTable| dh.unsafe_cas_reference,
        receiver: true,
        params: Some(4),
        ret: Some(b'Z'),
    },
    // JIT round 21 wave 1, lane updaters (UPDATERS21-1, opt-in): the
    // reference volatile get / put thin binds; the prefix serves a published
    // compact reference field (a put only where the published gates rule the
    // barriers out) and declines everything else to the unchanged CALL.
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        // Unwired (`0`, no row) with the switch off: the default site is untouched.
        helper: |dh: &crate::DirectHelperTable| {
            if crate::direct_helpers::unsafe_ref_volatile_field_enabled() {
                dh.unsafe_get_reference_volatile
            } else {
                0
            }
        },
        receiver: true,
        params: Some(2),
        ret: Some(b'L'),
    },
    SpThinPrefixRow {
        prefix: SpThinPrefix::UnsafeAccess,
        // Unwired (`0`, no row) with the switch off: the default site is untouched.
        helper: |dh: &crate::DirectHelperTable| {
            if crate::direct_helpers::unsafe_ref_volatile_field_enabled() {
                dh.unsafe_put_reference_volatile
            } else {
                0
            }
        },
        receiver: true,
        params: Some(3),
        ret: Some(b'V'),
    },
];

/// The [`SP_THIN_PREFIX_ROWS`] row a plain direct site matches: its bound
/// `callee_entry` is the row's helper cell (never an unwired `0`), at the
/// row's arm, with the row's declared shape. `None`: no prefix, the call
/// stands alone.
pub(super) fn sp_thin_prefix_row(
    dh: &crate::DirectHelperTable,
    callee_entry: usize,
    receiver: bool,
    callee_params: usize,
    ret_type: u8,
) -> Option<SpThinPrefix> {
    if callee_entry == 0 {
        return None;
    }
    SP_THIN_PREFIX_ROWS
        .iter()
        .find(|row| {
            row.receiver == receiver
                && (row.helper)(dh) == callee_entry
                && row.params.is_none_or(|p| p == callee_params)
                && row.ret.is_none_or(|t| t == ret_type)
        })
        .map(|row| row.prefix)
        // nio21 wave 3 (lane L3): the sixteen `ScopedMemoryAccess` cells are
        // one family with its own shape table (`sp_scoped_access_of`), so
        // they are matched there rather than as sixteen rows. Instance arm.
        .or_else(|| {
            sp_scoped_access_of(dh, callee_entry)
                .filter(|a| receiver && a.num_params() == callee_params && a.ret_type() == ret_type)
                .map(|_| SpThinPrefix::ScopedAccess)
        })
}

/// Round 13 (lane crash): the inline MIC/PIC native-stack guard
/// (`CRATONVM_JIT_IC_STACK_GUARD`, default on; `0` emits the IC hit path
/// exactly as before). Read per site compile, so it adds no process global.
fn ic_stack_guard_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IC_STACK_GUARD")
}

/// `CRATONVM_JIT_SP_IC_PROTECTED_SITES` (default ON since round 15 wave 4, the
/// orchestrator's flip after the battery, `C2_ACCEPT=never` / `THRESHOLD=1`
/// arms and a Spring census all matched the default; `0` restores the
/// round-13 gate; round 13 wave 11, lane mega9, proposal M13-7): a
/// virtual/interface site inside a protected
/// range of a method compiled with precise exception frames keeps its inline
/// caches and hashed stub, where the hoisted pre-call spill makes the hit
/// paths publish the caller state the dispatch path does (see the site). Off,
/// every call at such a site is a helper call, as since `a523715a84`. Read per
/// site compile.
fn sp_ic_protected_sites_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SP_IC_PROTECTED_SITES")
}

/// gcd d9/d (2026-09-28): `CRATONVM_JIT_CALLEE_OWNED_ARGS` (default on; `0`
/// keeps the service copy of a baked direct call's arguments exactly as
/// before). Read per site compile, so it adds no process global and a test's
/// thread override reaches it.
fn callee_owned_args_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_CALLEE_OWNED_ARGS")
}

/// gcd d9/d (2026-09-28): may this baked single-pass direct `CALL` leave its
/// arguments to the callee? The SITE half of the rule; the callee half is
/// `crate::direct_callee_owns_its_arguments`, asked after this answers `true`.
///
/// Every term keeps a reader of the arguments that runs after the call:
///
/// * `opcode == invokestatic` and `invoke_kind == 3`, or (gcd d10/f,
///   2026-09-28, `walk_invoke_instance`'s plain direct arm) an instance opcode
///   whose site is statically bound, `invoke_kind == 1` (every `invokespecial`,
///   and a private `invokevirtual` / `invokeinterface` the single-pass site
///   planner pins to its owner): the service resolves such a callee by name
///   (through the pinned owner id), and reads no receiver out of the arguments
///   (`jit_service_callee_deopt_body`'s `receiver_class_id` is asked only for
///   kinds 0/2, whose receiver class selects the method; those keep the copy);
/// * not a caller-held synchronized site (either row): its exits read the
///   receiver back from the service copy;
/// * not a retire-cell site: the cell's dispatch fallback takes the service
///   copy as its argument buffer;
/// * not a protected pc: with the copy gone, a trap the service can no longer
///   re-run leaves this frame as a frameless deopt through the shared
///   sentinel exit, and only an unprotected invoke's exception check takes
///   that exit (a protected one goes to a local-handler stub or a reason-9
///   frame, which expect a pending exception);
/// * `caller_replay_exact` (gcd d10/f, 2026-09-28; asked last, it scans the
///   bytecode): that frameless deopt is
///   answered by the caller's caller RE-RUNNING THIS METHOD FROM ENTRY, so it
///   is admitted only where that re-run commits nothing twice
///   (`Compiler::owned_args_handoff_replays_exactly`). Without it a rare
///   callee decline (a redefinition mid-call, a rematerialisation that fails
///   after a collection) replayed every store, invoke and monitor operation
///   this method made before the call
///   (`gcd-d10f-owned-args-handoff-replays-the-caller-unchecked-DONE-20260928.md`).
///   A refused site keeps the copy, and its service re-runs only the callee,
///   as before d9/d.
///
/// Pure, so the table is testable without a compile.
fn sp_direct_call_args_owned_by_callee(
    enabled: bool,
    opcode: Option<u8>,
    invoke_kind: Option<u8>,
    sync_direct_site: bool,
    retire_cell: bool,
    pc_is_protected: bool,
    caller_replay_exact: impl FnOnce() -> bool,
) -> bool {
    let statically_bound = matches!(
        (opcode, invoke_kind),
        (Some(0xb8), Some(3)) | (Some(0xb6 | 0xb7 | 0xb9), Some(1))
    );
    enabled
        && statically_bound
        && !sync_direct_site
        && !retire_cell
        && !pc_is_protected
        && caller_replay_exact()
}

/// `CRATONVM_JIT_SPLICE_CALLEE_OWNED_ARGS` -- default on, `=0` keeps the
/// service copy at a spliced direct call. See
/// [`splice_call_args_owned_by_callee`]. Read per site compile.
fn splice_callee_owned_args_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SPLICE_CALLEE_OWNED_ARGS")
}

/// gcd d9/d row 4 (the gcj j2/pn2 residual, `Gcd1ArgPinSpecialProbe`
/// `spliced-direct`): may a single-pass splice's direct call leave its
/// arguments to its callee? [`sp_direct_call_args_owned_by_callee`] with the
/// splice's terms: no spliced call is a caller-held synchronized site or a
/// retire cell, `pc_is_protected` is asked of the splice's own call site, and
/// `replay_exact` holds the rest (both replay levels, the callee's ownership;
/// `Compiler::splice_inner_call_owned_args`). Asked last, as it scans
/// bytecode.
pub(super) fn splice_call_args_owned_by_callee(
    opcode: Option<u8>,
    invoke_kind: Option<u8>,
    pc_is_protected: bool,
    replay_exact: impl FnOnce() -> bool,
) -> bool {
    sp_direct_call_args_owned_by_callee(
        callee_owned_args_enabled() && splice_callee_owned_args_enabled(),
        opcode,
        invoke_kind,
        false,
        false,
        pc_is_protected,
        replay_exact,
    )
}

/// gcd d10/f (2026-09-28): the replay rule every other frameless exit of a
/// single-pass body is held to before install (`x64/driver.rs`,
/// `deopt::single_pass_first_trap_needing_unsound_replay`), asked of the call
/// at `pc`: may a re-run of this method from bci 0 replace an attempt that
/// stopped at this call? `true` when nothing in `code[..pc]`, closed over
/// every loop containing `pc`, commits a side effect (no array or field
/// store, no invoke, no monitor operation:
/// `deopt::replay_from_entry_commits_nothing_with_handlers` with the
/// single-pass tier's "spliced bodies are pure", since a splice's `invoke` is
/// in this prefix, and `handlers`, the method's exception table in bci space:
/// a backward handler edge widens the extent exactly as it does for the
/// driver's frameless traps).
///
/// `code`/`code_len` are the bytecode the walk emits. It answers `false`
/// (keep the copy) for a compile of REWRITTEN bytecode, whose pcs are not the
/// interpreter's bcis the rule is stated in, and for a self-locking body,
/// whose frameless exit would release and re-take the method monitor across
/// the re-run.
///
/// The residue, which this does not change: the callee's own abandoned
/// attempt is still replayed by the re-run, exactly as the copying site's
/// `rerun_declined_callee_from_entry` / frameless re-run replays it (counted
/// in the door census, `callee-declined`).
///
/// j27 wave 9: production asks [`caller_replay_to_call_is_exact_with_statics`]
/// (this rule with no static vouched for); this form stays for the gcd d9/d tests.
#[cfg(test)]
fn caller_replay_to_call_is_exact(
    code: &[u8],
    code_len: usize,
    pc: usize,
    handlers: &[(usize, usize, usize)],
) -> bool {
    // ARGWIN21-4: plus a straight-line prefix whose only stores fill arrays
    // it allocated itself (`deopt::owned_args_caller_replay_is_exact`).
    u32::try_from(pc).is_ok_and(|bci| {
        crate::deopt::owned_args_caller_replay_is_exact(code, code_len, bci, handlers)
    })
}

/// j27 wave 9 (lane W9RPL; OOM21-2): [`caller_replay_to_call_is_exact`]
/// plus the opt-in constant-`putstatic` arm
/// (`deopt::owned_args_caller_replay_is_exact_with_statics`), with the
/// single-pass tier's resolved static rows (`Compiler::static_field_info`)
/// vouching for each `putstatic` ([`sp_static_row_is_plain`]). The IR tier
/// vouches the same way from its `Op::StoreStatic` nodes; the service-copy
/// window already counts both (`deopt::owned_args_caller_replay_may_be_exact`).
fn caller_replay_to_call_is_exact_with_statics(
    code: &[u8],
    code_len: usize,
    pc: usize,
    handlers: &[(usize, usize, usize)],
    static_rows: &[(usize, u32, usize, u8, bool)],
) -> bool {
    u32::try_from(pc).is_ok_and(|bci| {
        crate::deopt::owned_args_caller_replay_is_exact_with_statics(
            code,
            code_len,
            bci,
            handlers,
            &|at: usize| sp_static_row_is_plain(static_rows, at),
        )
    })
}

/// Does the single-pass compile's static row at `pc` name a resolved
/// (`class_id != 0`), non-volatile static? Rows are
/// `(pc, class_id_raw, field_index, type_tag, is_volatile)`.
fn sp_static_row_is_plain(static_rows: &[(usize, u32, usize, u8, bool)], pc: usize) -> bool {
    static_rows
        .iter()
        .any(|&(at, class_id, _, _, is_volatile)| at == pc && class_id != 0 && !is_volatile)
}

impl Compiler {
    /// `caller_replay_to_call_is_exact` for this compile: `false` on
    /// rewritten bytecode (`bci_provenance`) and in a self-locking body
    /// (`self_lock_obj_off`), both set before the walk. j27 wave 9: with the
    /// constant-`putstatic` arm ([`caller_replay_to_call_is_exact_with_statics`]).
    pub(super) fn owned_args_handoff_replays_exactly(
        &self,
        code: &[u8],
        code_len: usize,
        pc: usize,
    ) -> bool {
        self.bci_provenance.is_none()
            && self.self_lock_obj_off == 0
            && caller_replay_to_call_is_exact_with_statics(
                code,
                code_len,
                pc,
                &self.replay_handler_ranges,
                &self.static_field_info,
            )
    }
}

/// `CRATONVM_JIT_IC_HIT_SERVICE_COPY_WINDOW` -- default on, `=0` off. See
/// [`ic_hit_window_arg_oops`]. Read per site compile.
fn ic_hit_service_copy_window_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IC_HIT_SERVICE_COPY_WINDOW")
}

/// gcd d9/d row 2 (the gcj j2/pn2 residual, `Gcd1ArgPinSpecialProbe`
/// `virtual-direct` / `interface-direct`): which words of an inline-cache
/// site's args buffer a MIC/PIC hit files as its service copy for the
/// collector's window (`CompiledMethod::service_arg_copies`, gkr OOM21-2):
/// every reference argument but the receiver, by `arg_oops`' index.
///
/// A monomorphic `invokevirtual` / `invokeinterface` lowers to the inline
/// cache, whose one buffer feeds the hit's marshal, the `.miss` helper and,
/// after a hit returns the sentinel, the site-open service. Named in the
/// call's map, it kept every argument for the whole call however early the
/// callee dropped it, where HotSpot's argument is the callee's. Filed at the
/// hit's return address, those words are cleared by the collector once the
/// callee that ran stands past its last exact re-run point
/// (`conservative_roots::clear_closed_service_copies`, which asks the callee
/// frame itself, so whatever the cache bound is judged): from there the
/// service never reads them. The receiver stays: the service reads its class
/// to select the callee (`jit_service_callee_deopt_body`). The miss helper,
/// the hashed stub and the vtable column return elsewhere, so their buffer is
/// whole. All `false` with the switch off.
fn ic_hit_window_arg_oops(arg_oops: &[bool]) -> Vec<bool> {
    let on = ic_hit_service_copy_window_enabled();
    arg_oops
        .iter()
        .enumerate()
        .map(|(i, &oop)| on && oop && i > 0)
        .collect()
}

/// The outgoing stack block for a single-pass MIC hit whose `n` arguments
/// (receiver included) do not fit `regs` argument registers together with the
/// context word: `Some((total_sub, stack_base))`, or `None` when nothing
/// overflows or more than `crate::inline_cache_pic::ic_max_stack_words()`
/// would (4 until round 13 wave 11, 8 since: lane mega9, proposal M13-8,
/// `CRATONVM_JIT_IC_WIDE_STACK_WORDS`). A bound on code size at a site, not
/// an ABI limit: every compiled prologue reads any number of caller stack
/// words.
///
/// Sized for the CONTEXT ABI (`vm_ptr` + `n` words), which always needs one
/// more stack word than the context-free ABI, so one `SUB`/`ADD` pair of the
/// same size serves both paths of the hit; the context-free path leaves its
/// top word unused. The layout is `emit_stack_arg_setup`'s: Win64 reserves the
/// 32-byte home area below the stack words (`stack_base == 32`), SysV none,
/// and the total is rounded up to 16 so RSP stays aligned at the CALL.
fn ic_stack_arg_block(n: usize, regs: usize, win64: bool) -> Option<(i32, i32)> {
    let words = (n + 1).checked_sub(regs).filter(|&w| w > 0)?;
    if words > crate::inline_cache_pic::ic_max_stack_words() {
        return None;
    }
    let shadow: i32 = if win64 { 32 } else { 0 };
    let raw = shadow + i32::try_from(words).ok()? * 8;
    Some(((raw + 15) & !15, shadow))
}

// ---------------------------------------------------------------------------
// Post-call exit sites (interpreter round i1 wave 27, lane L6)
// ---------------------------------------------------------------------------
//
// `docs/feature-designs/profile-guided-inlining.md`,
// stages 1-2, for the single-pass tier's OSR compiles. After a real call whose
// successor state an `OsrExit` map can describe, the walk emits a five-byte
// `NOP` (`crate::ENTRY_PATCH_PAD`) and files the map at the SUCCESSOR bci; after
// the walk each site gets a 16-byte stub (`CALL` the shared verdict tail, `JNZ`
// the successor's reason-7 stub, `JMP` back past the `NOP`). A class
// redefinition that withdraws the body rewrites the `NOP` into a `JMP` to the
// stub (`JitCache::force_withdrawn_exit_polls`, with the body's exit polls), so
// a frame whose thread was inside the call leaves for the interpreter as soon
// as the call returns, before the rest of its iteration runs an old splice --
// what HotSpot's return-address patch to the deopt blob does. Until then the
// fast path is the `NOP` (and, at most one site in two, a one-to-four-byte
// alignment `NOP` in front of it).

/// Kill switch for the post-call exit sites. `false` emits no site, no stub
/// and no successor map: every compile is byte-identical to wave 26's.
pub(super) const POST_CALL_EXITS_ENABLED: bool = true;

/// Kill switch for post-call exit sites in a METHOD-ENTRY single-pass compile
/// (interpreter round i1 wave 29, lane L3;
/// `interpreter-L6-a-compiled-frame-in-a-call-at-the-redefinition-keeps-its-old-splice-FIXED-20261007`,
/// the "next single-pass step" of the proposal's "Why OSR compiles only"). Such
/// a body gets a site only once it already carries a loop-boundary exit map
/// (`Compiler::osr_exit_points` non-empty when the walk reaches the call: a
/// loop header before it, or an `invokedynamic` trap map), so no body that had
/// none gains its first deopt exit here -- the caller-held direct `CALL` route
/// for synchronized callees (`jit_bridge::wrapped_body_has_no_deopt_exit`)
/// answers as before. The exit leaves on the method-entry verdict bit
/// (`SAFEPOINT_VERDICT_POLLING_BODY`), as the body's own back-edge polls do.
/// `false` restores wave 28's OSR-only rule.
pub(super) const METHOD_ENTRY_POST_CALL_EXITS_ENABLED: bool = true;

/// Kill switch for a METHOD-ENTRY single-pass post-call site that files the
/// body's FIRST loop-boundary exit map: a call before the first loop header
/// in bytecode order, or in a loop-free body (interpreter round i1 wave 39,
/// lane L3; `interpreter-L6-a-compiled-frame-in-a-call-at-the-redefinition-keeps-its-old-splice-FIXED-20261007`,
/// "What remains"). Admitted only when the compile keeps a dispatch record
/// (`Compiler::keeps_a_call_record`): such a body calls something by its
/// artifact's own record (`_jit_invoke_infos`, `_jit_mic_slots`,
/// `_jit_pic_slots`), so the two routes wave 29 kept the first deopt exit
/// away from -- the caller-held direct `CALL` of a synchronized callee
/// (`jit_bridge::caller_held_body_is_closed`) and the synchronized door's
/// wrapped body (`door_admits_wrapped_body`) -- already refuse it through
/// `wrapped_body_attempt_never_reruns`'s "calls nothing" test, whatever its
/// deopt exits. The other reader the first map changes, `can_osr_exit`, is
/// read by the OSR door's transfer only, which never enters a method-entry
/// body. The wave-38 argument for the optimizing tier, applied here.
/// `false` restores wave 29's rule (a map filed before the call).
pub(super) const METHOD_ENTRY_FIRST_MAP_POST_CALL_EXITS_ENABLED: bool = true;

/// Switch for a METHOD-ENTRY single-pass post-call site that files the body's
/// FIRST loop-boundary exit map in a compile that keeps NO dispatch record,
/// when the door said the method is not `ACC_SYNCHRONIZED`
/// (`BackendRequest::method_known_unsynchronized`; interpreter round i2 wave
/// 54, lane L2: item 1 of
/// `interpreter-L6-a-compiled-frame-in-a-call-at-the-redefinition-keeps-its-old-splice-FIXED-20261007`).
///
/// The dispatch-record test of [`METHOD_ENTRY_FIRST_MAP_POST_CALL_EXITS_ENABLED`]
/// exists only to keep the first deopt exit off a body that the two
/// synchronized routes must see exit-free: the caller-held direct `CALL`
/// (`jit_bridge::caller_held_body_is_closed`) and the synchronized door's
/// wrapped body (`door_admits_wrapped_body`), both asked only about an
/// `ACC_SYNCHRONIZED` method's body. The other readers of a body's first
/// exit map are the OSR door's (`can_osr_exit`, `cached_osr_body_is_despec_stale`:
/// OSR bodies only) and the door's stash read (`body_may_publish_a_pad_frame`:
/// one more length load per such call), so for an unsynchronized method the
/// site is admitted whatever its calls go through: a body whose only calls
/// are intrinsic helpers that can reach a safepoint now leaves after such a
/// call when a redefinition forces it, instead of finishing its activation
/// on a splice of the redefined class. `false` keeps the wave-39 rule. `true`
/// since the wave-54 lane's last commit.
pub(super) const METHOD_ENTRY_UNSYNCHRONIZED_FIRST_MAP_POST_CALL_EXITS: bool = true;

/// Kill switch for the constant-pool helper exit sites (interpreter round i1
/// wave 44, lane L2;
/// `interpreter-L2-proposal-exits-at-a-withdrawn-bodys-constant-pool-helper-calls-RETIRED-20261015`):
/// a patchable site BEFORE each run-time constant-pool helper call (`ldc`
/// String / Class, a deferred `new` / `anewarray`, `multianewarray`), with an
/// `OsrExit` map at the instruction ITSELF, so a body a redefinition or a
/// debugger withdrew leaves for the interpreter at the instruction instead of
/// running it compiled (and translating its constant-pool index). The same
/// site, stub, verdict tail, cap and force pass as the post-call exits
/// ([`Compiler::emit_cp_helper_exit_site`]). `false` emits no such site, and
/// every compile is byte-identical to wave 43's.
pub(super) const CP_HELPER_EXITS_ENABLED: bool = true;

// Post-call exit CLAIMS (interpreter round i1 wave 48, lane L2;
// `docs/feature-designs/jit-ir-optimizations.md`):
// every single-pass post-call site builds its map at the call's return but
// records only a CLAIM ([`PostCallExitClaim`]); after the walk
// ([`Compiler::resolve_post_call_exit_claims`]) the claim
//
// * files its map, when nothing else filed a non-rethrow point at the
//   successor's bci;
// * shares the one `OsrExit` map filed there, when it describes the same
//   frame (the stub's `JNZ` resolves by bci, so the site and the successor's
//   own exit leave through one point);
// * is dropped otherwise (the `NOP` stays, never recorded, never forced):
//   the refusal is decided by what was filed, not by a prediction.
//
// So the successor admission covers every instruction that can follow a call
// in the same basic block ([`post_call_exit_claim_successor_admitted`]). The
// wave-47 admission that filed the map at once, and so had to PREDICT every
// successor whose own lowering files a point at that bci (the wave-46
// successor list with its `getstatic` / `getfield` switch, and the
// rotated-entry `goto` and fused back-edge constant refusals), sat behind the
// `false` arm of the `POST_CALL_EXIT_CLAIMS_ENABLED` const from wave 48 and
// was deleted in interpreter round i2 wave 62 (lane L2;
// `docs/feature-designs/jit-ir-optimizations.md`):
// those two shapes are now decided by what is filed (the pre-header guards
// are a point of another reason, the fused back edge's map one the claim
// shares or yields to).

/// At most this many post-call exit sites per compile. Each costs a successor
/// map, a stub of 16 bytes and a reason-7 stub; past the cap a call keeps
/// wave 26's behaviour (its frame leaves at the next exit-capable back edge).
/// The constant-pool helper exit sites (wave 44) count against it too, and so
/// do unresolved claims ([`PostCallExitClaim`]). 64 until
/// interpreter round i1 wave 48; 1024 under [`POST_CALL_EXIT_SITES_WIDE_CAP`]
/// until 2026-10-07; since then [`POST_CALL_EXIT_SITES_UNREACHABLE_CAP`]
/// under [`POST_CALL_EXIT_SITES_UNCAPPED`] (item 4 of
/// `interpreter-L6-a-compiled-frame-in-a-call-at-the-redefinition-keeps-its-old-splice-FIXED-20261007`).
pub(super) const POST_CALL_EXIT_SITES_MAX: usize = if POST_CALL_EXIT_SITES_UNCAPPED {
    POST_CALL_EXIT_SITES_UNREACHABLE_CAP
} else if POST_CALL_EXIT_SITES_WIDE_CAP {
    1024
} else {
    64
};

/// A cap no method reaches: a method's code is at most 65535 bytes
/// (JVMS 4.7.3), and every site follows an instruction of at least one byte
/// (a call, or a constant-pool helper instruction of at least two), so a
/// compile can never queue this many. Kept as a number rather than removed
/// so that the per-compile counters stay bounded by construction.
pub(super) const POST_CALL_EXIT_SITES_UNREACHABLE_CAP: usize = 65_536;

/// Kill switch for lifting the post-call site cap (item 4 of the i24-L6
/// page: "a call past the 1024th site of a single-pass compile"; 2026-10-07).
/// The cap bounded only a pathological method's metadata, and that
/// metadata grows linearly with the calls without it, as the first 1024
/// sites' already did: one frame-wide point per call, beside the oop map the
/// call already keeps (and, inside a try range, the `RETHROW` frame of the
/// same width that `emit_post_invoke_exception_check` files for it). The
/// sites are `NOP`s until a redefinition forces them, so the cost is
/// metadata only. Past the 1024th site such a method (only one of more than
/// 3000 bytes of calls: HotSpot does not compile it at all,
/// `DontCompileHugeMethods`, so its frame returns into the interpreter at
/// every call's return there) ran the rest of the iteration after a call
/// whose splice a redefinition withdrew on the old bytecode once. `false`
/// restores the 1024 of [`POST_CALL_EXIT_SITES_WIDE_CAP`].
pub(super) const POST_CALL_EXIT_SITES_UNCAPPED: bool = true;

/// Kill switch for the `invokedynamic`, `monitorenter` and `monitorexit`
/// successors of a post-call exit claim
/// ([`post_call_exit_claim_successor_admitted`]; item 2 of the i24-L6 page,
/// 2026-10-07). `false` refuses them, as from wave 48.
pub(super) const POST_CALL_EXIT_CLAIMS_AT_INDY_AND_MONITORS: bool = true;

/// Kill switch for the post-call exit sites after a `getstatic` /
/// `putstatic` helper call that may run `<clinit>`
/// ([`Compiler::emit_post_clinit_helper_exit_site`]; the i24-L6 page's
/// "Fixed (2026-10-07)"). `false` emits none, as before.
pub(super) const POST_CLINIT_HELPER_EXIT_SITES: bool = true;

/// Kill switch for a LOCAL exception handler's entry as the successor of a
/// post-call exit claim, reached live by the call's fall-through
/// ([`forward_only_joins`]; item 2 of the i24-L6 page, 2026-10-07). `false`
/// refuses every handler entry, as from wave 60.
pub(super) const POST_CALL_EXIT_CLAIMS_AT_HANDLER_ENTRIES: bool = true;

/// Kill switch for the wider post-call exit site cap (interpreter round i1
/// wave 48, lane L2; item 4 of "Progress (wave 40)" of
/// `interpreter-L6-a-compiled-frame-in-a-call-at-the-redefinition-keeps-its-old-splice-FIXED-20261007`:
/// "a call past a compile's 64th site"). The 64 was never a limit of the
/// mechanism: a site is a five-byte `NOP` (plus at most a four-byte pad), a
/// 16-byte stub and one `OsrExit` point, each proportional to the call it
/// follows, which already carries its own oop map and exception frame; the
/// force pass (`not_entrant::exit_poll_writes`) iterates a `Vec`. The cap is
/// kept only as a bound on a pathological method's metadata. The optimizing
/// tier's `IR_POST_CALL_EXIT_SITES_MAX` is 512 since interpreter round i2
/// wave 54 (its graphs admit 64 own calls, plus the real calls of its spliced
/// bodies, which have post-call sites since wave 47). `false` restores the 64.
pub(super) const POST_CALL_EXIT_SITES_WIDE_CAP: bool = true;

/// A post-call exit site whose map is not filed yet (a CLAIM, interpreter
/// round i1 wave 48): the patchable `NOP` at `site`, the
/// call's successor at emitter pc `bci`, and the `OsrExit` point built at the
/// call's return (`Compiler::build_deopt_point`: the frame as the `NOP` sees
/// it, stamped with the `NOP`'s buffer position).
pub(crate) struct PostCallExitClaim {
    site: usize,
    bci: usize,
    point: crate::deopt::DeoptimizationPoint,
    /// `bci` is a loop header ([`post_call_exits_at_loop_headers_enabled`]):
    /// the claim may only share the header's map, never file its own.
    loop_header: bool,
}

/// How [`Compiler::resolve_post_call_exit_claims`] settled one claim.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PostCallExitClaimOutcome {
    /// Nothing else filed a non-rethrow point at the bci: the claim's own map.
    /// Since wave 49 ([`crate::osr_exit::OSR_EXIT_MAPS_BESIDE_GUARDS`]) also
    /// when everything else there is a `REEXECUTE` guard of the claim's frame
    /// ([`guard_admits_an_exit_map_beside`]).
    Own,
    /// The one non-rethrow point there is an `OsrExit` map of the same frame.
    Shared,
    /// Only `REEXECUTE` guards of ANOTHER frame are there (the next invoke's
    /// dispatch-helper snapshot, taken after its arm flushed a `float` /
    /// `double` result the claim's map saw in its XMM register), no
    /// `OsrExit` map is keyed at the bci,
    /// and the compile is a METHOD-ENTRY one (since wave 56 also an OSR-tier
    /// one, [`osr_post_call_own_point_exits_enabled`]): the claim's point is
    /// recorded in `deopt_points` but not filed by bci, and its stub bakes it
    /// itself (tag 13, [`post_call_own_point_exits_enabled`]). Interpreter
    /// round i2 wave 55, lane L2.
    OwnBeside,
    /// Another point is there: the site is left an unrecorded `NOP`.
    Dropped,
}

/// `CRATONVM_JIT_POST_CALL_OWN_POINT_EXITS` -- interpreter round i2 wave 55,
/// lane L2: build
/// `docs/feature-designs/jit-ir-optimizations.md`
/// (item 2 of
/// `interpreter-L6-a-compiled-frame-in-a-call-at-the-redefinition-keeps-its-old-splice-FIXED-20261007.md`).
///
/// On: a single-pass post-call exit claim whose successor filed only
/// `REEXECUTE` guards of a DIFFERENT frame at its bci (measured: `g(f())`
/// where `f` returns a `float` or `double`, which the claim's map reads from
/// its XMM register and `g`'s dispatch-helper snapshot from its frame word;
/// an `int`, `long` or reference result is in its frame word at the return,
/// so that claim is wave 49's `Own`) is settled
/// [`PostCallExitClaimOutcome::OwnBeside`] instead of `Dropped`, in a
/// METHOD-ENTRY compile only: the point goes into `deopt_points` (so every
/// stash sink's `owns_deopt_point` and the cause check know it), NOT into
/// `osr_exit_box_ptr_by_bci` / `osr_exit_points` (OSR entry, the OSR door's
/// exit classification and the loop-boundary readers never see it), and its
/// stub (tag 13 of `emit_deopt_stubs`) bakes it from
/// `Compiler::post_call_own_box_ptr_by_bci`. Every cause-less by-bci reason
/// lookup already skips an `OsrExit` point beside a guard
/// (`osr_exit::trap_reason_at_bci`, wave 49), and the stub stashes the
/// point's own cause. Off (`=0`): such a claim is `Dropped`, as in waves
/// 48-54. **Default ON** since the wave-55 lane's last commit (revert that
/// commit to turn it off by default).
///
/// Read once per compile that settles a claim; not cached in a static
/// (`process_global_statics_ratchet`).
pub(crate) fn post_call_own_point_exits_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_POST_CALL_OWN_POINT_EXITS")
}

/// `CRATONVM_JIT_OSR_POST_CALL_OWN_POINT_EXITS` -- interpreter round i2 wave
/// 56, lane L2: the OSR-tier stage of
/// `docs/feature-designs/jit-ir-optimizations.md`
/// (item 2 of
/// `interpreter-L6-a-compiled-frame-in-a-call-at-the-redefinition-keeps-its-old-splice-FIXED-20261007.md`).
///
/// On (with [`post_call_own_point_exits_enabled`]): an OSR-tier compile
/// (`mode_exit_polls`) settles a claim [`PostCallExitClaimOutcome::OwnBeside`]
/// as a method-entry one does, when the compile already filed a loop-boundary
/// or back-edge exit map (so the artifact is `can_osr_exit` and the OSR door's
/// transfer takes the exit). The OSR door's by-bci readers know such a point
/// through `CompiledMethod::post_call_own_exit_bcis`: the exit classification
/// answers `PostCallOwnPoint` instead of the `ExitMapMissing` cross-check, and
/// the OSR entry contract (`osr_entry_frame_state`) never takes it for the
/// guard's frame at that bci. `resume_after_exit` needs nothing: the claim's
/// point and the guards beside it agree on `resume_kind`
/// (`Compiler::claim_may_bake_its_own_point`), so `resume_image` stays
/// unique there. Off (`=0`): such a claim is `Dropped` in an OSR-tier
/// compile, as in waves 48-55. **Default ON** since the wave-56 lane's
/// switch-on commit (revert that commit to turn it off by default).
///
/// Read once per OSR-tier compile that settles a claim; not cached in a
/// static (`process_global_statics_ratchet`).
pub(crate) fn osr_post_call_own_point_exits_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_OSR_POST_CALL_OWN_POINT_EXITS")
}

/// The `emit_deopt_stubs` tag of a post-call exit stub that bakes its own
/// point ([`PostCallExitClaimOutcome::OwnBeside`]); 7 is the tag of one that
/// resolves through `osr_exit_box_ptr_by_bci`.
pub(super) const POST_CALL_OWN_POINT_STUB_TAG: i64 = 13;

/// The `emit_deopt_stubs` tag of a post-call exit stub after a real call
/// inside a splice ([`Compiler::emit_splice_post_call_exit_site`]): its
/// `deopt_stubs` entry's `site_pc` is an index into
/// `Compiler::splice_post_call_box_ptrs`, not a bci. Interpreter round i2
/// wave 59, lane L2.
pub(super) const SPLICE_POST_CALL_STUB_TAG: i64 = 14;

/// The `deopt_point_pcs` entry of a splice post-call exit's point: no pc of
/// the compile's own method (see [`Compiler::emit_splice_post_call_exit_site`]).
pub(super) const SPLICE_POINT_EMITTER_PC: usize = usize::MAX;

/// `CRATONVM_JIT_SP_POST_CALL_SPLICE_EXITS` -- interpreter round i2 wave 59,
/// lane L2: the single-pass stage of
/// `docs/feature-designs/deopt-osr.md`.
/// On: a single-pass METHOD-ENTRY compile puts a post-call exit site after a
/// real call made inside an outermost splice, leaving through a two-frame
/// chain ([`Compiler::emit_splice_post_call_exit_site`]), and the splice
/// flushes its scratch registers before it captures the caller scope. Off:
/// no such site, byte for byte as before (a frame inside such a call
/// finishes the splice on the old bytecode and leaves at its next
/// exit-capable site). **Default ON** since the wave-59 lane's switch-on
/// commit (revert that commit to turn it off by default). Read per spliced
/// call of a compile; not cached in a static (`process_global_statics_ratchet`).
pub(crate) fn sp_post_call_splice_exits_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SP_POST_CALL_SPLICE_EXITS")
}

/// `CRATONVM_JIT_SP_OSR_POST_CALL_SPLICE_EXITS` -- interpreter round i2 wave
/// 62, lane L2: the OSR-tier stage of the single-pass splice post-call exits
/// (the "call inside a splice of a single-pass OSR-tier compile" member of
/// `docs/feature-designs/jit-ir-optimizations.md`).
///
/// On (with [`sp_post_call_splice_exits_enabled`]): a single-pass OSR-tier
/// compile (`mode_exit_polls`) that already filed a loop-boundary exit map
/// (so the artifact is `can_osr_exit` and the OSR door transfers its exits)
/// puts the wave-59 post-call exit site after a real call made inside an
/// outermost splice. Its two-frame chain point leaves through the OSR door's
/// planned chain transfer (`deopt_resume::transfer_osr_exit_chain_into_live_frame`,
/// `RecordedBci`: the looping method's live frame is rewritten to park in its
/// `invoke` of the spliced callee, and the callee is pushed at the call's
/// successor with the result on its stack) -- the transfer every chain guard
/// of a single-pass OSR splice already takes. The point is recorded, never
/// filed by bci, and the entry contract skips every chain point
/// (`CompiledMethod::osr_entry_frame_state`), so the header's entry map is
/// untouched. Off: an OSR-tier compile emits no such site, byte for byte as
/// before (a frame inside such a call finishes the splice on the old
/// bytecode and leaves at the loop's next exit-capable back edge). **Default
/// ON** since the wave-62 lane's switch-on commit (revert that commit to turn
/// it off by default; `=0` turns it off). Read per spliced call of an
/// OSR-tier compile; not cached in a static (`process_global_statics_ratchet`).
pub(crate) fn sp_osr_post_call_splice_exits_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SP_OSR_POST_CALL_SPLICE_EXITS")
}

/// `CRATONVM_JIT_SP_NESTED_POST_CALL_SPLICE_EXITS` -- the last call shape of
/// `docs/feature-designs/jit-ir-optimizations.md`
/// with no exit in a single-pass body: a real call inside a NESTED splice
/// (`docs/feature-designs/deopt-osr.md`).
///
/// On (with [`sp_post_call_splice_exits_enabled`]): a nested splice records
/// the enclosing callee parked in its `invoke` ([`NestedSpliceLevel`]), and
/// the wave-59 site after a real call inside the nested body files a chain
/// point of one frame per spliced level -- the innermost callee at the
/// call's successor with the result pushed, each enclosing callee parked in
/// its `invoke`, the compile's own method parked in its `invoke` -- which
/// the nested splice's postcondition admits (it names exactly the points the
/// sites queued). Off: no level is recorded and every site inside a nested
/// splice is refused, byte for byte as before. **Default ON.** Read once per
/// nested splice and per site; not cached in a static
/// (`process_global_statics_ratchet`).
pub(crate) fn sp_nested_post_call_splice_exits_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SP_NESTED_POST_CALL_SPLICE_EXITS")
}

/// `CRATONVM_JIT_POST_CALL_EXITS_AT_FORWARD_JOINS` -- interpreter round i2
/// wave 60, lane L2 (item 2 of
/// `docs/feature-designs/deopt-osr.md`).
/// On: a single-pass post-call exit CLAIM may name a successor that is a
/// branch target when it is a forward-only join ([`forward_only_joins`]) --
/// the shape of a call that ends an `if` arm with no `else`, whose successor
/// is the join, so a frame inside that call when its body was withdrawn ran
/// the rest of the iteration on the old splice. Off: every branch-target
/// successor is refused, byte for byte as before. **Default ON** since the
/// wave-60 lane's switch-on commit (revert that commit to turn it off by
/// default). Read once per single-pass walk; not cached in a static
/// (`process_global_statics_ratchet`).
pub(crate) fn post_call_exits_at_forward_joins_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_POST_CALL_EXITS_AT_FORWARD_JOINS")
}

/// `CRATONVM_JIT_POST_CALL_EXITS_AT_LOOP_HEADERS` -- interpreter round i2
/// wave 61, lane L2
/// (`docs/feature-designs/jit-ir-optimizations.md`).
/// On: a single-pass post-call exit claim may name a successor that is a LOOP
/// HEADER (a textual back edge's target: `x = prepare(); while (...)`), but
/// only to SHARE the header's own `OsrExit` map
/// ([`PostCallExitClaimOutcome::Shared`]: one non-rethrow point there, the
/// keyed `OsrExit` map, describing the claim's frame value by value and
/// location by location). The site's stub then resolves to the header's map,
/// which OSR entry and the header's back-edge polls already read by bci; the
/// claim never files (`Own`) or bakes (`OwnBeside`) a map of its own there,
/// so the header's entry contract is untouched. Every other outcome drops
/// the claim. Off: every loop-header successor is refused, byte for byte as
/// before. **Default ON** since the wave-61 lane's switch-on commit (revert
/// that commit to turn it off by default). Read once per single-pass walk
/// (compile time); not cached in a static.
pub(crate) fn post_call_exits_at_loop_headers_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_POST_CALL_EXITS_AT_LOOP_HEADERS")
}

/// `targets[pc]`: is `pc` the target of a textual back edge of `code` (a loop
/// header, by the rule [`forward_only_joins`] refuses)? Built once per walk
/// ([`Compiler::post_call_loop_headers`]).
pub(super) fn back_edge_targets(code: &[u8], code_len: usize) -> Vec<bool> {
    let mut targets = vec![false; code_len + 1];
    for (target, _source) in crate::bytecode_analysis::back_edges(code, code_len) {
        if let Some(t) = targets.get_mut(target) {
            *t = true;
        }
    }
    targets
}

/// [`back_edge_targets`] for one pc: the debug census's question
/// (`Compiler::note_post_call_header_claim_census`), asked per refused claim.
fn is_back_edge_target(code: &[u8], code_len: usize, pc: usize) -> bool {
    crate::bytecode_analysis::back_edges(code, code_len)
        .into_iter()
        .any(|(target, _)| target == pc)
}

/// `joins[pc]`: may a post-call exit claim name `pc` although it is a branch
/// target ([`Compiler::post_call_forward_joins`])? Only when every edge into
/// it is an explicit FORWARD branch or switch entry and the fall-through:
/// not pc 0 (the method entry), not an exception handler's entry (an implicit
/// edge), not the target of any textual back edge
/// (`bytecode_analysis::back_edges`: a loop header, whose map OSR entry and
/// the back-edge polls read by bci), and not a loop-boundary map's bci
/// (`osr_exit_map_headers`, which also names a rotated loop's dominating
/// test). The site's `NOP` follows the call on the fall-through edge alone,
/// before the walk binds the join's label and canonicalises its operands, so
/// its map describes exactly the frame that edge brings; the other edges never
/// pass it. Nothing else reads an `OsrExit` map at such a bci: a forward
/// branch polls nowhere, and the claim's resolution still yields to any point
/// another arm files there.
///
/// A LOCAL exception handler's entry is a join too under
/// [`POST_CALL_EXIT_CLAIMS_AT_HANDLER_ENTRIES`] (2026-10-07): its implicit
/// edge is the local-handler stub's jump to the entry's label, which never
/// passes the `NOP` either, and the walk compiles a live fall-through into it
/// only with the one reference the exception edge also brings
/// (`singlepass-codegen/local-handler-entry-live-fallthrough` refuses any
/// other depth), so the claim's map is exactly the fall-through edge's frame.
/// Nothing reads an `OsrExit` map at a handler's bci: the exception edge's
/// precise frames are `RETHROW` points keyed by the THROWING bci
/// (`exc_frame_box_ptr_by_bci`), and a handler-only pc publishes no OSR
/// entry. javac never falls into a handler (the protected code ends in a
/// `goto`, a return or `athrow`), so only generated bytecode reaches this.
pub(super) fn forward_only_joins(
    code: &[u8],
    code_len: usize,
    branch_targets: &[bool],
    handler_pcs: &[usize],
    loop_boundary_maps: &rustc_hash::FxHashSet<usize>,
) -> Vec<bool> {
    let mut joins: Vec<bool> = (0..=code_len)
        .map(|pc| branch_targets.get(pc).copied().unwrap_or(false))
        .collect();
    if let Some(entry) = joins.get_mut(0) {
        *entry = false;
    }
    if !POST_CALL_EXIT_CLAIMS_AT_HANDLER_ENTRIES {
        for &h in handler_pcs {
            if let Some(j) = joins.get_mut(h) {
                *j = false;
            }
        }
    }
    for (target, _source) in crate::bytecode_analysis::back_edges(code, code_len) {
        if let Some(j) = joins.get_mut(target) {
            *j = false;
        }
    }
    for &header in loop_boundary_maps {
        if let Some(j) = joins.get_mut(header) {
            *j = false;
        }
    }
    joins
}

/// A post-call exit site after a real call inside a splice, queued by
/// [`Compiler::emit_splice_post_call_exit_site`]: the patchable `NOP`, the
/// identity box of its recorded chain point, and the source rows of the
/// spliced bodies its chain names (the innermost one, then every enclosing
/// spliced callee of a nested splice; a body with no class id to name it by
/// has none).
pub(crate) struct SplicePostCallExit {
    pub(super) site: usize,
    pub(super) point: *const crate::deopt::DeoptimizationPoint,
    pub(super) sources: Vec<crate::SpliceScopeSource>,
}

/// One level of a NESTED single-pass splice, pushed by
/// `inlining.rs::try_emit_nested_inline` while the nested body is emitted
/// and popped on both of its exits (interpreter round i2, the i62-L2
/// nested-splice proposal, built behind
/// [`sp_nested_post_call_splice_exits_enabled`]).
///
/// A nested splice pushes no caller scope on `inline_scope_stack` (every
/// other point would inherit it); this is the scope a post-call exit INSIDE
/// the nested body needs, and only it reads it. `parked` is the ENCLOSING
/// spliced callee parked in its `invoke` of the nested one (arguments
/// popped, the result not yet pushed), built as the wave-59 site builds a
/// callee frame: its locals from the enclosing body's memory homes typed by
/// a whole-body kind scan, its operand window below the arguments all
/// references. `None` when that frame cannot be described, which refuses
/// every site inside this level.
pub(crate) struct NestedSpliceLevel {
    pub(super) parked: Option<crate::deopt::FrameState>,
    /// The enclosing callee's source row, for the chain sinks to rebuild its
    /// scope after a redefinition (`None`: no class id).
    pub(super) enclosing_source: Option<crate::SpliceScopeSource>,
    /// The NESTED callee's identity and geometry, as
    /// `InlineCalleeScope` gives them for the outermost splice: its key, its
    /// own `max_locals`, and where its window of the shared operand stack
    /// starts.
    pub(super) key: String,
    pub(super) max_locals: usize,
    pub(super) caller_stack_floor: usize,
}

/// May the caller scope `push_inline_scope` captured be rebuilt at an exit
/// INSIDE the splice? Every value must still be where the scope says when
/// the body has run up to a call's return: a constant, a frame word, or a
/// callee-saved local home (`LOCAL_REGS`: RBX, R12-R15, and RSI / RDI on
/// Windows since wave 62; the splice body and every call it makes preserve
/// them, and the exit stub spills them). Never an XMM or a
/// caller-saved GPR (the body clobbers them), a scalar-replaced object, an
/// undescribed slot, or a held monitor (a door hands the method monitor to
/// ONE resumed frame; a chain's lock is not this exit's to move).
fn splice_caller_scope_is_transferable(fs: &crate::deopt::FrameState) -> bool {
    splice_caller_scope_refusal(fs).is_none()
}

/// One value of [`splice_caller_scope_is_transferable`]'s rule.
fn splice_scope_value_ok(v: &crate::deopt::FrameValue) -> bool {
    use crate::deopt::FrameValue;
    match v {
        FrameValue::Int(_)
        | FrameValue::Long(_)
        | FrameValue::Float(_)
        | FrameValue::Double(_)
        | FrameValue::Undefined
        | FrameValue::StackSlot(_)
        | FrameValue::StackSlotRef(_)
        | FrameValue::StackSlotLong(_)
        | FrameValue::StackSlotFloat(_)
        | FrameValue::StackSlotDouble(_) => true,
        FrameValue::Object(0) => true,
        // A callee-saved local home of this ABI (`LOCAL_REGS`: RBX and
        // R12-R15, and on Windows RSI and RDI too). Interpreter round i2 wave
        // 62, lane L2: the rule named RBX / R12-R15 only, which refused every
        // Windows caller scope with a local homed in RSI or RDI (measured on
        // `L2W62SinglePassOsrPostCallExitInsideASplice`'s OSR loops: `local 0 =
        // RegisterLong(6)`); the splice body never allocates a root local's
        // home, every call it makes preserves it, and the exit stub saves all
        // sixteen GPRs.
        FrameValue::Register(r) | FrameValue::RegisterLong(r) | FrameValue::RegisterRef(r) => {
            super::LOCAL_REGS.contains(r)
        }
        _ => false,
    }
}

/// [`splice_caller_scope_is_transferable`] naming the first thing it refuses
/// (interpreter round i2 wave 62, lane L2: the `CRATONVM_DBG_JITC` refusal
/// line of [`Compiler::emit_splice_post_call_exit_site`] prints it).
fn splice_caller_scope_refusal(fs: &crate::deopt::FrameState) -> Option<String> {
    if !fs.monitors.is_empty() {
        return Some("a held monitor".to_string());
    }
    if let Some((i, v)) = fs
        .locals
        .iter()
        .enumerate()
        .find(|(_, v)| !splice_scope_value_ok(v))
    {
        return Some(format!("local {i} = {v:?}"));
    }
    if let Some((i, v)) = fs
        .stack
        .iter()
        .enumerate()
        .find(|(_, v)| !splice_scope_value_ok(v))
    {
        return Some(format!("stack {i} = {v:?}"));
    }
    fs.caller.as_deref().and_then(splice_caller_scope_refusal)
}

/// The successors a CLAIMED post-call site admits (interpreter round i1
/// wave 48): constants, local loads and stores, the stack shuffles, `iinc`
/// and the field reads (the wave-46 list), a `goto` whatever its stack (a
/// live stack's `goto` files its own map at its bci, which the claim then
/// shares or yields to), and the instructions that list refused only because
/// their lowering MAY file a point at their own bci: array loads and stores,
/// field stores, arithmetic, conditional branches and switches, `ldc`, the
/// four ordinary invokes, the allocations and the type checks. Still refused:
/// the returns and `athrow` (nothing after them runs in this frame), and
/// `jsr` / `ret`.
///
/// `invokedynamic` and the monitor instructions are admitted under
/// [`POST_CALL_EXIT_CLAIMS_AT_INDY_AND_MONITORS`] (they were refused from
/// wave 48 until 2026-10-07): the claim is decided by what is filed at the
/// bci, like every other successor's. A BRIDGED `invokedynamic`
/// (`"v=" + f()`: `invokestatic f; invokedynamic makeConcatWithConstants`)
/// files no point of its own -- its bridge call's only point is the
/// `RETHROW` frame every claim ignores -- so the claim keeps its own map
/// there (`Own`). A TRAPPING one files its `UnreachedCode` snapshot keyed in
/// `osr_exit_box_ptr_by_bci` at that bci, so the claim is `Dropped` and
/// never shares it (a trap's map is charged as a failed speculation); the
/// frame then leaves at the trap itself, before the instruction runs, which
/// is the claim's own resume point. A `monitorenter` / `monitorexit`
/// successor re-executes in the interpreter with the frame the claim
/// describes (the lock it would take, or the hold it would release, is
/// exactly what [`Compiler::branch_mode_exit_admits`] checks for any
/// successor inside a `synchronized` block); javac never puts either right
/// after a call (it stores the lock object first), so this is hand-written
/// or generated bytecode only.
fn post_call_exit_claim_successor_admitted(op: u8) -> bool {
    match op {
        // invokedynamic.
        0xba => POST_CALL_EXIT_CLAIMS_AT_INDY_AND_MONITORS,
        // jsr, ret, jsr_w.
        0xa8 | 0xa9 | 0xc9 => false,
        // ireturn .. return, athrow.
        0xac..=0xb1 | 0xbf => false,
        // monitorenter, monitorexit.
        0xc2 | 0xc3 => POST_CALL_EXIT_CLAIMS_AT_INDY_AND_MONITORS,
        // Everything else a verified method can put after a call: nop ..
        // sipush, ldc .. ldc2_w, the loads, array loads, stores, array stores,
        // the stack shuffles, arithmetic, conversions, compares, the
        // conditional branches, goto, the switches, the field accesses, the
        // ordinary invokes, new .. arraylength, checkcast, instanceof, wide,
        // multianewarray, ifnull / ifnonnull, goto_w.
        0x00..=0xa7 | 0xaa | 0xab | 0xb2..=0xb9 | 0xbb..=0xbe | 0xc0 | 0xc1 | 0xc4..=0xc8 => true,
        _ => false,
    }
}

/// May an `OsrExit` map of `map`'s frame and `semantics` sit at the bci of
/// `guard`, a non-rethrow point of another reason already filed there
/// (interpreter round i1 wave 49, lane L2, behind
/// [`crate::osr_exit::OSR_EXIT_MAPS_BESIDE_GUARDS`];
/// `interpreter-L2-proposal-a-trap-is-charged-by-the-point-its-stub-baked-FIXED-20261013`)?
///
/// Only when the two describe the SAME interpreter state: the guard
/// re-executes its instruction as the map does (same `semantics`), and its
/// frame matches the map's value by value and location by location
/// ([`post_call_exit_frames_match`]). Then either stub resumes the same
/// frame, and each stashes the cause of the point it baked (a guard's stub
/// bakes `deopt_box_ptr_by_bci[(bci, reason)]`, the exit's
/// `osr_exit_box_ptr_by_bci[bci]`), so a trap is charged by what fired; the
/// cause-less by-bci lookup skips the map beside a guard
/// ([`crate::osr_exit::deopt_reason_at_bci`]). Never beside an `OsrExit`
/// point (the callers share or refuse those) nor an `UnreachedCode` one (the
/// `invokedynamic` trap snapshot is filed in the exit's own by-bci map).
pub(super) fn guard_admits_an_exit_map_beside(
    guard: &crate::deopt::DeoptimizationPoint,
    map: &crate::deopt::FrameState,
    semantics: crate::deopt::ResumeSemantics,
) -> bool {
    use crate::deopt::DeoptReason;
    let admitted = crate::osr_exit::OSR_EXIT_MAPS_BESIDE_GUARDS
        && !matches!(
            guard.reason,
            DeoptReason::OsrExit | DeoptReason::UnreachedCode
        )
        && !guard.semantics.rethrow_exception
        && guard.semantics == semantics
        && post_call_exit_frames_match(&guard.frame_state, map);
    // JIT round 19 (lane selflock19, SYNCDOOR618-3): the census of the
    // `ResumeSemantics` compare. A refusal caused ONLY by the self-lock mark
    // (`method_monitor_first`, the one bit `resume_kind()` strips besides
    // `first_arrival`), with frames that match value by value, is a merge an
    // explicit `resume_kind()` + mark compare could have made. One
    // `CRATONVM_DBG_JITC` line per such refusal (`grep -c
    // 'self-lock-mark-merge'`); the proposal is built only if it is non-zero
    // on the blocks battery. Reporting only.
    if !admitted
        && crate::x64::dbg_jitc_enabled()
        && guard.semantics != semantics
        && guard.semantics.resume_kind() == semantics.resume_kind()
        && guard.semantics.first_arrival == semantics.first_arrival
        && !matches!(
            guard.reason,
            DeoptReason::OsrExit | DeoptReason::UnreachedCode
        )
        && !guard.semantics.rethrow_exception
        && post_call_exit_frames_match(&guard.frame_state, map)
    {
        eprintln!(
            "[cratonvm-jitc] self-lock-mark-merge refused site=exit-map-beside-guard {} bci={} \
             guard-mark={} map-mark={}",
            map.method_key,
            map.bci,
            guard.semantics.method_monitor_first,
            semantics.method_monitor_first,
        );
    }
    admitted
}

/// Do two frame states describe the same interpreter frame, value by value
/// and location by location? Two `OsrExit` maps at one bci may share one
/// point only then ([`Compiler::resolve_post_call_exit_claims`]).
fn post_call_exit_frames_match(a: &crate::deopt::FrameState, b: &crate::deopt::FrameState) -> bool {
    a.method_key == b.method_key
        && a.bci == b.bci
        && a.locals == b.locals
        && a.stack == b.stack
        && a.caller.is_none()
        && b.caller.is_none()
        && a.monitors.len() == b.monitors.len()
        && a.monitors.iter().zip(&b.monitors).all(|(x, y)| {
            x.object == y.object && x.lock_depth == y.lock_depth && x.relock == y.relock
        })
}

/// The first place two frame states differ, in the terms of
/// [`post_call_exit_frames_match`] (`None` when it would answer `true`): the
/// census line of `Compiler::report_post_call_header_claim_census`
/// (interpreter round i2 wave 61, lane L2). `header` is the loop header's
/// own map, `claim` the frame the call's return would describe.
fn first_frame_difference(
    header: &crate::deopt::FrameState,
    claim: &crate::deopt::FrameState,
) -> Option<String> {
    if header.method_key != claim.method_key || header.bci != claim.bci {
        return Some("identity".to_string());
    }
    if header.caller.is_some() || claim.caller.is_some() {
        return Some("caller-chain".to_string());
    }
    if header.locals.len() != claim.locals.len() {
        return Some(format!(
            "locals-len {} vs {}",
            header.locals.len(),
            claim.locals.len()
        ));
    }
    if let Some((i, (h, c))) = header
        .locals
        .iter()
        .zip(&claim.locals)
        .enumerate()
        .find(|(_, (h, c))| h != c)
    {
        return Some(format!("local {i}: header={h:?} call-return={c:?}"));
    }
    if header.stack.len() != claim.stack.len() {
        return Some(format!(
            "stack-len {} vs {}",
            header.stack.len(),
            claim.stack.len()
        ));
    }
    if let Some((i, (h, c))) = header
        .stack
        .iter()
        .zip(&claim.stack)
        .enumerate()
        .find(|(_, (h, c))| h != c)
    {
        return Some(format!("stack {i}: header={h:?} call-return={c:?}"));
    }
    if !post_call_exit_frames_match(header, claim) {
        return Some("monitors".to_string());
    }
    None
}

/// Bytes the shared verdict tail reserves below its realigned stack pointer:
/// the Win64 home area (32, harmless on SysV) and the sixteen XMM registers
/// (16 bytes each). A multiple of 16, so the `CALL` stays aligned.
const POST_CALL_EXIT_TAIL_FRAME: i32 = 0x20 + 16 * 16;

/// A single `NOP` instruction of `len` bytes (1 to 4; longer asks are clamped
/// to 4), the padding that moves a post-call exit site into one 8-aligned
/// word.
fn post_call_exit_pad(len: usize) -> &'static [u8] {
    match len {
        0 => &[],
        1 => &[0x90],
        2 => &[0x66, 0x90],
        3 => &[0x0F, 0x1F, 0x00],
        _ => &[0x0F, 0x1F, 0x40, 0x00],
    }
}

impl Compiler {
    /// After the invoke at the walk's current pc made a real call and left
    /// the walk at `next`: emit a post-call exit site there when one is
    /// admitted (see the section note above). Called by `compile_bytecode`
    /// only; emits nothing and files nothing on a refusal.
    ///
    /// Admitted in an OSR-tier compile (`mode_exit_polls`: the probe's loops,
    /// and a body that already has a loop-boundary exit map, so no caller-held
    /// direct `CALL` route that refuses a body with `osr_exit_points` loses
    /// anything) or, since interpreter round i1 wave 29 (lane L3), a
    /// method-entry compile that already filed such a map before the call
    /// ([`METHOD_ENTRY_POST_CALL_EXITS_ENABLED`]) -- since wave 39 also one
    /// that files the body's first such map here when it keeps a dispatch
    /// record ([`METHOD_ENTRY_FIRST_MAP_POST_CALL_EXITS_ENABLED`]) --, that reserved a compile
    /// id (the stub names its body to the verdict), outside a splice, and
    /// whatever [`Self::emit_post_call_exit_claim`] admits for `next`: the
    /// site is a CLAIM settled after the walk (interpreter round i1 wave 48;
    /// the wave-47 admission that filed its map at once was deleted in
    /// interpreter round i2 wave 62).
    pub(super) fn emit_post_call_exit_site(
        &mut self,
        code: &[u8],
        code_len: usize,
        next: usize,
        branch_targets: &[bool],
    ) {
        self.emit_post_call_exit_claim(code, code_len, next, branch_targets);
    }

    /// After a `getstatic` / `putstatic` HELPER call (`op_field.rs`), standing
    /// at the instruction after it, `next`: the post-call exit claim an invoke
    /// gets ([`Self::emit_post_call_exit_site`]), when the access's class may
    /// still be uninitialized -- the VM did not prove it initialized at
    /// compile time (`DirectHelperTable::class_is_initialized`, `false` when
    /// it cannot tell), so the helper may run its `<clinit>`. An initialized
    /// class whose reads stay on the helper (`java/lang/System`, a second VM)
    /// gets no site. Under [`POST_CLINIT_HELPER_EXIT_SITES`].
    ///
    /// A `<clinit>` is Java code: it can redefine (or block while another
    /// thread redefines) a class this body spliced, and the helper then
    /// returned into the old splice and ran the rest of the activation on it
    /// (measured, 2026-10-07: `tools/probes/interp/L2/I24PostHelperRedefinition.java`
    /// rows `getstatic` / `putstatic` printed `false` in both tiers, HotSpot
    /// `true`: its compiled code reaches an uninitialized class through an
    /// uncommon trap or a patching stub, and a frame marked meanwhile is
    /// deoptimized on the return). The site is a `NOP` until a redefinition
    /// forces it, exactly as after an invoke; its map is at `next` with the
    /// loaded value pushed (`getstatic`) or the stored one popped
    /// (`putstatic`), the state the interpreter has after the access.
    pub(super) fn emit_post_clinit_helper_exit_site(
        &mut self,
        code: &[u8],
        code_len: usize,
        next: usize,
        branch_targets: &[bool],
        class_id_raw: u32,
    ) {
        if !POST_CLINIT_HELPER_EXIT_SITES || self.direct_helpers.class_is_initialized(class_id_raw)
        {
            return;
        }
        self.emit_post_call_exit_claim(code, code_len, next, branch_targets);
    }

    /// The body of [`Self::emit_post_call_exit_site`]:
    /// the compile-wide conditions, `next` not a branch target (a loop
    /// header files its own map there, which OSR entry reads by bci) unless it
    /// is a forward-only join ([`forward_only_joins`], since wave 60: the
    /// site's `NOP` sits on the fall-through edge alone, before the join's
    /// label, so its map describes only the frame that edge brings), a successor [`post_call_exit_claim_successor_admitted`] admits,
    /// and the admission of [`Self::branch_mode_exit_target`] for a map at
    /// `next` with the whole current stack as its operands -- but instead of
    /// filing that map, the point is built here, at the call's return, and
    /// queued with the site's `NOP` as a [`PostCallExitClaim`] that
    /// [`Self::resolve_post_call_exit_claims`] settles after the walk, when
    /// every point the successor's own arm files at `next` is known. A
    /// rotated loop's entry `goto` and the constant of a fused backward
    /// compare need no refusal of their own (wave 47's): the pre-header
    /// guards are a point of another reason there (the claim is dropped), and
    /// the fused back edge's map is an `OsrExit` map the claim shares or
    /// yields to.
    fn emit_post_call_exit_claim(
        &mut self,
        code: &[u8],
        code_len: usize,
        next: usize,
        branch_targets: &[bool],
    ) {
        // Interpreter round i2 wave 60, lane L2: a branch-target successor is
        // admitted when it is a forward-only join
        // ([`post_call_exits_at_forward_joins_enabled`]).
        if !POST_CALL_EXITS_ENABLED
            || !self.post_call_exit_site_may_be_emitted()
            || next >= code_len
        {
            return;
        }
        let mut loop_header = false;
        if branch_targets.get(next).copied().unwrap_or(true)
            && !self
                .post_call_forward_joins
                .get(next)
                .copied()
                .unwrap_or(false)
        {
            // Wave 61: a LOOP HEADER successor, under its switch, for the
            // `Shared` outcome only (`post_call_exits_at_loop_headers_enabled`).
            // Not pc 0 (the method entry has no call before it anyway) and
            // only a textual back edge's target: a handler entry stays
            // refused.
            loop_header = next != 0
                && self
                    .post_call_loop_headers
                    .get(next)
                    .copied()
                    .unwrap_or(false);
            if !loop_header {
                // The census of a loop-header successor (debug only).
                if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_DEOPT") {
                    self.note_post_call_header_claim_census(code, code_len, next);
                }
                return;
            }
        }
        let Some(&op) = code.get(next) else {
            return;
        };
        if !post_call_exit_claim_successor_admitted(op) {
            return;
        }
        let operands = self.stack.len();
        if !self.branch_mode_exit_admits(next, operands) {
            return;
        }
        let point = self.build_deopt_point(next, crate::deopt::DeoptReason::OsrExit);
        let site = self.emit_post_call_exit_patch_nop();
        // Interpreter round i6 wave 121, lane L2 (i43-L1 stage 3a): the call
        // this site follows, for `CompiledMethod::debugger_exit_call_bcis`.
        if self.debugger_observes_locals {
            self.debugger_claim_call_bcis.push((site, self.cur_bc_pc));
        }
        self.post_call_exit_claims.push(PostCallExitClaim {
            site,
            bci: next,
            point,
            loop_header,
        });
    }

    /// Interpreter round i6 wave 121, lane L2 (stage 3a of
    /// `i43-L1-proposal-deoptimize-a-compiled-frame-for-the-frame-commands`):
    /// the claim at `site`, whose `OsrExit` map stands at `exit_bci`, was
    /// kept, so `(call bci, exit_bci)` joins [`Self::debugger_exit_call_bcis`].
    /// Nothing for a site the walk did not note (any compile without
    /// `debugger_observes_locals`).
    fn note_debugger_exit_claim_kept(&mut self, site: usize, exit_bci: usize) {
        if let Some(&(_, call_bci)) = self.debugger_claim_call_bcis.iter().find(|&&(s, _)| s == site)
        {
            if let (Ok(call_bci), Ok(exit_bci)) = (u32::try_from(call_bci), u32::try_from(exit_bci))
            {
                self.debugger_exit_call_bcis.push((call_bci, exit_bci));
            }
        }
    }

    /// Step 0 of
    /// `docs/feature-designs/jit-ir-optimizations.md`
    /// (interpreter round i2 wave 61, lane L2), under `CRATONVM_DBG_DEOPT`
    /// only: a claim refused because its successor `next` is a branch target
    /// that is no forward-only join. When `next` is a LOOP HEADER (a textual
    /// back edge's target) whose successor and admission would pass, the
    /// frame the claim would describe is built -- nothing is emitted, recorded
    /// or filed (`build_frame_state_at` reads the walk's state only) -- and
    /// kept for [`Self::report_post_call_header_claim_census`], which compares
    /// it with the header's own `OsrExit` map after the walk. Any other
    /// refusal prints its reason at once.
    fn note_post_call_header_claim_census(&mut self, code: &[u8], code_len: usize, next: usize) {
        let is_header = is_back_edge_target(code, code_len, next);
        let refusal = if !is_header {
            Some("not-a-loop-header")
        } else if !code
            .get(next)
            .copied()
            .is_some_and(post_call_exit_claim_successor_admitted)
        {
            Some("successor-refused")
        } else {
            let operands = self.stack.len();
            self.branch_mode_exit_refusal(next, operands)
        };
        if let Some(why) = refusal {
            eprintln!(
                "[cratonvm-deopt] post-call header claim census at bci={next} of {}: refused ({why})",
                self.method_key
            );
            return;
        }
        // Built exactly as a claim's point is (`emit_post_call_exit_claim`),
        // and like it not recorded.
        let point = self.build_deopt_point(next, crate::deopt::DeoptReason::OsrExit);
        self.post_call_header_claim_census.push(PostCallExitClaim {
            site: 0,
            bci: next,
            point,
            loop_header: true,
        });
    }

    /// After the walk, under `CRATONVM_DBG_DEOPT`: for every claim
    /// [`Self::note_post_call_header_claim_census`] kept, print whether the
    /// header's own `OsrExit` map (the one `osr_exit_box_ptr_by_bci` keys
    /// there) describes the same frame value by value and location by
    /// location -- the `Shared` outcome the proposal would admit -- and if
    /// not, the first slot that differs. Rank with
    /// `grep 'post-call header claim census' | sed 's/.*: //' | sort | uniq -c`.
    pub(super) fn report_post_call_header_claim_census(&mut self) {
        let census = std::mem::take(&mut self.post_call_header_claim_census);
        for claim in census {
            let keyed = self.osr_exit_box_ptr_by_bci.get(&claim.bci).copied();
            let header = keyed.and_then(|k| {
                self.deopt_boxes
                    .iter()
                    .position(|b| std::ptr::addr_of!(**b) == k)
                    .and_then(|i| self.deopt_points.get(i))
            });
            let verdict = match header {
                None => "no-header-map".to_string(),
                Some(h) if h.semantics != claim.point.semantics => "differ (semantics)".to_string(),
                Some(h) => match first_frame_difference(&h.frame_state, &claim.point.frame_state) {
                    None => "match".to_string(),
                    Some(slot) => format!("differ ({slot})"),
                },
            };
            eprintln!(
                "[cratonvm-deopt] post-call header claim census at bci={} of {}: {verdict}",
                claim.bci, self.method_key
            );
        }
    }

    /// Settle every [`PostCallExitClaim`] of the walk, before the stubs are
    /// laid down:
    /// every point the walk will file is filed by now (the successor arms',
    /// the loop pre-headers', the constant-pool helper sites'), so each claim
    /// is judged by what is actually at its bci
    /// ([`PostCallExitClaimOutcome`]). A claim that keeps a site queues it
    /// for [`Self::emit_post_call_exit_stubs`] exactly as a wave-47 site
    /// was; its stub's `JNZ` resolves to the reason-7 stub of the ONE
    /// `OsrExit` map at its bci, its own or the shared one. Under
    /// `CRATONVM_DBG_DEOPT` each claim prints its outcome (the positive
    /// control of `L2W48PostCallExitClaims`).
    pub(super) fn resolve_post_call_exit_claims(&mut self) {
        let claims = std::mem::take(&mut self.post_call_exit_claims);
        // Wave 55: read once per compile that has a claim; method-entry
        // compiles only (the proposal's first stage keeps the OSR door, whose
        // transfer and exit classification read `OsrExit` maps by bci, out).
        // Wave 56: an OSR-tier compile too, under its own switch, once it
        // filed a loop-boundary or back-edge map (`can_osr_exit`, so the OSR
        // door transfers the exit; the door's by-bci readers learn the point
        // from `CompiledMethod::post_call_own_exit_bcis`).
        let own_point = !claims.is_empty()
            && (!self.mode_exit_polls
                || (!self.osr_exit_points.is_empty() && osr_post_call_own_point_exits_enabled()))
            && crate::deopt_real_enabled()
            && post_call_own_point_exits_enabled();
        for claim in claims {
            if self.failed {
                return;
            }
            let outcome = self.post_call_exit_claim_outcome(&claim, own_point);
            if cratonvm_types::flags::runtime_flag_on("CRATONVM_DBG_DEOPT") {
                let there: Vec<String> = self
                    .deopt_point_pcs
                    .iter()
                    .zip(&self.deopt_points)
                    .filter(|(&at, _)| at == claim.bci)
                    .map(|(_, p)| format!("{:?}/{}", p.reason, p.semantics))
                    .collect();
                eprintln!(
                    "[cratonvm-deopt] post-call exit claim at bci={} of {}: {outcome:?} \
                     (points there: {there:?})",
                    claim.bci, self.method_key,
                );
            }
            match outcome {
                PostCallExitClaimOutcome::Own => {
                    let bci = claim.bci;
                    let site = claim.site;
                    let box_ptr = self.record_built_deopt_point_in_order(bci, claim.point);
                    self.file_osr_exit_box(bci, box_ptr);
                    // Keyed only outside a splice, where every claim was made;
                    // checked anyway so a missing key can never bake the shared
                    // exit into this site's stub.
                    if self.osr_exit_box_ptr_by_bci.get(&bci).copied() == Some(box_ptr) {
                        self.post_call_exits_pending.push((site, bci));
                        self.note_debugger_exit_claim_kept(site, bci);
                    }
                }
                PostCallExitClaimOutcome::Shared => {
                    self.post_call_exits_pending.push((claim.site, claim.bci));
                    self.note_debugger_exit_claim_kept(claim.site, claim.bci);
                }
                PostCallExitClaimOutcome::OwnBeside => {
                    let bci = claim.bci;
                    let site = claim.site;
                    // Recorded (sorted by native offset), never filed by bci:
                    // the stub finds it through `post_call_own_box_ptr_by_bci`.
                    let box_ptr = self.record_built_deopt_point_in_order(bci, claim.point);
                    self.post_call_own_box_ptr_by_bci.insert(bci, box_ptr);
                    self.post_call_exits_pending.push((site, bci));
                    self.note_debugger_exit_claim_kept(site, bci);
                }
                PostCallExitClaimOutcome::Dropped => {}
            }
        }
    }

    /// Judge one claim against the points filed at its bci: the rethrow
    /// points (a `PendingException` frame, which neither by-bci reason lookup
    /// confuses with an `OsrExit` one) are ignored, and since wave 49 so are
    /// `REEXECUTE` guards of the claim's own frame
    /// ([`guard_admits_an_exit_map_beside`]); none left is
    /// [`PostCallExitClaimOutcome::Own`]; exactly one, the `OsrExit` map
    /// `osr_exit_box_ptr_by_bci` names, describing the claim's frame, is
    /// [`PostCallExitClaimOutcome::Shared`]; anything else is
    /// [`PostCallExitClaimOutcome::Dropped`].
    fn post_call_exit_claim_outcome(
        &self,
        claim: &PostCallExitClaim,
        own_point: bool,
    ) -> PostCallExitClaimOutcome {
        if claim.loop_header {
            // Wave 61: a loop header's map is the header's entry contract;
            // the claim may only share it.
            return match self.post_call_exit_claim_outcome_by_bci(claim) {
                PostCallExitClaimOutcome::Shared => PostCallExitClaimOutcome::Shared,
                _ => PostCallExitClaimOutcome::Dropped,
            };
        }
        match self.post_call_exit_claim_outcome_by_bci(claim) {
            PostCallExitClaimOutcome::Dropped
                if own_point && self.claim_may_bake_its_own_point(claim) =>
            {
                PostCallExitClaimOutcome::OwnBeside
            }
            outcome => outcome,
        }
    }

    /// May a claim the by-bci rule drops keep its own point beside what is
    /// at its bci ([`PostCallExitClaimOutcome::OwnBeside`])? Only when no
    /// `OsrExit` map is keyed there (no loop-boundary, back-edge or
    /// `invokedynamic` map a reader could take for this one), no other claim
    /// baked its own point there, and every non-rethrow point there is a
    /// guard of another reason that resumes as the claim's map does
    /// (`REEXECUTE`, same `resume_kind`, so `osr_exit::resume_image` stays
    /// unique at the bci). The guards keep their own stubs and frames; a
    /// cause-less by-bci lookup charges them, never this map
    /// (`osr_exit::trap_reason_at_bci`).
    fn claim_may_bake_its_own_point(&self, claim: &PostCallExitClaim) -> bool {
        use crate::deopt::DeoptReason;
        if self.osr_exit_box_ptr_by_bci.contains_key(&claim.bci)
            || self.post_call_own_box_ptr_by_bci.contains_key(&claim.bci)
        {
            return false;
        }
        let mut any = false;
        for (&at, p) in self.deopt_point_pcs.iter().zip(&self.deopt_points) {
            if at != claim.bci || p.semantics.rethrow_exception {
                continue;
            }
            if matches!(p.reason, DeoptReason::OsrExit | DeoptReason::UnreachedCode)
                || p.semantics.resume_kind() != claim.point.semantics.resume_kind()
            {
                return false;
            }
            any = true;
        }
        any
    }

    /// [`Self::post_call_exit_claim_outcome`] by the by-bci rule of waves
    /// 48-49 alone: `Own`, `Shared` or `Dropped`.
    fn post_call_exit_claim_outcome_by_bci(
        &self,
        claim: &PostCallExitClaim,
    ) -> PostCallExitClaimOutcome {
        use crate::deopt::DeoptReason;
        let mut others = self
            .deopt_point_pcs
            .iter()
            .enumerate()
            .filter(|(_, &at)| at == claim.bci)
            .filter_map(|(i, _)| Some((i, self.deopt_points.get(i)?)))
            .filter(|(_, p)| !p.semantics.rethrow_exception)
            // Wave 49: a guard of the claim's own frame is no obstacle
            // (`guard_admits_an_exit_map_beside`, false with the switch off).
            .filter(|(_, p)| {
                !guard_admits_an_exit_map_beside(p, &claim.point.frame_state, claim.point.semantics)
            });
        let Some((i, other)) = others.next() else {
            return if self.osr_exit_box_ptr_by_bci.contains_key(&claim.bci) {
                // A key with no point behind it: never shared, never replaced.
                PostCallExitClaimOutcome::Dropped
            } else {
                PostCallExitClaimOutcome::Own
            };
        };
        if others.next().is_some() || other.reason != DeoptReason::OsrExit {
            return PostCallExitClaimOutcome::Dropped;
        }
        let keyed = self.osr_exit_box_ptr_by_bci.get(&claim.bci).copied();
        let boxed = self.deopt_boxes.get(i).map(|b| std::ptr::addr_of!(**b));
        if keyed.is_none() || keyed != boxed {
            return PostCallExitClaimOutcome::Dropped;
        }
        if other.semantics == claim.point.semantics
            && post_call_exit_frames_match(&other.frame_state, &claim.point.frame_state)
        {
            PostCallExitClaimOutcome::Shared
        } else {
            PostCallExitClaimOutcome::Dropped
        }
    }

    /// The compile-wide conditions of a post-call exit site, shared with the
    /// constant-pool helper exit sites: the body's tier admits one (an
    /// OSR-tier compile, or a method-entry one under the wave-29 / wave-39
    /// rules in [`Self::emit_post_call_exit_site`]), it reserved a compile id
    /// (the stub names its body to the verdict), the compile has room under
    /// [`POST_CALL_EXIT_SITES_MAX`], and the walk is outside a splice.
    fn post_call_exit_site_may_be_emitted(&self) -> bool {
        !self.failed
            && self.post_call_exit_tier_admitted()
            && self.compile_id.id() != 0
            && self.post_call_exit_sites_queued() < POST_CALL_EXIT_SITES_MAX
            && self.inline_callee_scopes.is_empty()
    }

    /// The tier half of [`Self::post_call_exit_site_may_be_emitted`]: an
    /// OSR-tier compile, or a method-entry one under the wave-29 / wave-39
    /// rules.
    fn post_call_exit_tier_admitted(&self) -> bool {
        self.mode_exit_polls
            || (METHOD_ENTRY_POST_CALL_EXITS_ENABLED
                && (!self.osr_exit_points.is_empty()
                    || (METHOD_ENTRY_FIRST_MAP_POST_CALL_EXITS_ENABLED
                        && (self.keeps_a_call_record()
                            || (METHOD_ENTRY_UNSYNCHRONIZED_FIRST_MAP_POST_CALL_EXITS
                                && self.method_known_unsynchronized)))))
    }

    /// Every post-call exit site the walk queued so far, of every kind, for
    /// [`POST_CALL_EXIT_SITES_MAX`].
    fn post_call_exit_sites_queued(&self) -> usize {
        self.post_call_exits_pending.len()
            + self.post_call_exit_claims.len()
            + self.splice_post_call_exits.len()
    }

    /// After a REAL call the splice walk emitted inside a spliced body
    /// (`inlining.rs`, the invoke arm's `emit_inline_invoke`), with the walk
    /// standing at the callee's successor pc `next`: a post-call exit site
    /// whose `OsrExit` point leaves through a two-frame CHAIN -- the spliced
    /// callee at `next` with the call's result pushed, over the compile's own
    /// method parked in its `invoke` of the callee. Interpreter round i2 wave
    /// 59, lane L2: the single-pass stage of
    /// `docs/feature-designs/deopt-osr.md`,
    /// behind [`sp_post_call_splice_exits_enabled`].
    ///
    /// The three pieces the wave-54 triage named, and what each is here:
    ///
    /// * **a chain frame-state producer for the single-pass walk.** The
    ///   caller scope is the one `push_inline_scope` captured at the splice
    ///   (the compile's own method at its invoke, arguments popped, built by
    ///   `build_frame_state_at` like any root point; under the switch the
    ///   splice flushes the scratch registers BEFORE capturing it, so no
    ///   caller operand names a register the body clobbers). The callee frame
    ///   is built here from what IS known about a spliced body: its locals
    ///   are memory-homed at `callee_local_base + 8 i` and zeroed at the
    ///   splice (`try_emit_inline_body`), so a whole-body kind scan
    ///   (`bce::classify_local_kinds`) types each one exactly -- a slot never
    ///   written yet reads `0`/null, which is what an unassigned slot the
    ///   interpreter can never read may hold; a slot the scan calls
    ///   `Ambiguous` refuses the site. Its operand stack below the result
    ///   must be references (their oop marks are the width source); the
    ///   result is typed by the call's descriptor.
    /// * **a point key that is not a bci.** Nothing else files a point inside
    ///   a splice (the by-bci key space belongs to the compile's own method,
    ///   `may_file_by_bci`), so the point is recorded in `deopt_points` only
    ///   and its stub (tag [`SPLICE_POST_CALL_STUB_TAG`]) bakes it through
    ///   `splice_post_call_box_ptrs`, by index.
    /// * **a single-pass chain consumer.** None needed: the stash sinks
    ///   (the method-entry doors, the call-site service by point) rebuild a
    ///   chain from any artifact's point, by its `splice_scope_class_ids` /
    ///   `splice_scope_sources`, which this compile now keeps for the bodies
    ///   its points name (`driver.rs`); and the VM's verdict asks
    ///   `post_call_chain_exits_resumable` first, as for the optimizing tier.
    ///
    /// Admitted only where every piece is certain: a METHOD-ENTRY compile --
    /// or, since wave 62 under [`sp_osr_post_call_splice_exits_enabled`], an
    /// OSR-tier one that already filed a loop-boundary exit map, whose chain
    /// exit the OSR door transfers by its recorded point
    /// (`deopt_resume::transfer_osr_exit_chain_into_live_frame`, as for any
    /// chain guard of a single-pass splice) -- of an unsynchronized method that is
    /// no self-locking body, with a compile id, the deopt register region and
    /// `CRATONVM_DEOPT_REAL`; no loop rewrite; the OUTERMOST splice only (a
    /// nested splice pushes no scope: `try_emit_nested_inline`); `next` inside
    /// the callee and not one of its branch targets; under the site cap.
    /// Anything else emits nothing and files nothing.
    pub(super) fn emit_splice_post_call_exit_site(
        &mut self,
        site: &crate::InlineSite,
        next: usize,
        callee_branch_targets: &[bool],
        return_type: u8,
    ) {
        use crate::deopt::{FrameState, FrameValue};
        // Interpreter round i2 wave 60, lane L2: the census the "Still open"
        // shapes of the i39-L3 proposal wait for -- a real call inside a
        // NESTED single-pass splice, or inside a splice of a single-pass
        // OSR-tier compile. One `CRATONVM_DBG_JITC` line per such call, so a
        // run can count them (`grep sp-splice-post-call-exit-census | sort |
        // uniq -c`). Compile time only.
        // Wave 62: an OSR-tier compile is admitted under its own switch once it
        // filed a loop-boundary exit map, so the artifact is `can_osr_exit` and
        // the OSR door's chain transfer takes the exit
        // ([`sp_osr_post_call_splice_exits_enabled`]).
        let osr_tier_refused = self.mode_exit_polls
            && (self.osr_exit_points.is_empty() || !sp_osr_post_call_splice_exits_enabled());
        if dbg_jitc_enabled() && sp_post_call_splice_exits_enabled() {
            // A nested splice pushes a callee-local oop scope of its own but no
            // caller scope (`try_emit_nested_inline`).
            // Since the nested-splice stage, a nested call whose levels are
            // all describable gets its site and is no longer counted.
            let shape = if (self.inline_oop_scopes.len() > 1 || self.inline_callee_scopes.len() > 1)
                && !self.splice_scopes_admit_a_post_call_site()
            {
                Some("nested-splice")
            } else if osr_tier_refused && self.inline_callee_scopes.len() == 1 {
                Some("osr-tier-splice")
            } else {
                None
            };
            if let Some(shape) = shape {
                eprintln!(
                    "[cratonvm-jitc] sp-splice-post-call-exit-census {shape} outermost-callee={} in {}",
                    self.inline_callee_scopes.first().map_or("?", |s| s.key.as_str()),
                    self.method_key,
                );
            }
        }
        if !sp_post_call_splice_exits_enabled()
            || !POST_CALL_EXITS_ENABLED
            || !crate::deopt_real_enabled()
            || self.failed
            || osr_tier_refused
            || !self.post_call_exit_tier_admitted()
            || self.compile_id.id() == 0
            || self.post_call_exit_sites_queued() >= POST_CALL_EXIT_SITES_MAX
            || !self.splice_scopes_admit_a_post_call_site()
            || !self.method_known_unsynchronized
            || self.self_lock_obj_off > 0
            || self.bci_provenance.is_some()
            || self.deopt_regs_base == 0
            || next >= site.callee_code_len
            || callee_branch_targets.get(next).copied().unwrap_or(true)
        {
            // Wave 62: an admitted OSR-tier compile names the compile-wide
            // condition that still refused it (debug only, compile time).
            if self.mode_exit_polls && !osr_tier_refused && dbg_jitc_enabled() {
                let why = if self.bci_provenance.is_some() {
                    "loop-rewrite"
                } else if self.deopt_regs_base == 0 {
                    "no-deopt-register-region"
                } else if !self.method_known_unsynchronized || self.self_lock_obj_off > 0 {
                    "synchronized"
                } else if !self.splice_scopes_admit_a_post_call_site() {
                    "not-the-outermost-splice"
                } else if next >= site.callee_code_len
                    || callee_branch_targets.get(next).copied().unwrap_or(true)
                {
                    "successor"
                } else {
                    "compile-wide"
                };
                eprintln!(
                    "[cratonvm-jitc] sp-splice-post-call-exit REFUSED osr-tier {why}: callee={} bci={next} in {}",
                    self.inline_callee_scopes.first().map_or("?", |s| s.key.as_str()),
                    self.method_key,
                );
            }
            return;
        }
        // The frame as the `NOP` sees it: every operand in its frame word.
        self.flush_scratch_registers();
        // The innermost spliced callee: the outermost splice's scope, or the
        // innermost nested level's.
        let (key, max_locals, floor) = match self.sp_nested_splice_levels.last() {
            Some(level) => (
                level.key.clone(),
                level.max_locals,
                level.caller_stack_floor,
            ),
            None => {
                let Some(scope) = self.inline_callee_scopes.first() else {
                    return;
                };
                (
                    scope.key.clone(),
                    scope.max_locals,
                    scope.caller_stack_floor,
                )
            }
        };
        let Some(local_base) = self.inline_oop_scopes.last().map(|s| s.local_base) else {
            return;
        };
        let refuse = |why: &str, me: &Self| {
            if dbg_jitc_enabled() {
                eprintln!(
                    "[cratonvm-jitc] sp-splice-post-call-exit REFUSED {why}: callee={key} bci={next} in {}",
                    me.method_key,
                );
            }
        };
        let code_len = site.callee_code_len.min(site.callee_code.len());
        let kinds = super::bce::classify_local_kinds(&site.callee_code, code_len, max_locals);
        let mut locals = Vec::with_capacity(max_locals);
        for (i, &kind) in kinds.iter().enumerate() {
            // Cast: a local index of a spliced body (`max_locals` <= 65535).
            let off = local_base + (i as i32) * 8;
            let fv = match kind {
                super::LocalKind::Ref => FrameValue::StackSlotRef(-off),
                other => super::typed_local_frame_value(None, None, off, other),
            };
            if matches!(fv, FrameValue::Unsupported) {
                refuse("a callee local of no single kind", self);
                return;
            }
            locals.push(fv);
        }
        // The callee's own window of the shared operand stack.
        let n = self.stack.len();
        if floor > n || self.stack_oop_marks.len() != n {
            refuse("operand stack window", self);
            return;
        }
        let mut stack = Vec::with_capacity(n - floor);
        for i in floor..n {
            let StackSlot::Frame(off) = self.stack[i] else {
                refuse("an operand outside its frame word", self);
                return;
            };
            let is_oop = self.stack_oop_marks[i];
            let fv = if i + 1 == n && return_type != b'V' {
                match return_type {
                    b'L' | b'[' if is_oop => FrameValue::StackSlotRef(-off),
                    b'L' | b'[' => {
                        refuse("an unmarked reference result", self);
                        return;
                    }
                    _ if is_oop => {
                        refuse("a primitive result marked an oop", self);
                        return;
                    }
                    b'J' => FrameValue::StackSlotLong(-off),
                    b'D' => FrameValue::StackSlotDouble(-off),
                    b'F' => FrameValue::StackSlotFloat(-off),
                    _ => FrameValue::StackSlot(-off),
                }
            } else if is_oop {
                FrameValue::StackSlotRef(-off)
            } else {
                // No width source for a primitive below the result.
                refuse("a primitive operand below the result", self);
                return;
            };
            stack.push(fv);
        }
        let Some(mut caller) = self.inline_caller_chain() else {
            return;
        };
        // A nested splice's enclosing callees, outermost first, each parked
        // in its `invoke` of the next ([`NestedSpliceLevel`]).
        for level in &self.sp_nested_splice_levels {
            let Some(parked) = level.parked.as_ref() else {
                return;
            };
            let mut fs = parked.clone();
            fs.caller = Some(caller);
            caller = Box::new(fs);
        }
        if !splice_caller_scope_is_transferable(&caller) {
            let why = splice_caller_scope_refusal(&caller).unwrap_or_default();
            refuse(&format!("the caller scope ({why})"), self);
            return;
        }
        // Cast: a callee bci (< 65536).
        let bci = next as u32;
        let reason = crate::deopt::DeoptReason::OsrExit;
        let point = crate::deopt::DeoptimizationPoint {
            // Cast: buffer position to encoding offset.
            native_offset: self.buf.pos() as u32,
            bci,
            reason,
            action: crate::deopt::DeoptAction::Reinterpret,
            semantics: crate::deopt::ResumeSemantics::for_reason(reason),
            speculation_id: crate::deopt::speculation_id(bci, reason),
            frame_state: FrameState {
                method_key: key.clone(),
                bci,
                locals,
                stack,
                monitors: Vec::new(),
                caller: Some(caller),
            },
        };
        // Recorded under an emitter pc no instruction of THIS compile's own
        // method has: `next` is a CALLEE pc, and every by-pc reader of
        // `deopt_point_pcs` (the post-call claims' "what else is at my bci",
        // the back-edge admissions' "a point already there") asks about the
        // root method's pcs. Read by the loop-rewrite translation check only,
        // which never runs here (`bci_provenance` refused above).
        let box_ptr = self.record_built_deopt_point(SPLICE_POINT_EMITTER_PC, point);
        let nop = self.emit_post_call_exit_patch_nop();
        let mut padded = Vec::with_capacity(code_len + 2);
        padded.extend_from_slice(site.callee_code.get(..code_len).unwrap_or_default());
        padded.extend_from_slice(&[0, 0]);
        let source = (site.class_id != 0)
            .then(|| u16::try_from(site.callee_max_locals).ok())
            .flatten()
            .map(|max_locals| crate::SpliceScopeSource {
                method_key: key.clone(),
                class_id: site.class_id,
                code: std::sync::Arc::from(padded.into_boxed_slice()),
                max_locals,
                is_static: site.callee_is_static,
            });
        let sources = source
            .into_iter()
            .chain(
                self.sp_nested_splice_levels
                    .iter()
                    .filter_map(|level| level.enclosing_source.clone()),
            )
            .collect();
        self.splice_post_call_exits.push(SplicePostCallExit {
            site: nop,
            point: box_ptr,
            sources,
        });
        if dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] sp-splice-post-call-exit site nop={nop} callee={key} bci={next} in {}",
                self.method_key,
            );
        }
    }

    /// Do the open splices admit a post-call exit site inside the innermost
    /// one? The outermost splice's caller scope (exactly one), and either no
    /// nested level or, under [`sp_nested_post_call_splice_exits_enabled`], a
    /// describable [`NestedSpliceLevel`] for every nested level open.
    fn splice_scopes_admit_a_post_call_site(&self) -> bool {
        self.inline_callee_scopes.len() == 1
            && self.inline_scope_stack.len() == 1
            && self.inline_oop_scopes.len() == 1 + self.sp_nested_splice_levels.len()
            && (self.sp_nested_splice_levels.is_empty()
                || (sp_nested_post_call_splice_exits_enabled()
                    && self
                        .sp_nested_splice_levels
                        .iter()
                        .all(|level| level.parked.is_some())))
    }

    /// At a NESTED splice of `nested` inside the spliced body of `enclosing`,
    /// standing at the enclosing body's `invoke` with the arguments still on
    /// the operand stack: the [`NestedSpliceLevel`] a post-call exit site
    /// inside the nested body needs, or `None` (and nothing to push) when no
    /// such site could be admitted anyway (the switches, a compile the site's
    /// compile-wide rules refuse, a level that is not the next one down).
    /// Pushed by the caller (`inlining.rs::try_emit_nested_inline`), which
    /// pops it on both exits.
    ///
    /// The enclosing callee's frame is built as the wave-59 site builds a
    /// callee frame ([`Self::emit_splice_post_call_exit_site`]): every
    /// operand in its frame word (the nested body's first act is the same
    /// flush), its locals from its memory homes typed by
    /// `bce::classify_local_kinds` over its whole code (an `Ambiguous` local
    /// refuses), and its window of the operand stack below the arguments all
    /// references (their oop marks are the only width source). Its bci is the
    /// `invoke` itself; the VM computes the successor.
    pub(super) fn capture_nested_splice_level(
        &mut self,
        enclosing: &crate::InlineSite,
        nested: &crate::InlineSite,
        enclosing_invoke_pc: usize,
    ) -> Option<NestedSpliceLevel> {
        use crate::deopt::{FrameState, FrameValue};
        if !sp_nested_post_call_splice_exits_enabled()
            || !sp_post_call_splice_exits_enabled()
            || self.failed
            || self.inline_callee_scopes.len() != 1
            || self.inline_scope_stack.len() != 1
            || self.inline_oop_scopes.len() != 1 + self.sp_nested_splice_levels.len()
            || !self.method_known_unsynchronized
            || self.self_lock_obj_off > 0
            || self.compile_id.id() == 0
        {
            return None;
        }
        // The enclosing callee's identity and geometry: the outermost
        // splice's scope, or the innermost nested level's.
        let (enc_key, enc_max_locals, enc_floor) = match self.sp_nested_splice_levels.last() {
            Some(level) => (
                level.key.clone(),
                level.max_locals,
                level.caller_stack_floor,
            ),
            None => {
                let scope = self.inline_callee_scopes.first()?;
                (
                    scope.key.clone(),
                    scope.max_locals,
                    scope.caller_stack_floor,
                )
            }
        };
        let local_base = self.inline_oop_scopes.last()?.local_base;
        let key = format!(
            "{}.{}:{}",
            nested.class_name, nested.method_name, nested.descriptor
        );
        let n = self.stack.len();
        let caller_stack_floor = n.checked_sub(nested.callee_num_args)?;
        let describable = self
            .sp_nested_splice_levels
            .iter()
            .all(|l| l.parked.is_some())
            && enc_floor <= caller_stack_floor
            && self.stack_oop_marks.len() == n;
        let parked = if describable {
            self.flush_scratch_registers();
            let code_len = enclosing.callee_code_len.min(enclosing.callee_code.len());
            let kinds =
                super::bce::classify_local_kinds(&enclosing.callee_code, code_len, enc_max_locals);
            let mut locals = Vec::with_capacity(enc_max_locals);
            for (i, &kind) in kinds.iter().enumerate() {
                // Cast: a local index of a spliced body (`max_locals` <= 65535).
                let off = local_base + (i as i32) * 8;
                let fv = match kind {
                    super::LocalKind::Ref => FrameValue::StackSlotRef(-off),
                    other => super::typed_local_frame_value(None, None, off, other),
                };
                locals.push(fv);
            }
            let mut stack = Vec::with_capacity(caller_stack_floor - enc_floor);
            for i in enc_floor..caller_stack_floor {
                stack.push(match self.stack[i] {
                    StackSlot::Frame(off) if self.stack_oop_marks[i] => {
                        FrameValue::StackSlotRef(-off)
                    }
                    _ => FrameValue::Unsupported,
                });
            }
            let complete = !locals
                .iter()
                .chain(stack.iter())
                .any(|v| matches!(v, FrameValue::Unsupported));
            // Cast: a callee bci (< 65536).
            complete.then(|| FrameState {
                method_key: enc_key.clone(),
                bci: enclosing_invoke_pc as u32,
                locals,
                stack,
                monitors: Vec::new(),
                caller: None,
            })
        } else {
            None
        };
        if parked.is_none() && dbg_jitc_enabled() {
            eprintln!(
                "[cratonvm-jitc] sp-nested-splice-level UNDESCRIBABLE: {enc_key} at bci={enclosing_invoke_pc} splicing {key} in {}",
                self.method_key,
            );
        }
        let code_len = enclosing.callee_code_len.min(enclosing.callee_code.len());
        let enclosing_source = (parked.is_some() && enclosing.class_id != 0)
            .then(|| u16::try_from(enclosing.callee_max_locals).ok())
            .flatten()
            .map(|max_locals| {
                let mut padded = Vec::with_capacity(code_len + 2);
                padded.extend_from_slice(enclosing.callee_code.get(..code_len).unwrap_or_default());
                padded.extend_from_slice(&[0, 0]);
                crate::SpliceScopeSource {
                    method_key: enc_key.clone(),
                    class_id: enclosing.class_id,
                    code: std::sync::Arc::from(padded.into_boxed_slice()),
                    max_locals,
                    is_static: enclosing.callee_is_static,
                }
            });
        Some(NestedSpliceLevel {
            parked,
            enclosing_source,
            key,
            max_locals: nested.callee_max_locals,
            caller_stack_floor,
        })
    }

    /// Emit the patchable five-byte `NOP` of a site whose `OsrExit` map
    /// `branch_mode_exit_target` just recorded at `exit_bci`, and queue its
    /// stub for [`Self::emit_post_call_exit_stubs`].
    fn emit_post_call_exit_nop(&mut self, exit_bci: usize) {
        let site = self.emit_post_call_exit_patch_nop();
        self.post_call_exits_pending.push((site, exit_bci));
    }

    /// The patchable five-byte `NOP` of a post-call exit site, aligned so it
    /// sits inside one 8-aligned word; returns its buffer offset.
    fn emit_post_call_exit_patch_nop(&mut self) -> usize {
        // Five bytes inside one 8-aligned word, so the force is one aligned
        // store (`not_entrant::post_call_exit_jump` checks it again).
        // Cast: the site's absolute address, for its alignment only.
        let here = self.buf.as_ptr() as usize + self.buf.pos();
        let misalign = here % 8;
        if misalign > 8 - crate::ENTRY_PATCH_PAD.len() {
            self.buf.emit(post_call_exit_pad(8 - misalign));
        }
        let site = self.buf.pos();
        self.buf.emit(&crate::ENTRY_PATCH_PAD);
        site
    }

    /// Before a run-time constant-pool helper call at `pc` (the `ldc` String
    /// / Class arms, a deferred `new` / `anewarray`, `multianewarray`), with
    /// the instruction's operands still on the simulated stack: a patchable
    /// exit site whose `OsrExit` map is at `pc` itself, so the interpreter
    /// RE-EXECUTES the instruction (interpreter round i1 wave 44, lane L2;
    /// `interpreter-L2-proposal-exits-at-a-withdrawn-bodys-constant-pool-helper-calls-RETIRED-20261015`,
    /// behind [`CP_HELPER_EXITS_ENABLED`]).
    ///
    /// Everything but the map's position is the post-call site's: the NOP,
    /// the 16-byte stub, the register-preserving verdict tail
    /// (`POST_CALL_EXIT_VERDICT_ONLY`: asked, never parked), the cap, and the
    /// force pass that rewrites the NOP when the body is withdrawn
    /// (`JitCache::force_withdrawn_exit_polls`, which reads
    /// `CompiledMethod::post_call_exit_sites`). So nothing runs until the
    /// body is withdrawn, and a withdrawn body leaves here BEFORE the helper
    /// runs: nothing of the instruction happened yet (no class resolved or
    /// initialised, nothing allocated), and the interpreter runs it once, on
    /// the frame it moved onto the class's current body, against that body's
    /// pool. A body a redefinition did not withdraw keeps the helper and its
    /// translation (`vm::jit::helpers::CpSite`).
    ///
    /// Refused, with nothing emitted or filed: whatever
    /// [`Self::post_call_exit_site_may_be_emitted`] refuses; `pc` a branch
    /// target (a loop header files its own map there, and a map this site
    /// filed first would become the header's for `mode_exit_target`); and
    /// whatever [`Self::branch_mode_exit_target`] refuses for a map at `pc`
    /// with the whole current stack as its operands (a point already at `pc`,
    /// a loop rewrite, no deopt register region, a frame the transfer would
    /// not take, an elided monitor or a self-lock). The instruction's own
    /// points at `pc` come after: the allocation guard's precise frame is a
    /// `RETHROW` point, which neither by-bci reason lookup confuses with this
    /// `REEXECUTE` one (`osr_exit::deopt_reason_at_bci`,
    /// `exceptional_reason_at_bci`), and it is filed in its own by-bci map.
    pub(super) fn emit_cp_helper_exit_site(&mut self, pc: usize, is_branch_target: bool) {
        if !CP_HELPER_EXITS_ENABLED
            || !POST_CALL_EXITS_ENABLED
            || is_branch_target
            || !self.post_call_exit_site_may_be_emitted()
        {
            return;
        }
        // The map describes the frame as the NOP sees it, as the conditional
        // back edge's does after its arm's flush: every operand-stack entry
        // in its frame word. Every helper arm this precedes flushes before
        // its call anyway (`emit_pre_safepoint_spill`, or the arm's own
        // flush), so this moves no work onto a path that had none.
        self.flush_scratch_registers();
        let operands = self.stack.len();
        let Some(exit_bci) = self.branch_mode_exit_target(pc, operands) else {
            return;
        };
        self.emit_post_call_exit_nop(exit_bci);
        self.cp_helper_exit_sites = self.cp_helper_exit_sites.saturating_add(1);
    }

    /// Does this compile keep a dispatch record its artifact will own
    /// (`CompiledMethod::_jit_invoke_infos` from `invoke_info`,
    /// `_jit_mic_slots` / `_jit_pic_slots` from `mic_slots` / `pic_slots`),
    /// so that the VM reads the body as one that calls something
    /// (`jit_bridge::wrapped_body_attempt_never_reruns`)? See
    /// [`METHOD_ENTRY_FIRST_MAP_POST_CALL_EXITS_ENABLED`].
    fn keeps_a_call_record(&self) -> bool {
        !self.invoke_info.is_empty()
            || !self.mic_slots.is_empty()
            || !self.pic_slots.is_empty()
            // 2026-10-07 (item 1 of the i24-L6 page): a call the door bound
            // directly, a cycle cell, or a splice's own call target keeps a
            // record in the artifact too, which these tables miss
            // (`BackendRequest::artifact_keeps_a_call_record`).
            || self.artifact_keeps_a_call_record
    }

    /// Lay down the stubs of every post-call exit site the walk emitted,
    /// after the walk and before `emit_deopt_stubs` (which resolves each
    /// stub's `JNZ` to its successor's reason-7 stub), and record `(site,
    /// stub)` for `CompiledMethod::post_call_exit_sites`. Nothing when no
    /// site was emitted.
    ///
    /// Per site, 16 bytes:
    ///
    /// ```text
    /// stub:  CALL tail           ; E8 rel32 -- the verdict, in the flags
    ///        JNZ  <reason-7 stub of the successor's OsrExit map>
    ///        JMP  <site + 5>     ; stay: back past the NOP
    /// ```
    ///
    /// and once per compile the tail ([`Self::emit_post_call_exit_verdict_tail`]).
    pub(super) fn emit_post_call_exit_stubs(&mut self) {
        self.resolve_post_call_exit_claims();
        if !self.post_call_header_claim_census.is_empty() {
            self.report_post_call_header_claim_census();
        }
        let pending = std::mem::take(&mut self.post_call_exits_pending);
        let splice_sites = std::mem::take(&mut self.splice_post_call_exits);
        if (pending.is_empty() && splice_sites.is_empty()) || self.failed {
            return;
        }
        let tail = self.buf.pos();
        self.emit_post_call_exit_verdict_tail();
        // Wave 59 (lane L2): the sites after a real call inside a splice. The
        // same 16-byte stub; its `JNZ` goes to a tag-14 stub that bakes the
        // site's own chain point, found by index (the point has no bci in
        // this compile's key space).
        for exit in splice_sites {
            let stub = self.buf.pos();
            self.buf.emit_byte(0xE8); // CALL rel32 -> the tail
            let call_patch = self.buf.pos();
            self.buf.emit(&[0u8; 4]);
            let call_rel = (tail as i32) - (call_patch as i32 + 4); // Cast: x86-64 rel32 displacement
            self.buf.try_patch_i32(call_patch, call_rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
            let leave = self.emit_jcc_rel32_patch(0x85);
            let index = self.splice_post_call_box_ptrs.len();
            self.splice_post_call_box_ptrs.push(exit.point);
            self.deopt_stubs
                .push((leave, index, SPLICE_POST_CALL_STUB_TAG));
            let back = self.emit_jmp_rel32_patch();
            let resume = exit.site + crate::ENTRY_PATCH_PAD.len();
            let back_rel = (resume as i32) - (back as i32 + 4); // Cast: x86-64 rel32 displacement
            self.buf.try_patch_i32(back, back_rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
            if let (Ok(site), Ok(stub)) = (u32::try_from(exit.site), u32::try_from(stub)) {
                self.post_call_exit_sites.push((site, stub));
            }
            self.splice_post_call_sources.extend(exit.sources);
        }
        for (site, exit_bci) in pending {
            let stub = self.buf.pos();
            self.buf.emit_byte(0xE8); // CALL rel32 -> the tail
            let call_patch = self.buf.pos();
            self.buf.emit(&[0u8; 4]);
            let call_rel = (tail as i32) - (call_patch as i32 + 4); // Cast: x86-64 rel32 displacement
            self.buf.try_patch_i32(call_patch, call_rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
                                                               // JNZ -> the successor's reason-7 stub (`emit_deopt_stubs` bakes its
                                                               // `osr_exit_box_ptr_by_bci` map, the one `branch_mode_exit_target`
                                                               // recorded for this site), or, for a claim settled `OwnBeside`
                                                               // (wave 55), the tag-13 stub that bakes the claim's own point.
            let leave = self.emit_jcc_rel32_patch(0x85);
            let tag = if self.post_call_own_box_ptr_by_bci.contains_key(&exit_bci) {
                POST_CALL_OWN_POINT_STUB_TAG
            } else {
                7 // OSR-exit
            };
            self.deopt_stubs.push((leave, exit_bci, tag));
            let back = self.emit_jmp_rel32_patch();
            let resume = site + crate::ENTRY_PATCH_PAD.len();
            let back_rel = (resume as i32) - (back as i32 + 4); // Cast: x86-64 rel32 displacement
            self.buf.try_patch_i32(back, back_rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
            if let (Ok(site), Ok(stub)) = (u32::try_from(site), u32::try_from(stub)) {
                self.post_call_exit_sites.push((site, stub));
            }
        }
    }

    /// The shared tail every post-call exit stub `CALL`s: ask the safepoint
    /// slow path for this body's verdict WITHOUT parking
    /// ([`crate::POST_CALL_EXIT_VERDICT_ONLY`]), with every register the
    /// site's state lives in preserved, and return with the flags of
    /// `TEST AL, <the verdict bit the body's polls test>`.
    ///
    /// ```text
    /// tail:  PUSH RAX RCX RDX RBX RSI RDI R8 R9 R10 R11
    ///        MOV  RBX, RSP            ; callee-saved: survives the CALL
    ///        AND  RSP, -16
    ///        SUB  RSP, 0x120          ; home area + 16 XMM slots
    ///        MOVDQU [RSP+0x20+16n], XMMn     (n = 0..15)
    ///        MOV  ARG0, <safepoint flag>     ; names the VM
    ///        MOV  ARG1, <compile id> | POST_CALL_EXIT_VERDICT_ONLY
    ///        MOV  RAX, <safepoint slow path> ; CALL RAX
    ///        MOVDQU XMMn, [RSP+0x20+16n]
    ///        MOV  RSP, RBX
    ///        TEST AL, <bit>
    ///        POP  R11 R10 R9 R8 RDI RSI RBX RDX RCX RAX   ; POP keeps the flags
    ///        RET                                         ; so does RET
    /// ```
    ///
    /// Why no spill and no oop map: the helper does not park in this mode, so
    /// this thread never stops for a collection with the frame's references
    /// only in registers or in the tail's save area. A stop-the-world request
    /// meanwhile finds it either in Rust (the take-over resumes such a thread
    /// and waits for it to arrive cooperatively: at the body's next poll, or
    /// through the exit) or back in this code, where the take-over freezes it
    /// and scans its registers and stack conservatively, and that collection
    /// does not move (`vm/src/jit/xt_root_scan.rs`) -- exactly as for a thread
    /// between two polls of any compiled loop. The site's state is every GPR
    /// and XMM as the call's lowering left them
    /// (RBP, R12-R15 are callee-saved in both ABIs and the helper keeps them;
    /// the flags are dead between two bytecodes). Nothing below RSP is live
    /// there: the call that just returned owned it.
    fn emit_post_call_exit_verdict_tail(&mut self) {
        // PUSH RAX, RCX, RDX, RBX, RSI, RDI, then R8-R11.
        self.buf.emit(&[0x50, 0x51, 0x52, 0x53, 0x56, 0x57]);
        self.buf
            .emit(&[0x41, 0x50, 0x41, 0x51, 0x41, 0x52, 0x41, 0x53]);
        self.buf.emit(&[0x48, 0x89, 0xE3]); // MOV RBX, RSP
        self.buf.emit(&[0x48, 0x83, 0xE4, 0xF0]); // AND RSP, -16
        self.buf.emit(&[0x48, 0x81, 0xEC]); // SUB RSP, imm32
        self.buf.emit(&POST_CALL_EXIT_TAIL_FRAME.to_le_bytes());
        for xmm in 0u8..16 {
            self.emit_post_call_exit_xmm(0x7F, xmm); // MOVDQU [RSP+..], XMMn
        }
        // Cast: the flag byte's address, as the poll passes it.
        self.emit_mov_imm64(ARG_REGS[0], self.helpers.safepoint_flag_addr as i64);
        self.emit_mov_imm64(
            ARG_REGS[1],
            i64::from(self.compile_id.id()) | crate::POST_CALL_EXIT_VERDICT_ONLY,
        );
        cratonvm_jit_api::assert_helper_call_shape!(
            "safepoint_slow_path",
            int_args = 2,
            returns_value = true
        );
        // Cast: helper address, baked as an immediate.
        self.emit_mov_imm64(RAX, self.helpers.safepoint_slow_path as i64);
        self.buf.emit(&[0xFF, 0xD0]); // CALL RAX
        for xmm in 0u8..16 {
            self.emit_post_call_exit_xmm(0x6F, xmm); // MOVDQU XMMn, [RSP+..]
        }
        self.buf.emit(&[0x48, 0x89, 0xDC]); // MOV RSP, RBX
                                            // The bit the body's own exit polls test (`emit_safepoint_poll_leaving_to`).
        let bit = if self.mode_exit_polls {
            crate::SAFEPOINT_VERDICT_INNERMOST_FRAME
        } else {
            crate::SAFEPOINT_VERDICT_POLLING_BODY
        };
        // Cast: the verdict bit is below 0x100 (x86-64 imm8).
        self.emit_test_r8_imm8(RAX, bit as u8);
        // POP R11-R8, then RDI, RSI, RBX, RDX, RCX, RAX.
        self.buf
            .emit(&[0x41, 0x5B, 0x41, 0x5A, 0x41, 0x59, 0x41, 0x58]);
        self.buf.emit(&[0x5F, 0x5E, 0x5B, 0x5A, 0x59, 0x58]);
        self.buf.emit_byte(0xC3); // RET
    }

    /// `MOVDQU` between XMM register `xmm` and its save slot
    /// `[RSP + 0x20 + 16 * xmm]` of the verdict tail: `opcode` `0x7F` stores,
    /// `0x6F` loads (`F3 [REX.R] 0F op ModRM(mod=10, reg, rm=SIB) 24 disp32`).
    fn emit_post_call_exit_xmm(&mut self, opcode: u8, xmm: u8) {
        self.buf.emit_byte(0xF3);
        if xmm >= 8 {
            self.buf.emit_byte(0x44); // REX.R
        }
        self.buf
            .emit(&[0x0F, opcode, 0x84 | ((xmm & 7) << 3), 0x24]);
        let disp: i32 = 0x20 + 16 * i32::from(xmm);
        self.buf.emit(&disp.to_le_bytes());
    }
}

// ---------------------------------------------------------------------------
// Round 15 wave 1 (lane calls, proposal C14W3-5 of `jit-r14-calls3-proposals-RETIRED-20260930.md`):
// the direct-call sentinel path out of line.
// ---------------------------------------------------------------------------
//
// A baked direct `invokestatic` used to end in
//
//     CALL callee ; CMP RAX,1 ; JNO .keep ; <callee-deopt service check> ;
//     <exception check> ; .keep:
//
// so every call that returned normally (all of them, in practice) took a
// branch over ~50 bytes of cold code. With the switch on it ends in
//
//     CALL callee ; CMP RAX,1 ; JO .tail ; .keep:
//
// and `.tail` (emitted after the walk, before the exception-check and deopt
// stubs, by `emit_sp_call_cold_tails`) holds the same two checks, emitted by the
// same functions, followed by `JMP .keep`. The machine state on every edge is
// what it was: the tail runs on exactly the edge the inline checks ran on, in
// the same order, and the checks read nothing the walk changes between the site
// and the end of the method except `dbg_last_pc` / `cur_bc_pc`, which the tail
// record carries and restores.
//
// What the admission (`sp_call_cold_tail_admitted`) keeps out, and why:
//  * a site inside a natively unrolled loop: the unroller copies the loop's
//    machine code and replicates every late-patch list it knows, and this one
//    is not among them (a copy's `JO` would land on the original's tail, which
//    jumps back into the ORIGINAL body);
//  * a compile of rewritten bytecode (`bci_provenance`): same duplication, done
//    on bytecode;
//  * a protected pc: the exception check there publishes a reason-9 frame or
//    takes a local-handler stub, both of which snapshot the walk's state AT the
//    site (`build_and_record_deopt_point`), which the end of the method no
//    longer has;
//  * a site with an inline plan or inside a splice: a splice attempt that rolls
//    back rewinds the buffer, and this list is in no rollback checkpoint;
//  * a caller-held synchronized site (the release sits on the cold edge).
// Anything refused keeps the inline form, byte for byte.

/// `CRATONVM_JIT_SP_CALL_COLD_TAILS` (default OFF, opt-in; round 15 wave 1,
/// lane calls, C14W3-5): a single-pass direct `invokestatic` puts its
/// callee-deopt service check and exception check out of line. Off, the site is
/// emitted exactly as before. Read per site compile, so it adds no process
/// global. Default off until `bench14.sh` prices it (a taken branch per call
/// against the tail's extra `JMP` on the rare sentinel edge).
fn sp_call_cold_tails_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_on("CRATONVM_JIT_SP_CALL_COLD_TAILS")
}

/// `Jcc` condition byte for "RAX was the sentinel" after
/// [`Compiler::emit_cmp_rax_sentinel`] (`JO`).
const SP_COLD_TAIL_JO: u8 = 0x80;

/// Which callee-deopt service the out-of-line tail emits
/// (`emit_inline_callee_deopt_check` / `_owned_args`, or none).
#[derive(Clone, Copy)]
pub(super) enum SpCallColdService {
    Args {
        info: *const crate::JitInvokeInfo,
        n: usize,
        args_base: i32,
    },
    OwnedArgs {
        info: *const crate::JitInvokeInfo,
    },
    Unserviced,
}

/// One deferred cold tail: the hot path's `JO` rel32, where the hot path
/// resumes, and what the tail must emit on the way back.
pub(super) struct SpCallColdTail {
    jo_patch: usize,
    keep: usize,
    service: SpCallColdService,
    ret_type: u8,
    throw_bci: usize,
    bc_pc: usize,
}

impl Compiler {
    /// May the direct call at `pc` take the out-of-line cold tail? See the
    /// section comment for each term.
    fn sp_call_cold_tail_admitted(&self, pc: usize) -> bool {
        sp_call_cold_tails_enabled()
            && merged_call_sentinel_enabled()
            && self.bci_provenance.is_none()
            && self.inline_scope_stack.is_empty()
            && !self.inline_sites.contains_key(&pc)
            && !self.pc_is_protected(pc)
            && !self.pc_is_protected(self.dbg_last_pc)
            && !self
                .unroll_loops
                .iter()
                .any(|&(a, b, _)| a.min(b) <= pc && pc <= a.max(b))
    }

    /// The hot half at the site: `CMP RAX,1 ; JO .tail`, and the record the
    /// tail is emitted from. The fall-through is `.keep`, a join (the tail
    /// jumps back to it), so the reload-elision mirror is dropped here as
    /// `patch_rel32_to_here` would. Counted as a post-invoke check at the site,
    /// where the walk reads the count (`emit_post_call_exit_site`).
    fn emit_sp_call_cold_tail_branch(&mut self, service: SpCallColdService, ret_type: u8) {
        self.emit_cmp_rax_sentinel();
        let jo_patch = self.emit_jcc_rel32_patch(SP_COLD_TAIL_JO);
        self.slot_mirror = None;
        self.post_invoke_checks_emitted = self.post_invoke_checks_emitted.wrapping_add(1);
        self.sp_call_cold_tails.push(SpCallColdTail {
            jo_patch,
            keep: self.buf.pos(),
            service,
            ret_type,
            throw_bci: self.dbg_last_pc,
            bc_pc: self.cur_bc_pc,
        });
    }

    /// Emit every deferred cold tail. Called by `compile_bytecode` after the
    /// walk and BEFORE `emit_local_handler_stubs` / `emit_exception_check_stub`
    /// / `emit_deopt_stubs`, which consume the edges the tails' exception
    /// checks record.
    pub(super) fn emit_sp_call_cold_tails(&mut self) {
        if self.sp_call_cold_tails.is_empty() {
            return;
        }
        let tails = std::mem::take(&mut self.sp_call_cold_tails);
        let (last_pc, bc_pc, checks) = (
            self.dbg_last_pc,
            self.cur_bc_pc,
            self.post_invoke_checks_emitted,
        );
        for tail in tails {
            // Also drops the reload-elision mirror: the tail is a join.
            self.patch_rel32_to_here(tail.jo_patch);
            self.dbg_last_pc = tail.throw_bci;
            self.cur_bc_pc = tail.bc_pc;
            match tail.service {
                SpCallColdService::Args { info, n, args_base } => {
                    self.emit_inline_callee_deopt_check(info, n, args_base)
                }
                SpCallColdService::OwnedArgs { info } => {
                    self.emit_inline_callee_deopt_check_owned_args(info)
                }
                SpCallColdService::Unserviced => {}
            }
            self.emit_post_invoke_exception_check(tail.ret_type);
            // JMP rel32 back to `.keep`.
            let back = self.emit_jmp_rel32_patch();
            let rel = (tail.keep as i32) - (back as i32 + 4); // Cast: x86-64 rel32 displacement
            self.buf.try_patch_i32(back, rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
        }
        self.dbg_last_pc = last_pc;
        self.cur_bc_pc = bc_pc;
        self.post_invoke_checks_emitted = checks;
        self.slot_mirror = None;
    }
}

impl Compiler {
    /// JIT round 16 (lane throwpath, TP-2): how does the String access
    /// intrinsic at `pc` (`length`, `isEmpty`, `charAt`, `hashCode`) treat a
    /// null receiver?
    ///
    /// The deopt (stub reason 6, `ReceiverTypeChanged`) handed the rest of the
    /// activation to the interpreter at every null receiver, and its
    /// `RecompileAndReinterpret` produced the same arm again: in
    /// `R16ThrowpathPlain` `npe-invoke` every one of the 60 003 caught NPEs of
    /// `vNullStr.length()` was raised by the interpreter after the first.
    /// With `CRATONVM_JIT_STRING_INTRINSIC_NPE=1` the NPE is raised in
    /// compiled code instead, as the array opcodes raise theirs:
    ///
    /// * [`StringNullReceiver::SharedStub`]: the shared null-check stub
    ///   (`jit_npe_with_action` with the site's trap key, then the implicit
    ///   local-handler probe).
    /// * [`StringNullReceiver::PreciseFrame`] (JIT round 16 wave 12, lane
    ///   throw3): inside a protected range of a method compiled with precise
    ///   exceptional frames, the reason-10 stub the array opcodes take there
    ///   (`emit_precise_array_npe_check`): the frame at this bci is published,
    ///   so a handler that reads a local the range wrote sees its value.
    ///   Wave 11 found the switch measured "no gain" because it never engaged
    ///   where it was measured: `npeInvoke`'s handler reads `c`, written in
    ///   the range, so the method compiles with precise frames and the site
    ///   is protected -- the old rule kept the deopt there (code length 1466
    ///   bytes in both arms, and `CRATONVM_DBG_DEOPT=1` showed the same
    ///   `ReceiverTypeChanged` deopts with the switch on, escalating to
    ///   `MakeNotCompilable`).
    ///
    /// Not inside a splice (the stubs' local-handler probe range-tests the bci
    /// against THIS method's exception table, and the precise stub publishes
    /// THIS method's frame): that keeps the deopt. Not memoised
    /// (`process_global_statics_ratchet`): read per String intrinsic site of a
    /// compile.
    pub(super) fn string_intrinsic_null_receiver_raises_npe(
        &self,
        pc: usize,
    ) -> StringNullReceiver {
        string_null_receiver_arm(
            string_intrinsic_npe_enabled(),
            !self.inline_scope_stack.is_empty(),
            self.precise_exception_frames && self.pc_is_protected(pc),
        )
    }
}

/// [`Compiler::string_intrinsic_null_receiver_raises_npe`]'s rule on its
/// inputs: the switch, a splice, and "a protected site of a method compiled
/// with precise exceptional frames".
fn string_null_receiver_arm(
    enabled: bool,
    in_splice: bool,
    precise_protected: bool,
) -> StringNullReceiver {
    if !enabled || in_splice {
        StringNullReceiver::Deopt
    } else if precise_protected {
        StringNullReceiver::PreciseFrame
    } else {
        StringNullReceiver::SharedStub
    }
}

/// [`Compiler::string_intrinsic_null_receiver_raises_npe`]'s answer.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(super) enum StringNullReceiver {
    /// The reason-6 guard deopt (the default).
    Deopt,
    /// The shared null-check stub: the NPE in compiled code, frame-less.
    SharedStub,
    /// The reason-10 precise-frame NPE stub (a protected site of a method
    /// compiled with precise exceptional frames).
    PreciseFrame,
}

/// `CRATONVM_JIT_STRING_INTRINSIC_NPE` (JIT round 16, lane throwpath, TP-2;
/// default ON since wave 13: npe-invoke 4331 -> 2473 ns, helpful message kept
/// under load 40/40; `=0` off). See [`Compiler::string_intrinsic_null_receiver_raises_npe`].
fn string_intrinsic_npe_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_STRING_INTRINSIC_NPE")
}

/// `CRATONVM_JIT_STRING_HASH_CACHE_WRITE` (JIT round 16, lane strings,
/// STR16-1; **default ON**, `=0` is the kill switch): the inline
/// `String.hashCode()` body stores a non-zero computed hash back into a
/// COMPACT receiver's `hash` field, as the JDK body does. A correctness fix
/// (the field is reflection-visible, and HotSpot's holds the hash after the
/// first call) that is also the fix for an O(n)-per-call re-hash. Not
/// memoised (`process_global_statics_ratchet`): read once per `hashCode`
/// intrinsic site of a compile.
fn string_hash_cache_write_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_STRING_HASH_CACHE_WRITE")
}

/// `CRATONVM_JIT_SB_APPEND_INT_NEGATIVE` (JIT round 16, lane strings,
/// STR16-3; **default ON** since the strings round `str16`, 2026-10-06:
/// `appNegInt` 529 -> 417 ns, `negInt` 2 981 -> 2 290 ns, medians of 5
/// interleaved on the loaded Linux host, `R16StringsDigits` /
/// `R16StringsIdentity` PASS; `=0` is the kill switch): the inline
/// `StringBuilder.append(int)` body serves a NEGATIVE value too — the
/// magnitude through the same unsigned digit loop (`NEG` of
/// `Integer.MIN_VALUE` is `0x8000_0000`, whose unsigned rendering is the
/// right 2147483648), then one `'-'` byte in front. Without it every negative
/// argument declines into the ordinary call, whose JDK body
/// (`DecimalDigits.uncheckedGetCharsLatin1` -> `Unsafe.putByte` per digit)
/// MEASURED 3 480 ns/op against 235 for a non-negative one
/// (`R16StringsSplit` rows `appNegInt` / `appInt`). Not memoised: read once
/// per `append(int)` intrinsic site of a compile.
fn sb_append_int_negative_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SB_APPEND_INT_NEGATIVE")
}

/// `CRATONVM_JIT_SB_GROW` (strings round 2, `str17`; default ON, `=0`
/// restores the decline edge): the `StringBuilder` append intrinsics grow a
/// full LATIN1 payload through `DirectHelperTable::sb_grow` and run their body
/// again (`emit_sb_grow_stub`), instead of declining into the generic
/// dispatcher and the JDK's compiled growth chain -- ~2 400 cycles a growth,
/// on 29% of `R16Bench strings`' iterations. Read once per append intrinsic
/// site of a compile.
fn sb_grow_enabled() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_SB_GROW")
}

/// What the inline `StringBuilder.toString()` body bakes at compile time
/// (JIT round 17 wave 1, lane strings, STR16-P1): the `java/lang/String`
/// compact recipe it allocates against, or the reason it emits only a decline.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct SbToStringPlan {
    /// `java/lang/String`'s header class id.
    pub(super) string_class_id: u32,
    /// The compact String's TOTAL size (8-byte header included), a multiple
    /// of 8.
    pub(super) string_total: i32,
    /// `String.value`'s compact displacement: a bare 8-byte pointer.
    pub(super) value_off: i32,
    /// Address and compile-time value of String's layout-replace counter.
    pub(super) replace_guard: (usize, u32),
    /// The largest `count` served inline: both objects stay under the inline
    /// array cap the allocator itself honours.
    pub(super) max_count: i32,
    /// `ARRAY_LENGTH_OFFSET` / `ARRAY_DATA_OFFSET` / `KIND_TAGS_BYTE_OFFSET`
    /// as disp8 bytes (all screened to `0..=127`).
    pub(super) len_d8: u8,
    pub(super) data_d8: u8,
    kind_d8: u8,
    /// The `KIND_TAGS_BYTE_OFFSET` byte of every `byte[]` (bits 6..7 are
    /// reserved zero on arrays; `primitive_array_kind_tags_byte("[B")`).
    byte_array_tag: u8,
    /// The mark word of a fresh `byte[]` (`ObjectHeader::new`'s own bits).
    pub(super) byte_array_mark: i32,
    /// `String.coder`'s compact `(offset, is_byte)`, for the UTF16 arm
    /// (round 17 wave 2, lane sbzgc, `CRATONVM_JIT_SB_TOSTRING_UTF16`), which
    /// stores `coder = UTF16` into the fresh String; `None` refuses that arm
    /// only. A 1- or 4-byte slot inside the String's body, at the layout's own
    /// offset, with the `+1` high-byte probe of the scan still a disp8.
    pub(super) utf16_coder: Option<(i32, bool)>,
}

/// Which collector obligations the inline `toString()` discharges at a site
/// (JIT round 17 wave 2, lane sbzgc), chosen at compile time by
/// [`sb_to_string_gc_arm`].
///
/// Both extra checks run BEFORE the first store and decline into the ordinary
/// call, so the fast path stays call-free on every backend (no safepoint map,
/// no OOM routing, no spill discipline), and both are proofs that the
/// collector's own barrier for the single reference store, `String.value =
/// the byte[]`, would have done nothing:
///
/// * Generational: a fresh young receiver needs no card, a null old value no
///   SATB entry (the wave-1 premise; no run-time check).
/// * ZGC (`zgc_start_bits`): both objects are announced with the inline
///   start-bit store -- BEFORE the commit since nio21 wave 10 L1
///   (`CRATONVM_ZGC_JIT_START_BIT_BEFORE_COMMIT`; after it with `=0`),
///   exactly as `emit_inline_tlab_new` /
///   `emit_inline_tlab_newarray` announce one, with every condition of the
///   table's contract checked first. `blocked == 0` is one of them, and it
///   means no mark is running (`ZgcRealHeap::set_field` publishes an SATB
///   entry only under `mark_active`, and the old value is the TLAB's zero
///   anyway) and the heap is not generational (`note_ref_store` cards only
///   with `has_old_objects`). No colour bits: this ZGC never arms its load
///   barrier (`docs/GC.md`, backend table).
/// * G1 (`g1_same_region`): `post_write_barrier_rset` returns without a card
///   or a remembered-set edge for a same-region store, and the SATB
///   pre-barrier logs nothing for a null old value; the run-time check is
///   that same-region test, `((S - base) ^ (A - base)) & region_mask == 0`,
///   against the published `JIT_G1_BARRIER` table. Objects above TAMS are
///   implicitly live, as for every inline `new` on G1.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct SbToStringGc {
    /// ZGC: the call-free start-bit pre-check and both start bits.
    pub(super) zgc_start_bits: bool,
    /// A live G1 table: the same-region pre-check.
    pub(super) g1_same_region: bool,
}

/// What one emitted copy of [`Compiler::emit_sb_to_string_tail`] builds (JIT
/// round 17 wave 6, lane sbzgc2): the String's coder, whether the copy
/// narrows a UTF16 payload to LATIN1, and which
/// [`crate::metrics::SB_TO_STRING_CENSUS`] row counts it when counting is on.
#[derive(Clone, Copy, Debug)]
pub(super) struct SbToStringArm {
    /// `Some` stores `coder = UTF16` at that `(offset, is_byte)`; `None`
    /// leaves the zeroed LATIN1.
    pub(super) utf16_coder: Option<(i32, bool)>,
    /// ECX chars of the UTF16 source in RDX copied as their low bytes (the
    /// compress, `CRATONVM_JIT_SB_TOSTRING_COMPRESS`), rather than ECX bytes.
    pub(super) narrow: bool,
    /// The run-time `taken-*` row.
    pub(super) taken_row: usize,
}

/// The compile-time facts [`sb_to_string_gc_arm`] decides from, gathered by
/// the emitter (and spelled out by the unit tests).
#[derive(Clone, Copy, Debug)]
pub(super) struct SbToStringGcInputs {
    /// `jit_tlab_registration_required()`: ZGC.
    pub(super) zgc_registration: bool,
    /// `CRATONVM_ZGC_JIT_INLINE_ANNOUNCE` (the collector publishes its table).
    pub(super) zgc_start_bit_requested: bool,
    /// `CRATONVM_JIT_IR_ZGC_INLINE_ARRAY_ANNOUNCE`, the inline array lever.
    pub(super) zgc_array_announce: bool,
    /// `g1_barrier_table_live`: a G1 collector published its geometry.
    pub(super) g1_table_live: bool,
    /// `region_bounds_are_live`: the Generational backend's bounds.
    pub(super) generational_bounds_live: bool,
}

/// The collector name the `CRATONVM_DBG_JITC` line carries.
pub(super) fn sb_to_string_gc_name(i: &SbToStringGcInputs) -> &'static str {
    if i.zgc_registration {
        "ZGC"
    } else if i.g1_table_live {
        "G1"
    } else if i.generational_bounds_live {
        "Generational"
    } else {
        "unknown"
    }
}

/// The per-collector arm of the inline `toString()`, or why there is none.
///
/// A ZGC site needs the inline start-bit table (without it every pre-check
/// would decline) and honours the array announce lever, since this is an
/// inline `newarray`. A live G1 table adds the same-region check on whatever
/// backend (two VMs in one process: the check is sound everywhere). A site
/// with none of the three premises declines.
pub(super) fn sb_to_string_gc_arm(i: SbToStringGcInputs) -> Result<SbToStringGc, &'static str> {
    if i.zgc_registration {
        if !i.zgc_start_bit_requested {
            return Err("ZGC inline start-bit announce off (CRATONVM_ZGC_JIT_INLINE_ANNOUNCE=0)");
        }
        if !i.zgc_array_announce {
            return Err(
                "ZGC inline array announce off (CRATONVM_JIT_IR_ZGC_INLINE_ARRAY_ANNOUNCE=0)",
            );
        }
    } else if !i.g1_table_live && !i.generational_bounds_live {
        return Err("no collector premise (no ZGC table, G1 table or generational bounds)");
    }
    Ok(SbToStringGc {
        zgc_start_bits: i.zgc_registration,
        g1_same_region: i.g1_table_live,
    })
}

/// The compile-time half of the inline `toString()`: every screen that does
/// not depend on the receiver. `Err` names the refusal; the site then emits
/// one unconditional decline (the ordinary call) and nothing else.
///
/// Screens, each a reason the fast path could not keep its contract (the
/// collector is [`sb_to_string_gc_arm`]'s question, round 17 wave 2):
/// * the inline-TLAB levers (`CRATONVM_NO_JIT_INLINE_TLAB_NEW[ARRAY]`, zero
///   elision off), because this is an inline `new` and an inline `newarray`;
/// * narrow oops (the `value` store is a bare 8-byte pointer);
/// * no compact `String` recipe for exactly its registered field count in a
///   single layout domain (`compact_tlab_total_size`), or a `value` cell that
///   is not an 8-byte slot at the layout's own offset.
fn sb_to_string_plan(outer: &crate::StringFieldLayout) -> Result<SbToStringPlan, &'static str> {
    if !crate::jit_sb_to_string_inline_enabled() {
        return Err("switch off");
    }
    string_alloc_plan(outer)
}

#[cfg(test)]
impl SbToStringPlan {
    /// A hand-built recipe for executed-code tests of the allocation tails
    /// (JIT round 19 proposal wave 5, lane concat5): `total`-byte String with
    /// `value` at `value_off`, class `cid`, the replace guard at `guard`, and
    /// the real header offsets and `byte[]` mark word.
    pub(super) fn for_test(cid: u32, total: i32, value_off: i32, guard: (usize, u32)) -> Self {
        use cratonvm_types::{ArrayElementType, ClassId, ObjectHeader, ObjectKind};
        let mark = ObjectHeader::new(
            ClassId::new(0),
            ObjectKind::Array,
            ArrayElementType::Byte,
            0,
            0,
        )
        .mark_word
        .load(std::sync::atomic::Ordering::Relaxed);
        let d8 = |v: usize| u8::try_from(v).expect("a disp8 header constant");
        Self {
            string_class_id: cid,
            string_total: total,
            value_off,
            replace_guard: guard,
            max_count: 4096,
            len_d8: d8(cratonvm_types::ARRAY_LENGTH_OFFSET),
            data_d8: d8(cratonvm_types::ARRAY_DATA_OFFSET),
            kind_d8: d8(cratonvm_types::KIND_TAGS_BYTE_OFFSET),
            byte_array_tag: cratonvm_types::primitive_array_kind_tags_byte("[B").unwrap_or(0),
            // Cast: the mark word's bits as an imm32.
            byte_array_mark: mark as i32,
            utf16_coder: None,
        }
    }
}

/// [`sb_to_string_plan`] without its switch: the compact `String` + exact
/// `byte[]` recipe one inline TLAB bump builds. Shared by the inline
/// `StringBuilder.toString()` and (JIT round 19 proposal wave 4, lane
/// strgap4, STRGAP19-3) the inline concat, which has its own switch.
pub(super) fn string_alloc_plan(
    outer: &crate::StringFieldLayout,
) -> Result<SbToStringPlan, &'static str> {
    use cratonvm_types::{ArrayElementType, ClassId, ObjectHeader, ObjectKind};
    if !inline_tlab_new_enabled()
        || !inline_tlab_newarray_enabled()
        || !inline_tlab_zero_elision_enabled()
    {
        return Err("inline TLAB lever off");
    }
    if narrow_oops_enabled() || outer.value_compact_is_narrow {
        return Err("narrow oops");
    }
    let cid = outer.string_class_id;
    if cid == 0 {
        return Err("no String class id");
    }
    // The replace count BEFORE the recipe is read: a replacement between the
    // two reads fails the run-time guard, never the other way round.
    let (guard_addr, guard_value) = cratonvm_types::layout_replace_guard(cid);
    let fields = cratonvm_types::compact_field_count(cid).ok_or("no compact String layout")?;
    let total = cratonvm_types::compact_tlab_total_size(cid, fields as usize)
        .ok_or("no compact String recipe")?;
    let value_off = match cratonvm_types::compact_field_disp_storage(cid, outer.value_field_index) {
        Some((off, storage)) if storage.size_runtime() == 8 => off,
        _ => return Err("String.value is not an 8-byte compact slot"),
    };
    if total % 8 != 0
        || total > 256
        || value_off < cratonvm_types::COMPACT_HEADER_SIZE
        || value_off.saturating_add(8) > total
        || i32::try_from(value_off).ok() != Some(outer.value_compact_offset)
    {
        return Err("String recipe shape");
    }
    let d8 = |v: usize| u8::try_from(v).ok().filter(|b| *b <= 127);
    let (Some(len_d8), Some(data_d8), Some(kind_d8)) = (
        d8(cratonvm_types::ARRAY_LENGTH_OFFSET),
        d8(cratonvm_types::ARRAY_DATA_OFFSET),
        d8(cratonvm_types::KIND_TAGS_BYTE_OFFSET),
    ) else {
        return Err("header offset past disp8");
    };
    // The String is placed at `array + DATA + align8(count)`: an 8-aligned
    // array header and an 8-aligned data offset keep it on the 8-byte grid
    // every walker (and ZGC's start bitmap) assumes. True today (16); a
    // future header that broke it costs coverage, not a misaligned object.
    if data_d8 % 8 != 0 {
        return Err("array data offset not 8-aligned");
    }
    // The UTF16 arm's `coder` store (round 17 wave 2, lane sbzgc).
    let utf16_coder = if outer.has_coder && data_d8 < 127 {
        match cratonvm_types::compact_field_disp_storage(cid, outer.coder_field_index) {
            Some((off, storage)) => {
                let width = storage.size_runtime();
                let shape_ok = (width == 1 || width == 4)
                    && (width == 1) == outer.coder_compact_is_byte
                    && off >= cratonvm_types::COMPACT_HEADER_SIZE
                    && off.saturating_add(width as usize) <= total
                    && i32::try_from(off).ok() == Some(outer.coder_compact_offset);
                if shape_ok {
                    i32::try_from(off).ok().map(|o| (o, width == 1))
                } else {
                    None
                }
            }
            None => None,
        }
    } else {
        None
    };
    let byte_array_tag =
        cratonvm_types::primitive_array_kind_tags_byte("[B").ok_or("no byte[] kind tag")?;
    let byte_array_mark = ObjectHeader::new(
        ClassId::new(0),
        ObjectKind::Array,
        ArrayElementType::Byte,
        0,
        0,
    )
    .mark_word
    .load(std::sync::atomic::Ordering::Relaxed);
    // Both objects, the 8-byte alignment slop and the array's round-up stay
    // under the cap `emit_inline_tlab_newarray` honours for one array.
    let fixed = usize::from(data_d8) + total + 16;
    let max_count = Compiler::INLINE_ARRAY_TLAB_MAX_ALLOC
        .checked_sub(fixed)
        .and_then(|n| i32::try_from(n).ok())
        .ok_or("cap")?;
    Ok(SbToStringPlan {
        string_class_id: cid,
        string_total: i32::try_from(total).map_err(|_| "String recipe shape")?,
        value_off: i32::try_from(value_off).map_err(|_| "String recipe shape")?,
        replace_guard: (guard_addr as usize, guard_value),
        max_count,
        len_d8,
        data_d8,
        kind_d8,
        byte_array_tag,
        // Cast: the mark word's bits as an imm32.
        byte_array_mark: byte_array_mark as i32,
        utf16_coder,
    })
}

/// `CRATONVM_STRING_LITERAL_IDENTITY` (JIT round 17 wave 4, lane sbempty;
/// default ON, `=0` kill): the inline `toString()` declines an empty LATIN1
/// builder into the call, which answers JDK 25's `""` literal. Read at compile
/// time, once per emitted site, like the other levers of this body; the same
/// name gates the natives' literal answers (`native-builtins` `lang_string`
/// `string_literal_identity_enabled`).
fn empty_builder_declines_to_call() -> bool {
    cratonvm_types::flags::runtime_flag_default_on("CRATONVM_STRING_LITERAL_IDENTITY")
}

impl Compiler {
    /// The inline `StringBuilder.toString()` body (JIT round 17 wave 1, lane
    /// strings, STR16-P1; `CRATONVM_JIT_SB_TOSTRING_INLINE`, default on).
    ///
    /// JDK 25 `StringBuilder.toString()` is `new String(this, null)`, whose
    /// LATIN1 arm is `value = Arrays.copyOfRange(asb.getValue(), 0,
    /// asb.length()); coder = LATIN1`. On entry RAX is the receiver, already
    /// null-checked and proven an exact `StringBuilder` by the region's
    /// class-id guard. The fast path builds exactly that answer:
    ///
    /// ```text
    ///   compact receiver ; coder == LATIN1 ; value != null ; value is a byte[]
    ///   ECX = count ; count <=u value.length ; count <=u max   (else decline)
    ///   String layout-replace guard                           (else decline)
    ///   R10 = thread (cached slot or TLS mirror; null -> decline)
    ///   R11 = align8(cursor)                 ; the byte[count]
    ///   R9  = R11 + DATA + align8(count)     ; the String
    ///   RAX = R9 + String total ; RAX >u end -> decline     ; one bump, both
    ///   byte[] header ; String header ; String body zeroed ; String.value = R11
    ///   copy count bytes value[0..count] -> R11 data (8 at a time, then bytes)
    ///   cursor = R9 + String total            ; commit LAST
    ///   RAX = R9
    /// ```
    ///
    /// Every decline precedes the first store, so a declined call leaves the
    /// TLAB exactly as it found it (the zero-elision invariant every other
    /// inline allocation relies on), and the ordinary call -- the JDK body
    /// under `--jdk-only` -- answers. The fast path makes no call, so it cannot
    /// collect, trap or deopt: it owes no safepoint map, and the header-before-
    /// commit argument of `emit_inline_tlab_new` covers both objects (the cursor
    /// store is the single publication point). The one reference store, `value`,
    /// writes a young pointer into a young, uncommitted String whose old value
    /// is the TLAB's zero.
    ///
    /// Round 17 wave 2, lane sbzgc: every backend, each with its own proof that
    /// the collector's barrier for that store is a no-op ([`SbToStringGc`]).
    /// Generational needs nothing at run time; ZGC checks the start-bit table's
    /// whole contract for BOTH objects before the first store and sets both
    /// start bits after the commit (the `new` / `newarray` sites' announce,
    /// call-free); G1 checks that the two objects share a region. Any failed
    /// check is one more decline edge, so no arm needs a helper call.
    ///
    /// Semantics kept: a FRESH String per call (never interned, never shared:
    /// `sb.toString() != sb.toString()`), `hash` 0 and `hashIsZero` false so
    /// `hashCode()` computes as for any new String; `count < value.length` copies
    /// only `count` bytes. An EMPTY builder declines to the call (round 17
    /// wave 4, lane sbempty): JDK 25's `toString()` opens with `if (length()
    /// == 0) return "";`, the literal, which a fresh String is not; under
    /// `CRATONVM_STRING_LITERAL_IDENTITY=0` it gets a fresh `byte[0]`, as
    /// `Arrays.copyOfRange` gives it.
    ///
    /// The UTF16 arm (round 17 wave 2, lane sbzgc,
    /// `CRATONVM_JIT_SB_TOSTRING_UTF16`, opt-in on top of the main switch):
    /// JDK 25's UTF16 arm compresses to LATIN1 when `maybeLatin1` is set and
    /// every char fits, and otherwise copies `length << 1` bytes with `coder =
    /// UTF16`. The builder layout carries no `maybeLatin1`, so the inline arm
    /// serves exactly the builders for which both JDK paths agree: it scans for
    /// one char above `0xFF` and, finding one, copies `2 * count` bytes into a
    /// fresh `byte[2 * count]` with `coder = UTF16`; an all-LATIN1 UTF16
    /// builder (including an empty one) declines, so the compression and the
    /// `-XX:-CompactStrings` answer stay the JDK's.
    ///
    /// Round 17 wave 6, lane sbzgc2 (SBZGC17-2): when the layout carries the
    /// `maybeLatin1` slot ([`crate::StringBuilderFieldLayout::with_maybe_latin1`])
    /// the arm reads it. An EXACT `false` (`--jdk-only`) skips the scan and
    /// copies as UTF16, the JDK's answer whatever the chars; a set flag with
    /// no char above `0xFF` is narrowed to a LATIN1 String inline under
    /// `CRATONVM_JIT_SB_TOSTRING_COMPRESS`, else declines. Under
    /// `CRATONVM_DBG_JITC` every path and counted decline bumps its
    /// [`crate::metrics::SB_TO_STRING_CENSUS`] row (SBZGC17-5).
    ///
    /// Registers: RAX, RCX, RDX, R8-R11 and flags; the region flushed the
    /// operand cache before the guard, and the decline edge re-reads the
    /// receiver from its slot.
    pub(super) fn emit_sb_to_string_latin1_body(
        &mut self,
        b: &crate::StringBuilderFieldLayout,
        outer: &crate::StringFieldLayout,
        decline: &mut Vec<usize>,
    ) {
        let thread_source = self.jit_thread_slot_off != 0 || jit_thread_tls_disp() != 0;
        let gc_inputs = SbToStringGcInputs {
            zgc_registration: cratonvm_types::jit_tlab_registration_required(),
            zgc_start_bit_requested: super::objects::zgc_inline_start_bit_requested(),
            zgc_array_announce: crate::x64::zgc_inline_array_announce_enabled(),
            g1_table_live: g1_barrier_table_live(self.helpers.g1_barrier_addr),
            generational_bounds_live: region_bounds_are_live(self.helpers.region_bounds_addr),
        };
        let gc_name = sb_to_string_gc_name(&gc_inputs);
        let planned = sb_to_string_plan(outer).and_then(|p| {
            let gc = sb_to_string_gc_arm(gc_inputs)?;
            if !thread_source {
                Err("no thread source that is not a call")
            } else if self.deferred_alloc_blind_spill || self.deferred_alloc_shadow_push {
                Err("withheld allocation spill")
            } else if self.helpers.tlab_cursor_offset_in_thread
                == self.helpers.tlab_end_offset_in_thread
            {
                Err("no TLAB offsets")
            } else {
                Ok((p, gc))
            }
        });
        let (plan, gc) = match planned {
            Ok(pg) => pg,
            Err(why) => {
                if dbg_jitc_enabled() {
                    eprintln!(
                        "[cratonvm-jitc] sb-tostring-inline DECLINED {} gc={gc_name}: {why}",
                        self.method_label
                    );
                }
                decline.push(self.emit_jmp_rel32_patch());
                self.slot_mirror = None;
                return;
            }
        };
        let utf16_requested = crate::jit_sb_to_string_utf16_enabled();
        let utf16 = plan.utf16_coder.filter(|_| utf16_requested);
        // `maybeLatin1` (round 17 wave 6, lane sbzgc2, SBZGC17-2): the UTF16
        // arm reads it when the layout has its slot and it can use it --
        // `false` exact (`--jdk-only`) skips the scan, `true` with the
        // compress switch armed narrows an all-LATIN1 payload inline.
        let compress = utf16.is_some() && crate::jit_sb_to_string_compress_enabled();
        let skip_scan_on_false = b.maybe_latin1_false_is_exact;
        let maybe_latin1 = b
            .maybe_latin1_compact_offset
            .filter(|_| utf16.is_some() && (skip_scan_on_false || compress));
        // Run-time census (SBZGC17-5): only in code compiled while the
        // compile-time line below is armed; otherwise not one byte changes.
        let count = dbg_jitc_enabled();
        crate::metrics::note_sb_to_string(crate::metrics::SB_TS_SITES);
        if count {
            let utf16_word = match (utf16_requested, utf16.is_some()) {
                (false, _) => "off",
                (true, true) => "on",
                (true, false) => "refused(String.coder slot)",
            };
            let ml_word = match (b.maybe_latin1_compact_offset, maybe_latin1) {
                (None, _) => "no-slot",
                (Some(_), None) => "unused",
                (Some(_), Some(_)) if skip_scan_on_false => "exact",
                (Some(_), Some(_)) => "true-only",
            };
            eprintln!(
                "[cratonvm-jitc] sb-tostring-inline EMITTED {} gc={gc_name} zgc_start_bits={} g1_same_region={} utf16={utf16_word} maybe_latin1={ml_word} compress={compress} cid={} total={} value_off={} max={}",
                self.method_label,
                gc.zgc_start_bits,
                gc.g1_same_region,
                plan.string_class_id,
                plan.string_total,
                plan.value_off,
                plan.max_count
            );
        }
        let row = |r: usize| -> Option<&'static std::sync::atomic::AtomicU64> {
            if count {
                crate::metrics::SB_TO_STRING_CENSUS.get(r)
            } else {
                None
            }
        };
        if let Some(c) = row(crate::metrics::SB_TS_ENTERED) {
            // RAX (the receiver) survives; R8 is scratch until the tail.
            self.emit_lock_inc_counter_via_r8(c);
        }

        // ---- receiver screens (RAX = the builder) --------------------------
        self.emit_test_mem8_imm8(
            RAX,
            cratonvm_types::GC_FLAGS_BYTE_OFFSET as i32, // Cast: small header constant
            cratonvm_types::GC_FLAG_COMPACT,
        );
        decline.push(self.emit_jcc_rel32_patch(0x84)); // JZ legacy -> call
                                                       // ECX = coder.
        if b.coder_compact_is_byte {
            self.emit_movx_r64_mem_disp32(RCX, RAX, b.coder_compact_offset, 8, false);
        } else {
            self.emit_mov_r32_mem_disp32(RCX, RAX, b.coder_compact_offset);
        }
        // RDX = value; null -> call.
        self.emit_mov_r64_mem_disp32(RDX, RAX, b.value_compact_offset);
        self.emit_test_r64_r64(RDX);
        decline.push(self.emit_jcc_rel32_patch(0x84)); // JZ
                                                       // CMP BYTE [RDX + kind], byte[] tag ; JNE -> call.
        self.emit_cmp_mem8_imm8(RDX, i32::from(plan.kind_d8), plan.byte_array_tag);
        decline.push(self.emit_jcc_rel32_patch(0x85));
        // LATIN1 (0) here; UTF16 to its own arm when armed, else -> call.
        self.buf.emit(&[0x85, 0xC9]); // TEST ECX,ECX
        let to_utf16 = if utf16.is_some() {
            Some(self.emit_jcc_rel32_patch(0x85)) // JNZ utf16 arm
        } else {
            decline.push(self.emit_jcc_rel32_patch(0x85)); // JNZ UTF16 -> call
            None
        };
        // ECX = count (zero-extends RCX).
        self.emit_mov_r32_mem_disp32(RCX, RAX, b.count_compact_offset);
        // count == 0 -> call (round 17 wave 4, lane sbempty,
        // `CRATONVM_STRING_LITERAL_IDENTITY`, default ON): JDK 25 answers the
        // `""` LITERAL for an empty builder, which this body cannot name (a
        // movable heap object, no baked address), so the call answers it --
        // the JDK body, or the native that now returns the literal too. The
        // UTF16 arm already declines an empty builder (its scan finds no char
        // above 0xFF).
        //
        // JIT round 19 proposal wave 5, lane concat5 (STRGAP4-2,
        // `CRATONVM_JIT_STRING_LITERAL_SLOTS`, default OFF): with this VM's
        // rooted `""` literal slot the empty builder is answered inline
        // instead (the arm after the LATIN1 tail below); without one, or with
        // the switch off, this is byte for byte the decline.
        let mut empty_arm: Option<(usize, usize)> = None;
        if empty_builder_declines_to_call() {
            self.buf.emit(&[0x85, 0xC9]); // TEST ECX,ECX
            let empty_slot = if super::op_concat::string_literal_slots_enabled() {
                self.direct_helpers.string_literal_slot(true)
            } else {
                None
            };
            let jz = self.emit_jcc_rel32_patch(0x84); // JZ -> call (or the "" arm)
            match empty_slot {
                Some(slot) => empty_arm = Some((jz, slot)),
                None => decline.push(jz),
            }
        }
        // CMP ECX,[RDX+len] ; JA -> call: unsigned, so a negative count is out.
        self.buf.emit(&[0x3B, 0x4A, plan.len_d8]);
        decline.push(self.emit_jcc_rel32_patch(0x87));
        // CMP ECX,max_count ; JA -> call.
        self.buf.emit(&[0x81, 0xF9]);
        self.buf.emit(&plan.max_count.to_le_bytes());
        decline.push(self.emit_jcc_rel32_patch(0x87));
        let latin1_arm = SbToStringArm {
            utf16_coder: None,
            narrow: false,
            taken_row: crate::metrics::SB_TS_TAKEN_LATIN1,
        };
        self.emit_sb_to_string_tail(&plan, gc, latin1_arm, count, decline, None);
        if let Some((jz, slot)) = empty_arm {
            // ---- "" arm (STRGAP4-2): RAX = the interned "" literal, read raw
            // from the VM's GC-maintained slot as an `ldc` slot is read; a
            // word still 0 (never, once published) declines. Joins the LATIN1
            // tail's fall-through with RAX = the String.
            let over = self.emit_jmp_rel32_patch();
            self.patch_rel32_to_here(jz);
            // Cast: the VM's slot address, baked.
            self.emit_mov_imm64_full(RAX, slot as i64);
            self.buf.emit(&[0x48, 0x8B, 0x00]); // MOV RAX,[RAX]
            self.emit_test_r64_r64(RAX);
            decline.push(self.emit_jcc_rel32_patch(0x84)); // JZ -> call
            self.patch_rel32_to_here(over);
        }

        if let (Some(to_utf16), Some(coder)) = (to_utf16, utf16) {
            let mut done = vec![self.emit_jmp_rel32_patch()];
            // ---- UTF16 arm: ECX = coder, RDX = value (a byte[]) -------------
            self.patch_rel32_to_here(to_utf16);
            self.buf.emit(&[0x83, 0xF9, 0x01]); // CMP ECX,1 (UTF16 exactly)
            decline.push(self.emit_jcc_rel32_patch(0x85)); // JNE -> call
                                                           // ECX = count ; count <=u max/2 (so 2*count <=u max) ; JA -> call.
            self.emit_mov_r32_mem_disp32(RCX, RAX, b.count_compact_offset);
            if maybe_latin1.is_some() {
                // count == 0 -> call, explicitly: the scan below used to
                // decline an empty builder by finding no char, and neither
                // the skipped scan nor the compress may answer one (JDK 25
                // returns the `""` literal).
                self.buf.emit(&[0x85, 0xC9]); // TEST ECX,ECX
                decline.push(self.emit_jcc_rel32_patch(0x84)); // JZ -> call
            }
            self.buf.emit(&[0x81, 0xF9]);
            self.buf.emit(&(plan.max_count / 2).to_le_bytes());
            decline.push(self.emit_jcc_rel32_patch(0x87));
            // R8D = 2*count ; CMP R8D,[RDX+len] ; JA -> call.
            self.buf.emit(&[0x44, 0x8D, 0x04, 0x09]); // LEA R8D,[RCX+RCX]
            self.buf.emit(&[0x44, 0x3B, 0x42, plan.len_d8]); // CMP R8D,[RDX+len]
            decline.push(self.emit_jcc_rel32_patch(0x87));
            // R9D = maybeLatin1 (RAX is still the compact receiver). JDK 25's
            // `String(AbstractStringBuilder, Void)`: `false` -> copy as UTF16
            // whatever the chars are; `true` -> compress when every char fits.
            let mut skip_scan = None;
            if let Some(ml_off) = maybe_latin1 {
                self.emit_movx_r64_mem_disp32(R9, RAX, ml_off, 8, false); // MOVZX R9D,BYTE
                if skip_scan_on_false {
                    self.buf.emit(&[0x45, 0x85, 0xC9]); // TEST R9D,R9D
                    skip_scan = Some(self.emit_jcc_rel32_patch(0x84)); // JZ: no scan
                }
            }
            // Scan for a char above 0xFF: its HIGH byte (odd index, x86 is
            // little-endian, as `StringUTF16`'s byte order is native) != 0.
            // None found -> the all-LATIN1 block below (the call, unless the
            // compress is armed and `maybeLatin1` is set).
            let all_latin1_inline = compress && maybe_latin1.is_some();
            self.buf.emit(&[0x31, 0xC0]); // XOR EAX,EAX (char index)
            let scan_top = self.buf.pos();
            self.buf.emit(&[0x39, 0xC8]); // CMP EAX,ECX
            let scan_end = self.emit_jcc_rel32_patch(0x83); // JAE: all LATIN1
                                                            // CMP BYTE [RDX+RAX*2+DATA+1],0 (the plan screened DATA+1 <= 127).
            self.buf.emit(&[0x80, 0x7C, 0x42, plan.data_d8 + 1, 0x00]);
            let found = self.emit_jcc_rel32_patch(0x85); // JNE found
            self.buf.emit(&[0xFF, 0xC0]); // INC EAX
            let back = self.emit_jmp_rel32_patch();
            let rel = scan_top as i32 - (back as i32 + 4); // Cast: rel32 displacement
            self.buf.try_patch_i32(back, rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
            let all_latin1_row = row(crate::metrics::SB_TS_UTF16_ALL_LATIN1);
            if !all_latin1_inline && all_latin1_row.is_none() {
                // The wave-2 shape, byte for byte: the scan's end IS a decline.
                decline.push(scan_end);
            } else {
                self.patch_rel32_to_here(scan_end);
                if all_latin1_inline {
                    // `maybeLatin1 == false` -> call (counted): the JDK copies
                    // such a builder as UTF16, and only an exact `false`
                    // (handled above, before the scan) may answer that inline.
                    self.buf.emit(&[0x45, 0x85, 0xC9]); // TEST R9D,R9D
                    self.emit_decline_jcc_counted(0x84, all_latin1_row, decline); // JZ
                                                                                  // ---- compress: ECX = count chars of RDX -> byte[count] --
                    let compressed = SbToStringArm {
                        utf16_coder: None,
                        narrow: true,
                        taken_row: crate::metrics::SB_TS_TAKEN_COMPRESSED,
                    };
                    self.emit_sb_to_string_tail(&plan, gc, compressed, count, decline, None);
                    done.push(self.emit_jmp_rel32_patch());
                } else if let Some(c) = all_latin1_row {
                    self.emit_lock_inc_counter_via_r8(c);
                    decline.push(self.emit_jmp_rel32_patch());
                }
            }
            // `maybeLatin1 == false`, exact: straight to the UTF16 copy.
            if let Some(skip) = skip_scan {
                self.patch_rel32_to_here(skip);
                if let Some(c) = row(crate::metrics::SB_TS_UTF16_SCAN_SKIPPED) {
                    self.emit_lock_inc_counter_via_r8(c);
                }
            }
            self.patch_rel32_to_here(found);
            // ECX = 2*count, the byte count (ECX still holds count on both
            // edges into here; R8 may be a counter address).
            self.buf.emit(&[0x01, 0xC9]); // ADD ECX,ECX
            let utf16_arm = SbToStringArm {
                utf16_coder: Some(coder),
                narrow: false,
                taken_row: crate::metrics::SB_TS_TAKEN_UTF16,
            };
            self.emit_sb_to_string_tail(&plan, gc, utf16_arm, count, decline, None);
            for d in done {
                self.patch_rel32_to_here(d);
            }
        }
        self.slot_mirror = None;
    }

    /// The allocation half of [`Self::emit_sb_to_string_latin1_body`], shared
    /// by its LATIN1 and UTF16 arms: `byte[ECX]` holding the first ECX bytes of
    /// the source array in RDX, plus the `String` over it, in ONE bump; every
    /// refusal before the first store pushes onto `decline`. `arm.utf16_coder`
    /// stores `coder = UTF16` (the LATIN1 arm leaves the zeroed `0`);
    /// `arm.narrow` (round 17 wave 6, lane sbzgc2) copies the low byte of each
    /// of ECX UTF16 chars instead of ECX bytes. `count` (`CRATONVM_DBG_JITC`)
    /// counts the TLAB-full and collector declines and `arm.taken_row` at run
    /// time; off, the tail is byte for byte its uncounted form. Leaves RAX =
    /// the String.
    ///
    /// `fill` (JIT round 19 proposal wave 4, lane strgap4, STRGAP19-3; `None`
    /// at every `toString()` site, which keeps their bytes unchanged) replaces
    /// the copy from RDX: it is emitted after both headers and `String.value`
    /// are stored, with R11 = the `byte[]` and R9 = the String, may clobber
    /// RAX, RCX, RDX, R8 and R10, and must write exactly the ECX bytes the
    /// array was sized for. R10 (the thread) is re-derived after it.
    pub(super) fn emit_sb_to_string_tail(
        &mut self,
        plan: &SbToStringPlan,
        gc: SbToStringGc,
        arm: SbToStringArm,
        count: bool,
        decline: &mut Vec<usize>,
        fill: Option<&dyn Fn(&mut Compiler)>,
    ) {
        use crate::metrics as m;
        let row = |r: usize| -> Option<&'static std::sync::atomic::AtomicU64> {
            if count {
                m::SB_TO_STRING_CENSUS.get(r)
            } else {
                None
            }
        };
        let utf16_coder = arm.utf16_coder;
        // Cast: encoding immediates/displacements of small header constants.
        let cursor_off = self.helpers.tlab_cursor_offset_in_thread as i32;
        let end_off = self.helpers.tlab_end_offset_in_thread as i32;
        let class_id_off = self.helpers.class_id_offset_in_obj as i32;

        // ---- String layout-replace guard (RAX, R11 scratch) ----------------
        self.emit_mov_imm64_full(R11, plan.replace_guard.0 as i64); // Cast: baked address
        self.emit_mov_r32_mem_disp32(RAX, R11, 0);
        self.buf.emit_byte(0x3D); // CMP EAX, imm32
        self.buf.emit(&(plan.replace_guard.1 as i32).to_le_bytes()); // Cast: counter bits
        decline.push(self.emit_jcc_rel32_patch(0x85)); // JNE

        // ---- thread, then ONE bump for both objects ------------------------
        if self.jit_thread_slot_off != 0 {
            self.emit_load_local(RAX, self.jit_thread_slot_off);
        } else {
            // Cast: the mirror's TLS displacement, a small positive offset.
            self.emit_mov_rax_tls_disp32(jit_thread_tls_disp() as u32);
        }
        self.emit_mov_r64_r64(R10, RAX);
        self.emit_test_r64_r64(R10);
        decline.push(self.emit_jcc_rel32_patch(0x84)); // JZ no thread -> call
                                                       // R11 = align8(cursor): the byte[].
        self.emit_mov_r64_mem_disp32(R11, R10, cursor_off);
        self.emit_add_r64_imm8(R11, 7);
        self.emit_and_r64_imm8(R11, -8);
        // R8 = align8(count).
        self.buf.emit(&[0x41, 0x89, 0xC8]); // MOV R8D,ECX
        self.emit_add_r64_imm8(R8, 7);
        self.emit_and_r64_imm8(R8, -8);
        // LEA R9,[R11+R8+DATA]: the String.
        self.buf.emit(&[0x4F, 0x8D, 0x4C, 0x03, plan.data_d8]);
        // RAX = R9 + total: the new cursor. CMP RAX,[R10+end] ; JA -> call.
        self.emit_lea_r64_mem_disp32(RAX, R9, plan.string_total);
        self.emit_cmp_r64_mem_disp32(RAX, R10, end_off);
        // JA -> call. A counted edge clobbers R8 (align8(count)) on the way
        // out only; the fall-through keeps it, though nothing below reads it.
        self.emit_decline_jcc_counted(0x87, row(m::SB_TS_TLAB_FULL), decline);

        // ---- per-collector pre-checks (RAX, R8 scratch; RAX re-derived at
        // the commit). Live: ECX, RDX, R9, R10, R11. ------------------------
        if gc.g1_same_region {
            self.emit_sb_g1_same_region_check(decline, row(m::SB_TS_G1_CROSS_REGION));
        }
        // zr z9/bo: one read of the start-bit form for the pre-check and
        // both stores (`CRATONVM_ZGC_JIT_SHORT_ANNOUNCE`).
        let short_bits = gc.zgc_start_bits && super::objects::zgc_jit_short_announce_enabled();
        if gc.zgc_start_bits {
            // Every condition of the start-bit table's contract, for both
            // objects, before anything is written; the bits follow the commit.
            self.emit_zgc_start_bit_precheck_form(
                cursor_off,
                end_off,
                &[R11, R9],
                decline,
                count,
                short_bits,
            );
        }
        // ---- no decline past this point: every store below is committed ----

        // byte[] header: class id 0, length, mark word, "no hash yet".
        self.emit_mov_dword_mem_disp32_imm32(R11, 0, 0);
        self.buf.emit(&[0x41, 0x89, 0x4B, plan.len_d8]); // MOV [R11+len],ECX
        self.emit_mov_dword_mem_disp32_imm32(
            R11,
            cratonvm_types::MARK_WORD_OFFSET as i32, // Cast: small header constant
            plan.byte_array_mark,
        );
        self.emit_mov_dword_mem_disp32_imm32(
            R11,
            cratonvm_types::IDENTITY_HASH_OFFSET as i32, // Cast: small header constant
            0,
        );
        // String header: class id and the compact mark word (NEUTRAL,
        // kind=Object, GC_FLAG_HEADER | GC_FLAG_COMPACT), as the inline `new`.
        self.emit_mov_dword_mem_disp32_imm32(R9, class_id_off, plan.string_class_id as i32); // Cast: ClassId fits in 32 bits
        let flags = cratonvm_types::GC_FLAG_COMPACT | cratonvm_types::GC_FLAG_HEADER;
        self.emit_mov_dword_mem_disp32_imm32(
            R9,
            cratonvm_types::MARK_WORD_OFFSET as i32, // Cast: small header constant
            i32::from(flags) << 24,
        );
        // String body: `coder` LATIN1 (0), `hash` 0, `hashIsZero` false, and
        // padding -- written, not assumed, as the mark word is.
        // Through `try_from`, not a cast: the header-offset inventory
        // (`header_offset_emission_site_inventory_matches_the_doc`) counts the
        // cast form. 8 today; an impossible failure zeroes nothing.
        let mut off =
            i32::try_from(cratonvm_types::COMPACT_HEADER_SIZE).unwrap_or(plan.string_total);
        while off < plan.string_total {
            self.emit_mov_dword_mem_disp32_imm32(R9, off, 0);
            off += 4;
        }
        // The UTF16 arm's `coder = UTF16` (1), over the zero just written.
        if let Some((coder_off, is_byte)) = utf16_coder {
            if is_byte {
                // MOV BYTE [R9+disp32],1: REX.B C6 /0, modrm 10 000 001.
                self.buf.emit(&[0x41, 0xC6, 0x81]);
                self.buf.emit(&coder_off.to_le_bytes());
                self.buf.emit_byte(1);
            } else {
                self.emit_mov_dword_mem_disp32_imm32(R9, coder_off, 1);
            }
        }
        // String.value = the byte[].
        self.emit_mov_mem_disp32_r64(R9, R11, plan.value_off);

        let d = plan.data_d8;
        if let Some(fill) = fill {
            fill(self);
            // The fill may use R10 as scratch: the thread again, for the
            // commit (proven non-null above; no decline past the stores).
            if self.jit_thread_slot_off != 0 {
                self.emit_load_local(RAX, self.jit_thread_slot_off);
            } else {
                // Cast: the mirror's TLS displacement, a small positive offset.
                self.emit_mov_rax_tls_disp32(jit_thread_tls_disp() as u32);
            }
            self.emit_mov_r64_r64(R10, RAX);
        } else if arm.narrow {
            // ---- compress: dst[i] = low byte of UTF16 char i, i < ECX ------
            // (round 17 wave 6, lane sbzgc2). The caller's scan proved every
            // high byte zero, so this is `StringUTF16.compress`'s answer; the
            // source reads stop at byte 2*count-2 < 2*count <=u value.length.
            self.buf.emit(&[0x45, 0x31, 0xC0]); // XOR R8D,R8D (i = 0)
            let narrow_top = self.buf.pos();
            self.buf.emit(&[0x41, 0x39, 0xC8]); // CMP R8D,ECX
            let narrowed = self.emit_jcc_rel32_patch(0x83); // JAE done
                                                            // MOVZX EAX,BYTE [RDX+R8*2+DATA]: REX.X 0F B6 /r, SIB scale 2.
            self.buf.emit(&[0x42, 0x0F, 0xB6, 0x44, 0x42, d]);
            self.buf.emit(&[0x43, 0x88, 0x44, 0x03, d]); // MOV [R11+R8+DATA],AL
            self.buf.emit(&[0x49, 0xFF, 0xC0]); // INC R8
            let back = self.emit_jmp_rel32_patch();
            let rel = narrow_top as i32 - (back as i32 + 4); // Cast: rel32 displacement
            self.buf.try_patch_i32(back, rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
            self.patch_rel32_to_here(narrowed);
        } else {
            self.emit_sb_to_string_byte_copy(d);
        }

        // ---- commit LAST, then answer the String ---------------------------
        // nio21 wave 10 L1 (`CRATONVM_ZGC_JIT_START_BIT_BEFORE_COMMIT`, default
        // ON): under ZGC both start bits are set BEFORE the commit (both
        // objects fully written; no poll since the pre-check), so a peer
        // frozen here owns two objects that are inside its published tail or
        // registered, never neither. The stores clobber RAX, so the new
        // cursor is derived after them. `=0`: commit, then the bits.
        let bits_first = gc.zgc_start_bits && super::objects::zgc_start_bit_before_commit_enabled();
        if bits_first {
            self.emit_zgc_start_bit_store_prechecked_form(cursor_off, R11, short_bits);
            self.emit_zgc_start_bit_store_prechecked_form(cursor_off, R9, short_bits);
        }
        self.emit_lea_r64_mem_disp32(RAX, R9, plan.string_total);
        self.emit_mov_mem_disp32_r64(R10, RAX, cursor_off);
        if gc.zgc_start_bits && !bits_first {
            // Announce both, as `emit_inline_tlab_newarray` / `_new` announce
            // one: after the commit, with no poll since the pre-check. The
            // copy's ECX / RDX are dead here; R9 / R10 / R11 survive.
            self.emit_zgc_start_bit_store_prechecked_form(cursor_off, R11, short_bits);
            self.emit_zgc_start_bit_store_prechecked_form(cursor_off, R9, short_bits);
        }
        if let Some(c) = row(arm.taken_row) {
            // R8 (the copy index, or the start-bit word index) is dead.
            self.emit_lock_inc_counter_via_r8(c);
        }
        self.emit_mov_r64_r64(RAX, R9);
        self.slot_mirror = None;
    }

    /// The byte copy of [`Self::emit_sb_to_string_tail`]: ECX bytes from the
    /// `byte[]` in RDX to the one in R11, 8 at a time, then bytes (`d` =
    /// `ARRAY_DATA_OFFSET` as a disp8). Clobbers RAX, R8 and the flags.
    fn emit_sb_to_string_byte_copy(&mut self, d: u8) {
        // ---- copy value[0..count) -> byte[] data ---------------------------
        self.buf.emit(&[0x45, 0x31, 0xC0]); // XOR R8D,R8D (i = 0)
        let qword_top = self.buf.pos();
        self.buf.emit(&[0x41, 0x8D, 0x40, 0x08]); // LEA EAX,[R8+8]
        self.buf.emit(&[0x39, 0xC8]); // CMP EAX,ECX
        let to_tail = self.emit_jcc_rel32_patch(0x87); // JA tail (i + 8 > count)
        self.buf.emit(&[0x4A, 0x8B, 0x44, 0x02, d]); // MOV RAX,[RDX+R8+DATA]
        self.buf.emit(&[0x4B, 0x89, 0x44, 0x03, d]); // MOV [R11+R8+DATA],RAX
        self.buf.emit(&[0x49, 0x83, 0xC0, 0x08]); // ADD R8,8
        let back = self.emit_jmp_rel32_patch();
        let rel = qword_top as i32 - (back as i32 + 4); // Cast: rel32 displacement
        self.buf.try_patch_i32(back, rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
        self.patch_rel32_to_here(to_tail);
        let byte_top = self.buf.pos();
        self.buf.emit(&[0x41, 0x39, 0xC8]); // CMP R8D,ECX
        let copied = self.emit_jcc_rel32_patch(0x83); // JAE done
        self.buf.emit(&[0x42, 0x0F, 0xB6, 0x44, 0x02, d]); // MOVZX EAX,BYTE [RDX+R8+DATA]
        self.buf.emit(&[0x43, 0x88, 0x44, 0x03, d]); // MOV [R11+R8+DATA],AL
        self.buf.emit(&[0x49, 0xFF, 0xC0]); // INC R8
        let back = self.emit_jmp_rel32_patch();
        let rel = byte_top as i32 - (back as i32 + 4); // Cast: rel32 displacement
        self.buf.try_patch_i32(back, rel).ok(); // on Err try_patch_i32 set buf.overflowed; compile bails
        self.patch_rel32_to_here(copied);
    }

    /// The G1 pre-check of the inline `toString()` (round 17 wave 2, lane
    /// sbzgc): `((R11 - base) ^ (R9 - base)) & region_mask == 0`, else a
    /// decline, against the published `JIT_G1_BARRIER` table -- the same
    /// arena-relative same-region test `emit_g1_barrier_filter` makes and
    /// `G1Collector::post_write_barrier_rset` opens with, so a passing pair
    /// (R9 = the String, R11 = the `byte[]` its `value` will name) is one whose
    /// store that barrier would have dismissed. An address outside the arena
    /// can only make the two differ (a wasted decline), never agree wrongly.
    /// Clobbers RAX, R8 and the flags; reads R9 and R11.
    ///
    /// Round 17 wave 6, lane sbzgc2 (SBZGC17-5): the decline is counted into
    /// `counter` when `Some`; `None` is byte for byte the uncounted check.
    pub(super) fn emit_sb_g1_same_region_check(
        &mut self,
        decline: &mut Vec<usize>,
        counter: Option<&'static std::sync::atomic::AtomicU64>,
    ) {
        // Cast: the 'static `JIT_G1_BARRIER` table's address, baked.
        let table = self.helpers.g1_barrier_addr as i64;
        self.emit_mov_imm64_full(RAX, table);
        self.emit_mov_r64_mem_disp32(RAX, RAX, Self::G1B_ARENA_BASE);
        self.emit_mov_r64_r64(R8, R11);
        self.emit_sub_r64_r64(R8, RAX); // R8 = A - base
        self.buf.emit(&[0x48, 0xF7, 0xD8]); // NEG RAX
        self.buf.emit(&[0x4C, 0x01, 0xC8]); // ADD RAX,R9: RAX = S - base
        self.emit_xor_r64_r64(RAX, R8);
        self.emit_mov_imm64_full(R8, table);
        self.emit_and_r64_mem_disp32(RAX, R8, Self::G1B_REGION_MASK);
        self.emit_decline_jcc_counted(0x85, counter, decline); // JNZ -> call
    }
}

/// JIT round 17 wave 2, lane sbzgc: the per-collector arm of the inline
/// `StringBuilder.toString()`, decided from spelled-out inputs (the emitter
/// gathers them from the process), and the G1 same-region pre-check executed
/// on its own against a fake `JIT_G1_BARRIER` table.
#[cfg(test)]
mod r17_sbzgc_sb_to_string_gc_arm_tests {
    use super::*;

    fn inputs(zgc: bool, g1: bool, gen: bool) -> SbToStringGcInputs {
        SbToStringGcInputs {
            zgc_registration: zgc,
            zgc_start_bit_requested: true,
            zgc_array_announce: true,
            g1_table_live: g1,
            generational_bounds_live: gen,
        }
    }

    /// Generational keeps the wave-1 premise and no run-time check.
    #[test]
    fn generational_needs_no_runtime_check() {
        let i = inputs(false, false, true);
        assert_eq!(sb_to_string_gc_name(&i), "Generational");
        assert_eq!(
            sb_to_string_gc_arm(i),
            Ok(SbToStringGc {
                zgc_start_bits: false,
                g1_same_region: false
            })
        );
    }

    /// G1 (no generational bounds) is admitted with the same-region check.
    #[test]
    fn g1_is_admitted_with_the_same_region_check() {
        let i = inputs(false, true, false);
        assert_eq!(sb_to_string_gc_name(&i), "G1");
        assert_eq!(
            sb_to_string_gc_arm(i),
            Ok(SbToStringGc {
                zgc_start_bits: false,
                g1_same_region: true
            })
        );
        // A live G1 table beside generational bounds (two VMs) keeps it.
        assert_eq!(
            sb_to_string_gc_arm(inputs(false, true, true)).map(|g| g.g1_same_region),
            Ok(true)
        );
    }

    /// ZGC, the default collector, is admitted with both start bits, and
    /// refuses when either inline-announce lever is off.
    #[test]
    fn zgc_is_admitted_with_the_start_bits_and_honours_its_levers() {
        let i = inputs(true, false, false);
        assert_eq!(sb_to_string_gc_name(&i), "ZGC");
        assert_eq!(
            sb_to_string_gc_arm(i),
            Ok(SbToStringGc {
                zgc_start_bits: true,
                g1_same_region: false
            })
        );
        let mut no_table = i;
        no_table.zgc_start_bit_requested = false;
        let why = sb_to_string_gc_arm(no_table).expect_err("no table, no inline announce");
        assert!(why.contains("CRATONVM_ZGC_JIT_INLINE_ANNOUNCE"), "{why}");
        let mut no_array = i;
        no_array.zgc_array_announce = false;
        let why = sb_to_string_gc_arm(no_array).expect_err("the array lever is honoured");
        assert!(
            why.contains("CRATONVM_JIT_IR_ZGC_INLINE_ARRAY_ANNOUNCE"),
            "{why}"
        );
        // The levers are ZGC's only: they never refuse another backend.
        let mut gen = inputs(false, false, true);
        gen.zgc_start_bit_requested = false;
        gen.zgc_array_announce = false;
        assert!(sb_to_string_gc_arm(gen).is_ok());
    }

    /// No premise at all (a hand-built helper table) declines.
    #[test]
    fn no_collector_premise_declines() {
        let i = inputs(false, false, false);
        assert_eq!(sb_to_string_gc_name(&i), "unknown");
        assert!(sb_to_string_gc_arm(i).is_err());
    }

    /// The G1 pre-check, executed: same region passes, a region boundary
    /// between the two objects declines, and the subtraction of the arena
    /// base (not a raw XOR) decides it.
    #[cfg(target_arch = "x86_64")]
    #[test]
    fn the_g1_same_region_check_executes_the_arena_relative_test() {
        // `[arena_base, arena_len, region_mask, card_base, card_shift]`, a
        // 4 KiB "region" at an arena base that is NOT region-aligned.
        const BASE: u64 = 0x1000_0300;
        const REGION: u64 = 0x1000;
        let table: [u64; 5] = [BASE, 64 * REGION, !(REGION - 1), 0, 0];

        let run = |a: u64, b: u64| -> i64 {
            let mut c = crate::x64::flag_and_header_contracts::bounds_check_test_compiler();
            // Cast: the fake table's address, as the helper table stores it.
            c.helpers.g1_barrier_addr = table.as_ptr() as usize;
            let entry_off = c.buf.pos();
            c.emit_mov_r64_r64(R11, ARG_REGS[0]);
            c.emit_mov_r64_r64(R9, ARG_REGS[1]);
            let mut decline: Vec<usize> = Vec::new();
            c.emit_sb_g1_same_region_check(&mut decline, None);
            c.emit_mov_imm32_sx(RAX, 1);
            c.buf.emit(&[0xC3]); // ret
            for p in decline {
                c.patch_rel32_to_here(p);
            }
            c.emit_xor_reg_self(RAX);
            c.buf.emit(&[0xC3]); // ret
            assert!(!c.buf.overflowed());
            crate::platform::make_executable(c.buf.as_ptr() as *mut u8, c.buf.capacity())
                .expect("the test buffer must be flippable to RX");
            // SAFETY: `entry_off` is a byte offset inside the same allocation.
            let entry = unsafe { c.buf.as_ptr().add(entry_off) };
            // SAFETY: a leaf snippet that reads only `table` (alive across the
            // call), writes nothing, calls nothing and returns an i64.
            let f: extern "C" fn(i64, i64) -> i64 = unsafe { std::mem::transmute(entry) };
            // Cast: the two addresses as the i64 arguments the snippet takes.
            let r = f(a as i64, b as i64);
            drop(c);
            r
        };
        // Same region (offsets 0x10 and 0x200 of region 3).
        assert_eq!(run(BASE + 3 * REGION + 0x10, BASE + 3 * REGION + 0x200), 1);
        // Straddling the boundary between regions 3 and 4.
        assert_eq!(run(BASE + 4 * REGION - 0x10, BASE + 4 * REGION + 0x8), 0);
        // Same ALIGNED 4 KiB block of the address space, different regions:
        // a raw `(a ^ b) & mask` would call these the same; the base
        // subtraction must not. 0x1000_4000 is region 3 (it starts at
        // 0x1000_3300), 0x1000_4310 is region 4.
        assert_eq!(run(0x1000_4000, 0x1000_4310), 0);
        // Same region, the pair the other way round (the String above the array).
        assert_eq!(run(BASE + 5 * REGION + 0x400, BASE + 5 * REGION + 0x20), 1);
    }
}

#[cfg(test)]
mod r11w12_hashmap_ic_stack_args {
    use super::ic_stack_arg_block;
    use crate::inline_cache_pic::ic_max_stack_words;

    /// A site that fits the register file with the context word gets no
    /// block, so its inline cache stays byte-identical to before.
    #[test]
    fn a_site_that_fits_the_registers_gets_no_block() {
        for n in 1..=3 {
            assert_eq!(ic_stack_arg_block(n, 4, true), None, "win64 n={n}");
        }
        for n in 1..=5 {
            assert_eq!(ic_stack_arg_block(n, 6, false), None, "sysv n={n}");
        }
    }

    /// `HashMap.newNode` (receiver + 4) on Win64: the context ABI needs two
    /// stack words (arguments 3 and 4 of the Java list), the context-free ABI
    /// one. 32 + 16 = 48, already 16-aligned; the words start above the home
    /// area.
    #[test]
    fn hashmap_new_node_on_win64_gets_a_48_byte_block_above_the_home_area() {
        assert_eq!(ic_stack_arg_block(5, 4, true), Some((48, 32)));
        // n = 4: one context word overflows; 32 + 8 rounds to 48.
        assert_eq!(ic_stack_arg_block(4, 4, true), Some((48, 32)));
    }

    /// SysV has no home area; the block is the words, rounded to 16.
    #[test]
    fn sysv_blocks_have_no_home_area_and_stay_aligned() {
        assert_eq!(ic_stack_arg_block(6, 6, false), Some((16, 0)));
        assert_eq!(ic_stack_arg_block(7, 6, false), Some((16, 0)));
        assert_eq!(ic_stack_arg_block(8, 6, false), Some((32, 0)));
    }

    /// Every block is 16-aligned and holds every context-ABI stack word; past
    /// the cap there is no block and the site keeps the helper.
    #[test]
    fn every_block_is_aligned_and_large_enough_and_the_cap_holds() {
        let cap = ic_max_stack_words();
        for (regs, win64) in [(4usize, true), (6, false)] {
            for n in 1..=(regs + cap + 2) {
                let words = (n + 1).saturating_sub(regs);
                match ic_stack_arg_block(n, regs, win64) {
                    None => assert!(words == 0 || words > cap, "n={n}"),
                    Some((total, base)) => {
                        assert_eq!(total % 16, 0, "n={n}");
                        assert!(total >= base + (words as i32) * 8, "n={n}");
                        assert_eq!(base, if win64 { 32 } else { 0 });
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod r13w11_mega9_kind_screen_tests {
    /// Round 13 wave 11 (lane mega9, M13-6): the optimizing tier's copy of the
    /// "can an array be this receiver" rule (`inline_cache_pic`, which
    /// `ir_lower.rs` reads) must answer exactly what the single-pass cascade's
    /// `x64::inlining::static_receiver_admits_arrays` answers, or the two tiers
    /// disagree about which sites may skip the kind screen.
    #[test]
    fn the_optimizing_tier_copy_agrees_with_the_single_pass_rule() {
        for owner in [
            "",
            "java/lang/Object",
            "java/lang/Cloneable",
            "java/io/Serializable",
            "[I",
            "[Ljava/lang/String;",
            "[[J",
            "java/lang/String",
            "java/util/HashMap",
            "java/util/AbstractMap",
            "pkg/Obj",
            "java/lang/Objectx",
            "java/lang/Number",
        ] {
            assert_eq!(
                crate::inline_cache_pic::ic_static_receiver_admits_arrays(owner),
                crate::x64::inlining::static_receiver_admits_arrays(owner),
                "owner {owner:?}"
            );
        }
    }
}

#[cfg(test)]
mod r13w11_mega9_wide_cap_tests {
    use super::ic_stack_arg_block;

    /// Round 13 wave 11 (lane mega9, M13-8): a receiver plus eight arguments
    /// on Win64 (plus ten on SysV) gets a MIC block by default; the kill
    /// switch restores the round-11 cap of four context-ABI stack words.
    #[test]
    fn a_receiver_plus_eight_site_gets_a_block_unless_switched_off() {
        // Since the round-17 close the over-wide cap (16 words) is the
        // default: nine words fit.
        assert_eq!(
            ic_stack_arg_block(12, 4, true),
            Some((112, 32)),
            "nine words: over-wide"
        );
        // The wide cap of 8 words, the over-wide switch off.
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IC_OVERWIDE_STACK_WORDS", Some("0"))],
            || {
                // Win64: n = 9 (receiver + 8) needs 10 - 4 = 6 context-ABI words.
                assert_eq!(ic_stack_arg_block(9, 4, true), Some((80, 32)));
                // The widest admitted Win64 site: n = 11, 8 words, 32 + 64 = 96.
                assert_eq!(ic_stack_arg_block(11, 4, true), Some((96, 32)));
                assert_eq!(
                    ic_stack_arg_block(12, 4, true),
                    None,
                    "nine words: past the cap"
                );
                // SysV: n = 13 (receiver + 12) needs 14 - 6 = 8 words.
                assert_eq!(ic_stack_arg_block(13, 6, false), Some((64, 0)));
                assert_eq!(ic_stack_arg_block(14, 6, false), None);
            },
        );
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IC_WIDE_STACK_WORDS", Some("0"))],
            || {
                assert_eq!(
                    ic_stack_arg_block(7, 4, true),
                    Some((64, 32)),
                    "four words fit"
                );
                assert_eq!(
                    ic_stack_arg_block(8, 4, true),
                    None,
                    "five words: the old cap"
                );
                assert_eq!(ic_stack_arg_block(9, 4, true), None);
                assert_eq!(ic_stack_arg_block(9, 6, false), Some((32, 0)));
                assert_eq!(ic_stack_arg_block(10, 6, false), None);
            },
        );
    }
}

#[cfg(test)]
mod gcd_d9d_owned_args_site_tests {
    //! gcd d9/d (2026-09-28): the site half of the callee-owned-arguments rule.

    use super::caller_replay_to_call_is_exact as replay_exact;
    use super::sp_direct_call_args_owned_by_callee;

    /// The rule with its seventh term (gcd d10/f, the caller's replay) held
    /// `true`, so the d9/d table below states the other six unchanged.
    fn owned(
        enabled: bool,
        opcode: Option<u8>,
        invoke_kind: Option<u8>,
        sync_direct_site: bool,
        retire_cell: bool,
        pc_is_protected: bool,
    ) -> bool {
        sp_direct_call_args_owned_by_callee(
            enabled,
            opcode,
            invoke_kind,
            sync_direct_site,
            retire_cell,
            pc_is_protected,
            || true,
        )
    }

    const INVOKESTATIC: Option<u8> = Some(0xb8);
    const STATIC_KIND: Option<u8> = Some(3);

    /// A plain, unprotected, unsynchronized `invokestatic` with the switch on
    /// is the one shape that may leave its arguments to the callee.
    #[test]
    fn a_plain_static_site_leaves_its_arguments_to_the_callee() {
        assert!(owned(true, INVOKESTATIC, STATIC_KIND, false, false, false));
    }

    /// Each term withdraws it on its own: the switch, another opcode or
    /// invoke kind (an instance row handed to this arm), a caller-held
    /// synchronized site, a retire-cell site, a protected pc, no info.
    #[test]
    fn every_term_of_the_rule_withdraws_ownership() {
        assert!(
            !owned(false, INVOKESTATIC, STATIC_KIND, false, false, false),
            "=0"
        );
        for op in [0xb6u8, 0xb7, 0xb9] {
            assert!(
                !owned(true, Some(op), STATIC_KIND, false, false, false),
                "opcode {op:#x}"
            );
        }
        assert!(
            !owned(true, None, STATIC_KIND, false, false, false),
            "no opcode"
        );
        for kind in [0u8, 1, 2, 4] {
            assert!(
                !owned(true, INVOKESTATIC, Some(kind), false, false, false),
                "kind {kind}"
            );
        }
        assert!(
            !owned(true, INVOKESTATIC, None, false, false, false),
            "no JitInvokeInfo"
        );
        assert!(
            !owned(true, INVOKESTATIC, STATIC_KIND, true, false, false),
            "sync site"
        );
        assert!(
            !owned(true, INVOKESTATIC, STATIC_KIND, false, true, false),
            "retire cell"
        );
        assert!(
            !owned(true, INVOKESTATIC, STATIC_KIND, false, false, true),
            "protected pc"
        );
    }

    /// gcd d9/d row 2 at the inline cache: the hit files every reference
    /// argument but its receiver for the service-copy window.
    #[test]
    fn an_inline_cache_hit_files_every_reference_but_its_receiver() {
        use super::ic_hit_window_arg_oops as filed;
        assert_eq!(
            filed(&[true, true, false, true]),
            [false, true, false, true]
        );
        assert_eq!(filed(&[true]), [false]);
        assert!(filed(&[]).is_empty());
    }

    /// gcd d9/d row 4: a splice's direct call is admitted on the static
    /// rule's terms, its protected pc and its replay verdict deciding as
    /// there, and a virtual form keeps its copy.
    #[test]
    fn a_spliced_static_call_is_admitted_on_the_static_terms() {
        use super::splice_call_args_owned_by_callee as spliced;
        assert!(spliced(INVOKESTATIC, STATIC_KIND, false, || true));
        assert!(
            spliced(Some(0xb7), Some(1), false, || true),
            "invokespecial"
        );
        assert!(
            !spliced(INVOKESTATIC, STATIC_KIND, true, || true),
            "protected pc"
        );
        assert!(
            !spliced(INVOKESTATIC, STATIC_KIND, false, || false),
            "replay"
        );
        assert!(!spliced(Some(0xb6), Some(0), false, || true), "virtual");
        assert!(
            !spliced(INVOKESTATIC, None, false, || true),
            "no JitInvokeInfo"
        );
    }

    /// gcd d10/f (2026-09-28): a statically bound instance site (kind 1: an
    /// `invokespecial`, or a private `invokevirtual` / `invokeinterface`
    /// pinned to its owner) is admitted on the same terms; every virtual form
    /// (kinds 0/2, whose receiver class the service reads out of the copy)
    /// and every mismatched opcode/kind pair keeps the copy, and each other
    /// term still withdraws it.
    #[test]
    fn a_statically_bound_instance_site_is_admitted_on_the_same_terms() {
        const INVOKESPECIAL: Option<u8> = Some(0xb7);
        const SPECIAL_KIND: Option<u8> = Some(1);
        for op in [0xb6u8, 0xb7, 0xb9] {
            assert!(
                owned(true, Some(op), SPECIAL_KIND, false, false, false),
                "{op:#x}"
            );
            for kind in [0u8, 2, 3, 4] {
                assert!(
                    !owned(true, Some(op), Some(kind), false, false, false),
                    "{op:#x}/{kind}"
                );
            }
        }
        assert!(
            !owned(true, INVOKESTATIC, SPECIAL_KIND, false, false, false),
            "static kind 1"
        );
        for op in [0x00u8, 0xb5, 0xba] {
            assert!(
                !owned(true, Some(op), SPECIAL_KIND, false, false, false),
                "{op:#x}"
            );
        }
        assert!(
            !owned(false, INVOKESPECIAL, SPECIAL_KIND, false, false, false),
            "=0"
        );
        assert!(
            !owned(true, INVOKESPECIAL, None, false, false, false),
            "no JitInvokeInfo"
        );
        assert!(
            !owned(true, INVOKESPECIAL, SPECIAL_KIND, true, false, false),
            "sync site"
        );
        assert!(
            !owned(true, INVOKESPECIAL, SPECIAL_KIND, false, true, false),
            "retire cell"
        );
        assert!(
            !owned(true, INVOKESPECIAL, SPECIAL_KIND, false, false, true),
            "protected pc"
        );
    }

    /// gcd d10/f (2026-09-28): the seventh term. A site whose caller cannot
    /// be re-run from entry exactly keeps its copy, whatever the other six
    /// say; and the term is asked LAST (it scans the bytecode), so a site
    /// the other terms refuse never pays for it.
    #[test]
    fn a_caller_that_cannot_replay_exactly_keeps_the_copy() {
        fn plain(op: Option<u8>, kind: Option<u8>, replay: impl FnOnce() -> bool) -> bool {
            sp_direct_call_args_owned_by_callee(true, op, kind, false, false, false, replay)
        }
        for (op, kind) in [(0xb8u8, 3u8), (0xb7, 1)] {
            assert!(
                plain(Some(op), Some(kind), || true),
                "{op:#x}: exact replay"
            );
            assert!(
                !plain(Some(op), Some(kind), || false),
                "{op:#x}: inexact replay"
            );
        }
        let asked = std::cell::Cell::new(false);
        let probe = || {
            asked.set(true);
            true
        };
        let retire_cell = sp_direct_call_args_owned_by_callee(
            true,
            INVOKESTATIC,
            STATIC_KIND,
            false,
            true,
            false,
            probe,
        );
        assert!(!retire_cell);
        assert!(
            !asked.get(),
            "a retire-cell site must not scan the bytecode"
        );
    }

    /// The replay predicate on real shapes. Each method below is
    /// `<prefix>; invokestatic #1 (the candidate call at `pc`); ireturn`.
    #[test]
    fn the_caller_replay_is_exact_only_before_any_side_effect() {
        // static boolean staticCaller(int n, boolean check) {
        //     return dropStatic(new long[n], check);
        // }  -- `Gcd1ArgPinSpecialProbe`: allocation only.
        let pure = [
            0x1a, // 0: iload_0
            0xbc, 0x0b, // 1: newarray long
            0x1b, // 3: iload_1
            0xb8, 0x00, 0x01, // 4: invokestatic dropStatic
            0xac, // 7: ireturn
        ];
        assert!(replay_exact(&pure, pure.len(), 4, &[]));

        // static boolean caller(int mb, boolean check) {
        //     Object[] box = new Object[1];
        //     return dropAndCheck(make(mb, box), box, check);
        // }  -- `Gcd1ArgPinProbe.caller`: `make` is an invoke before the call.
        let invoke_first = [
            0x04, // 0: iconst_1
            0xbd, 0x00, 0x02, // 1: anewarray Object
            0x4d, // 4: astore_2
            0x1a, // 5: iload_0
            0x2c, // 6: aload_2
            0xb8, 0x00, 0x03, // 7: invokestatic make
            0x2c, // 10: aload_2
            0x1b, // 11: iload_1
            0xb8, 0x00, 0x01, // 12: invokestatic dropAndCheck
            0xac, // 15: ireturn
        ];
        assert!(!replay_exact(&invoke_first, invoke_first.len(), 12, &[]));
        // ... while the FIRST call in it (`make`) has a pure prefix.
        assert!(replay_exact(&invoke_first, invoke_first.len(), 7, &[]));

        // A field store before the call: `counter++` as `getstatic; iconst_1;
        // iadd; putstatic`.
        let store_first = [
            0xb2, 0x00, 0x04, // 0: getstatic counter
            0x04, // 3: iconst_1
            0x60, // 4: iadd
            0xb3, 0x00, 0x04, // 5: putstatic counter
            0x1a, // 8: iload_0
            0xb8, 0x00, 0x01, // 9: invokestatic
            0xac, // 12: ireturn
        ];
        assert!(!replay_exact(&store_first, store_first.len(), 9, &[]));

        // A store AFTER the call, inside a loop around it: the re-run's
        // extent is closed over the loop, so an earlier iteration's store
        // counts.
        let store_in_loop = [
            0x1a, // 0: iload_0            <- loop head
            0xb8, 0x00, 0x01, // 1: invokestatic
            0xb3, 0x00, 0x04, // 4: putstatic
            0xa7, 0xff, 0xf9, // 7: goto 0
        ];
        assert!(!replay_exact(&store_in_loop, store_in_loop.len(), 1, &[]));
        // Without the back edge the store is past the call and harmless.
        let store_after = [
            0x1a, // 0: iload_0
            0xb8, 0x00, 0x01, // 1: invokestatic
            0xb3, 0x00, 0x04, // 4: putstatic
            0xb1, // 7: return
        ];
        assert!(replay_exact(&store_after, store_after.len(), 1, &[]));

        // A monitor held across the call.
        let locked = [
            0x2a, // 0: aload_0
            0xc2, // 1: monitorenter
            0x2a, // 2: aload_0
            0xb8, 0x00, 0x01, // 3: invokestatic
            0x2a, // 6: aload_0
            0xc3, // 7: monitorexit
            0xb1, // 8: return
        ];
        assert!(!replay_exact(&locked, locked.len(), 3, &[]));
    }
}

#[cfg(test)]
mod r16w12_throw3_string_null_receiver {
    //! JIT round 16 wave 12 (lane throw3): the String access intrinsics' null
    //! receiver under `CRATONVM_JIT_STRING_INTRINSIC_NPE=1` raises through the
    //! reason-10 precise-frame stub at a protected site of a method compiled
    //! with precise exceptional frames, where the wave-3 rule kept the deopt.

    use super::{string_null_receiver_arm, StringNullReceiver};
    use crate::deopt::DeoptReason;
    use crate::x64::Compiler;
    use cratonvm_jit_api::npe_action;

    /// A bare `Compiler` with precise exceptional frames and one protected
    /// range, shaped like `deopt_stubs.rs`'s `r9w2_spdeopt_tests` one.
    fn precise_compiler(protected: Vec<(u32, u32)>) -> Compiler {
        let alloc_result = crate::regalloc::RegAllocResult {
            assignments: Vec::new(),
            xmm_assignments: Vec::new(),
            used_callee_saved: Vec::new(),
            used_xmm_regs: Vec::new(),
            block_live_in: Vec::new(),
        };
        let mut helpers = cratonvm_jit_api::JitRuntimeHelpers::default();
        // Any non-zero addresses: the stubs only have to be emittable.
        helpers.set_throw_bci = precise_compiler as usize;
        helpers.jit_npe_with_action = precise_compiler as usize;
        Compiler::new(
            "r16w12-throw3-test".to_string(),
            crate::ExecutableBuffer::new(4096).expect("test executable buffer"),
            0,
            0,
            8,
            false,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            alloc_result,
            false,
            helpers,
            0,
            false,
            false,
            false,
            true,
            false,
            protected,
        )
    }

    #[test]
    fn the_switch_off_or_a_splice_keeps_the_deopt() {
        for precise in [false, true] {
            assert_eq!(
                string_null_receiver_arm(false, false, precise),
                StringNullReceiver::Deopt
            );
            assert_eq!(
                string_null_receiver_arm(true, true, precise),
                StringNullReceiver::Deopt
            );
        }
    }

    #[test]
    fn a_protected_precise_site_takes_the_precise_stub_and_others_the_shared_one() {
        assert_eq!(
            string_null_receiver_arm(true, false, true),
            StringNullReceiver::PreciseFrame
        );
        assert_eq!(
            string_null_receiver_arm(true, false, false),
            StringNullReceiver::SharedStub
        );
    }

    /// The precise arm files a `PendingException` point at the site, a
    /// reason-10 stub, and the INVOKE_RECEIVER action the stub hands to
    /// `jit_npe_with_action` (the JEP 358 text names the invoke).
    #[test]
    fn the_precise_arm_publishes_the_frame_with_the_invoke_action() {
        const SITE: usize = 13;
        let mut c = precise_compiler(vec![(0, 40)]);
        assert!(c.pc_is_protected(SITE));
        assert!(c.emit_precise_array_npe_check(SITE, npe_action::INVOKE_RECEIVER));
        assert_eq!(c.deopt_point_pcs, vec![SITE]);
        assert!(matches!(
            c.deopt_points[0].reason,
            DeoptReason::PendingException
        ));
        assert!(c.exc_frame_box_ptr_by_bci.contains_key(&SITE));
        assert_eq!(
            c.precise_npe_action_by_bci.get(&SITE).copied(),
            Some(u32::from(npe_action::INVOKE_RECEIVER))
        );
        assert_eq!(c.deopt_stubs.len(), 1);
        assert_eq!((c.deopt_stubs[0].1, c.deopt_stubs[0].2), (SITE, 10));
    }

    /// Wave 13 (w12b: `msg=null` under load): the String arm's trap-site key
    /// rides above the action in the word the reason-10 stub hands
    /// `jit_npe_with_action`, so the NPE's snapshot names the invoke's bci
    /// exactly instead of the frame's stale safepoint-id slot.
    #[test]
    fn the_keyed_precise_arm_packs_the_trap_key_into_the_stub_word() {
        const SITE: usize = 13;
        const KEY: u32 = 0x0012_34;
        let packed = u32::from(npe_action::INVOKE_RECEIVER) | (KEY << 8);
        let mut c = precise_compiler(vec![(0, 40)]);
        assert!(c.emit_precise_npe_check_keyed(SITE, npe_action::INVOKE_RECEIVER, KEY));
        assert_eq!(
            c.precise_npe_action_by_bci.get(&SITE).copied(),
            Some(packed)
        );
        let stub_start = c.buf.pos();
        c.emit_deopt_stubs();
        let stub = &c.buf.as_slice()[stub_start..c.buf.pos()];
        assert!(
            stub.windows(4).any(|w| w == packed.to_le_bytes()),
            "the reason-10 stub must pass the packed action word"
        );
    }

    /// Without a key the word is the bare action: the array and `putfield`
    /// sites' stubs are byte-identical to before.
    #[test]
    fn the_unkeyed_precise_arm_files_the_bare_action() {
        let mut c = precise_compiler(vec![(0, 40)]);
        assert!(c.emit_precise_array_npe_check(7, npe_action::INVOKE_RECEIVER));
        assert_eq!(
            c.precise_npe_action_by_bci.get(&7).copied(),
            Some(u32::from(npe_action::INVOKE_RECEIVER))
        );
    }

    /// Outside every protected range the precise arm emits nothing and
    /// answers `false`, so the caller keeps its own check.
    #[test]
    fn an_unprotected_site_gets_no_precise_stub() {
        let mut c = precise_compiler(vec![(100, 140)]);
        let before = c.buf.pos();
        assert!(!c.emit_precise_array_npe_check(13, npe_action::INVOKE_RECEIVER));
        assert_eq!(c.buf.pos(), before);
        assert!(c.deopt_stubs.is_empty());
        assert!(c.precise_npe_action_by_bci.is_empty());
    }
}

/// JIT round 17 wave 1, lane strings (STR16-P1): the compile-time plan of the
/// inline `StringBuilder.toString()` refuses a String layout with no class id
/// whatever the environment (the switch off is the first refusal, the missing
/// id the next), so such a site can only ever emit its decline.
#[cfg(test)]
mod r17_strings_sb_to_string_plan_tests {
    use super::sb_to_string_plan;

    #[test]
    fn a_layout_without_a_string_class_id_is_refused() {
        let outer = crate::StringFieldLayout::new(0, Some(1), 2, 0);
        let plan = sb_to_string_plan(&outer);
        assert!(plan.is_err());
        if !crate::jit_sb_to_string_inline_enabled() {
            assert_eq!(plan, Err("switch off"));
        }
    }
}

/// nio21 wave 10 L1 (`CRATONVM_ZGC_JIT_START_BIT_BEFORE_COMMIT`): the inline
/// `StringBuilder.toString()` under ZGC sets both start bits BEFORE its
/// cursor commit (`=0`: after it), read from the emitted bytes; and the
/// single-pass box sites hand the announce to the decline form.
#[cfg(test)]
mod nio21w10_sb_to_string_start_bits_tests {
    use super::*;

    const CURSOR_OFF: i32 = 0x40;
    /// `OR [RDX + R8*8], RAX`: `emit_zgc_start_bit_store_prechecked`'s store.
    const OR_BIT: [u8; 4] = [0x4A, 0x09, 0x04, 0xC2];

    fn find_all(hay: &[u8], needle: &[u8]) -> Vec<usize> {
        hay.windows(needle.len())
            .enumerate()
            .filter(|(_, w)| *w == needle)
            .map(|(i, _)| i)
            .collect()
    }

    fn tail_bytes(setting: Option<&str>) -> Vec<u8> {
        let _flag = cratonvm_types::flags::override_thread(
            cratonvm_types::flags::VmFlags::from_env_with_edits(&[(
                "CRATONVM_ZGC_JIT_START_BIT_BEFORE_COMMIT",
                setting,
            )]),
        );
        let mut c = crate::x64::flag_and_header_contracts::bounds_check_test_compiler();
        c.helpers.tlab_cursor_offset_in_thread = CURSOR_OFF as usize; // Cast: a small offset
        c.helpers.tlab_end_offset_in_thread = CURSOR_OFF as usize + 8; // Cast: a small offset
        c.helpers.class_id_offset_in_obj = 0;
        let plan = SbToStringPlan {
            string_class_id: 0x0765_4324,
            string_total: 24,
            value_off: 16,
            replace_guard: (0x1000, 0),
            max_count: 1024,
            len_d8: 8,
            data_d8: 16,
            kind_d8: 7,
            byte_array_tag: 0,
            byte_array_mark: 0,
            utf16_coder: None,
        };
        let gc = SbToStringGc {
            zgc_start_bits: true,
            g1_same_region: false,
        };
        let arm = SbToStringArm {
            utf16_coder: None,
            narrow: false,
            taken_row: 0,
        };
        let mut decline = Vec::new();
        let at = c.buf.pos();
        c.emit_sb_to_string_tail(&plan, gc, arm, false, &mut decline, None);
        c.buf.as_slice()[at..c.buf.pos()].to_vec()
    }

    fn commit_bytes() -> Vec<u8> {
        // MOV [R10 + CURSOR_OFF], RAX.
        let mut v = vec![0x49, 0x89, 0x82];
        v.extend_from_slice(&CURSOR_OFF.to_le_bytes());
        v
    }

    #[test]
    fn both_start_bits_precede_the_commit() {
        let b = tail_bytes(None);
        let ors = find_all(&b, &OR_BIT);
        let commits = find_all(&b, &commit_bytes());
        assert_eq!((ors.len(), commits.len()), (2, 1), "two bits, one commit");
        assert!(
            ors.iter().all(|o| *o < commits[0]),
            "{ors:?} vs {commits:?}"
        );
    }

    #[test]
    fn the_kill_switch_restores_commit_then_bits() {
        let b = tail_bytes(Some("0"));
        let ors = find_all(&b, &OR_BIT);
        let commits = find_all(&b, &commit_bytes());
        assert_eq!((ors.len(), commits.len()), (2, 1));
        assert!(
            ors.iter().all(|o| *o > commits[0]),
            "{ors:?} vs {commits:?}"
        );
    }

    /// The box sites no longer pair the decline form with a separate
    /// commit-then-rollback; the decline form announces (source scan).
    #[test]
    fn the_box_sites_hand_the_announce_to_the_decline_form() {
        let src = include_str!("op_invoke.rs");
        let rollback = ["emit_zgc_announce_", "or_rollback("].concat();
        assert_eq!(src.matches(rollback.as_str()).count(), 0);
        // The argument line alone (another line names the same call after a
        // field name).
        let arg = [
            "\n            cratonvm_types::jit_tlab_registration_",
            "required(),\n",
        ]
        .concat();
        assert_eq!(src.matches(arg.as_str()).count(), 2, "both box sites");
    }
}

/// JIT round 18 wave 9, lane osrframe: the sibling tail call keeps the frame
/// of a caller whose target takes the VM context, unless switched off.
#[cfg(test)]
mod r18_osrframe_tailcall_vm_helper_tests {
    use super::{sibling_tail_target_admitted, sp_tailcall_keeps_vm_helper_frame};

    #[test]
    fn a_context_taking_target_is_refused_while_the_fix_is_on() {
        assert!(!sibling_tail_target_admitted(true, true, false));
        assert!(sibling_tail_target_admitted(false, true, false));
        assert!(sibling_tail_target_admitted(true, false, false));
        assert!(sibling_tail_target_admitted(false, false, false));
    }

    /// JIT round 19 proposal wave 7, lane tail7 (OSRFRAME18-2): only a helper
    /// classified as never reaching the VM gets the tail form back while the
    /// frame-keeping fix is on; the classification changes nothing else.
    #[test]
    fn only_a_never_reaching_helper_gets_the_tail_form_back() {
        assert!(sibling_tail_target_admitted(true, true, true));
        assert!(!sibling_tail_target_admitted(true, true, false));
        assert!(sibling_tail_target_admitted(false, true, true));
        assert!(sibling_tail_target_admitted(true, false, true));
    }

    #[test]
    fn the_leaf_helper_switch_is_opt_in() {
        let key = "CRATONVM_JIT_SP_TAIL_LEAF_HELPERS";
        let unset = cratonvm_types::flags::with_thread_overrides(
            &[(key, None)],
            super::sp_tail_leaf_helpers_enabled,
        );
        let on = cratonvm_types::flags::with_thread_overrides(
            &[(key, Some("1"))],
            super::sp_tail_leaf_helpers_enabled,
        );
        assert!(!unset);
        assert!(on);
    }

    #[test]
    fn the_switch_is_default_on_with_a_kill_word() {
        let key = "CRATONVM_JIT_SP_TAILCALL_KEEPS_VM_HELPER_FRAME";
        let on = cratonvm_types::flags::with_thread_overrides(
            &[(key, None)],
            sp_tailcall_keeps_vm_helper_frame,
        );
        let off = cratonvm_types::flags::with_thread_overrides(
            &[(key, Some("0"))],
            sp_tailcall_keeps_vm_helper_frame,
        );
        assert!(on);
        assert!(!off);
    }

    /// JIT round 19 proposal wave (lane osr19, OSRFRAME18-3 of
    /// `jit-r18-osrframe-proposals.md`): a source-text ratchet. Tearing this
    /// frame down before a call that may reach the VM left the frame-chain
    /// mirror naming a dead frame (`r18-compatible-osr-inlined-native-throw-
    /// loses-the-inline-frame-FIXED-20261006.md`). The sibling tail call is
    /// the only frame-tearing call site in production code, and it asks
    /// `sibling_tail_target_admitted` (which refuses a context-taking target)
    /// and `info_ptr.is_none()` (no deopt stash) first. A second caller of
    /// `emit_epilogue_without_ret`, or a refactor that drops either term from
    /// the one that exists, fails here instead of as a wrong stack trace.
    /// Brittle to renames on purpose: whoever renames re-reads the argument.
    /// Production text is each file cut at its first `#[cfg(test)]`.
    #[test]
    fn frame_teardown_before_a_tail_jump_is_only_the_admitted_sibling_call() {
        fn walk(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            for entry in std::fs::read_dir(dir).expect("jit/src is readable") {
                let path = entry.expect("dir entry").path();
                if path.is_dir() {
                    walk(&path, out);
                } else if path.extension().is_some_and(|e| e == "rs") {
                    out.push(path);
                }
            }
        }
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut files = Vec::new();
        walk(&root, &mut files);
        assert!(files.len() > 20, "the walk found jit/src");
        let needle = format!(".{}()", "emit_epilogue_without_ret");
        let mut sites: Vec<(String, String)> = Vec::new();
        for path in &files {
            let text = std::fs::read_to_string(path).expect("source is UTF-8");
            let production = text.split("#[cfg(test)]").next().unwrap_or("");
            let mut from = 0;
            while let Some(at) = production[from..].find(&needle) {
                let abs = from + at;
                // The arm: up to 60 lines before the call.
                let before = &production[..abs];
                let arm_start = before.rmatch_indices('\n').nth(59).map_or(0, |(i, _)| i);
                let name = path
                    .strip_prefix(&root)
                    .map(|p| p.to_string_lossy().replace('\\', "/"))
                    .unwrap_or_default();
                sites.push((name, production[arm_start..abs].to_string()));
                from = abs + needle.len();
            }
        }
        let names: Vec<&str> = sites.iter().map(|(n, _)| n.as_str()).collect();
        assert_eq!(
            names,
            vec!["x64/op_invoke.rs"],
            "a new frame-tearing call site: prove its target cannot reach the VM \
             before the frame is gone (see OSRFRAME18-3), then update this ratchet"
        );
        let arm = &sites[0].1;
        assert!(
            arm.contains("sibling_tail_target_admitted("),
            "the sibling tail call no longer asks sibling_tail_target_admitted"
        );
        assert!(
            arm.contains("info_ptr.is_none()"),
            "the sibling tail call no longer refuses a callee that can stash a deopt frame"
        );
    }
}

/// JIT round 19 proposal wave 7, lane tail7 (MEGA619-1 = the caller half of
/// THROWS18-6): the lazy return-tail republish, and the obligation that every
/// VM entry a return-tail call can still reach republishes first.
#[cfg(test)]
mod tail7_lazy_return_republish_tests {
    use super::lazy_return_republish_rule;

    fn ok(next: u8) -> bool {
        lazy_return_republish_rule(Some(next), false, false, false, false, b'I', false)
    }

    #[test]
    fn only_a_plain_return_tail_call_drops_its_republish() {
        for op in 0xacu8..=0xb1 {
            assert!(ok(op), "xreturn {op:#04x}");
        }
        // Anything else may enter the VM before the next republish point.
        for op in [0x00u8, 0x57, 0x3b, 0xa7, 0xb6, 0xb8, 0xbf, 0xc2] {
            assert!(!ok(op), "op {op:#04x}");
        }
        assert!(!lazy_return_republish_rule(
            None, false, false, false, false, b'I', false
        ));
    }

    #[test]
    fn every_vm_entering_edge_of_the_return_refuses_the_elision() {
        let base = |bt, prot, lock, sync, ret, watch| {
            lazy_return_republish_rule(Some(0xac), bt, prot, lock, sync, ret, watch)
        };
        assert!(base(false, false, false, false, b'L', false));
        assert!(base(false, false, false, false, b'V', false));
        assert!(!base(true, false, false, false, b'I', false), "merge point");
        assert!(
            !base(false, true, false, false, b'I', false),
            "local handler / reason-9"
        );
        assert!(
            !base(false, false, true, false, b'I', false),
            "self-lock release"
        );
        assert!(
            !base(false, false, false, true, b'I', false),
            "caller-held release"
        );
        for wide in [b'J', b'D', b'F'] {
            assert!(
                !base(false, false, false, false, wide, false),
                "dispatch_threw peek"
            );
        }
        assert!(
            !base(false, false, false, false, b'I', true),
            "watchpoint epilogue"
        );
    }

    #[test]
    fn the_switch_is_opt_in() {
        let key = "CRATONVM_JIT_SP_LAZY_RETURN_REPUBLISH";
        let unset = cratonvm_types::flags::with_thread_overrides(
            &[(key, None)],
            super::sp_lazy_return_republish_enabled,
        );
        assert!(!unset);
    }

    /// Production text of `file` (relative to `jit/src`), cut at its first
    /// `#[cfg(test)]`.
    fn production(file: &str) -> String {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("src")
            .join(file);
        let text = std::fs::read_to_string(&path).expect("source is UTF-8");
        text.split("#[cfg(test)]").next().unwrap_or("").to_string()
    }

    /// The body of `fn name` in `text`: from its signature to the next
    /// `\n    fn ` / `\n    pub` item at the same indentation.
    fn body<'a>(text: &'a str, name: &str) -> &'a str {
        let start = text.find(&format!("fn {name}(")).expect("function exists");
        let rest = &text[start + 1..];
        let end = [
            "\n    fn ",
            "\n    pub(super) fn ",
            "\n    pub(crate) fn ",
            "\n    pub fn ",
        ]
        .iter()
        .filter_map(|m| rest.find(m))
        .min()
        .unwrap_or(rest.len());
        &text[start..start + 1 + end]
    }

    /// The callee-deopt service is the one VM entry a return-tail call's
    /// sentinel edge makes before the exception edge returns: it must publish
    /// this frame BEFORE it calls the service, whether or not the site is
    /// open. A refactor that moves the republish after the call (or under the
    /// `!site_open` arm) fails here.
    #[test]
    fn the_callee_deopt_service_republishes_before_its_call() {
        let text = production("x64/deopt_stubs.rs");
        let f = body(&text, "emit_callee_deopt_service_check");
        let republish = f
            .find("self.emit_post_call_rbp_republish();")
            .expect("the service check republishes");
        let call = f
            .find("self.emit_call_absolute(helper);")
            .expect("the service check calls its helper");
        assert!(
            republish < call,
            "the republish must precede the service call"
        );
        let open_arm = f.find("if !site_open {").expect("the open-site arm exists");
        assert!(
            republish < open_arm,
            "the republish must not sit under the open-site screen"
        );
    }

    /// The shared sentinel exit an UNPROTECTED site's exception edge takes
    /// calls nothing but `set_throw_bci` (a thread-local store) before it
    /// returns. A new helper call there would be a VM entry the lazy
    /// return-tail republish has not covered.
    #[test]
    fn the_shared_sentinel_exit_calls_only_set_throw_bci() {
        let text = production("x64/deopt_stubs.rs");
        let f = body(&text, "emit_exception_check_stub");
        let calls: Vec<&str> = f
            .match_indices("self.emit_call_absolute(")
            .map(|(i, _)| {
                let tail = &f[i..];
                &tail[..tail.find(')').map_or(tail.len(), |e| e + 1)]
            })
            .collect();
        assert_eq!(
            calls,
            vec!["self.emit_call_absolute(self.helpers.set_throw_bci)"],
            "a new call on the shared sentinel exit: prove it cannot walk the \
             stack, or refuse it in `lazy_return_republish_rule`"
        );
    }

    /// Every production site that skips the post-call republish asks the
    /// return-tail rule: four sites, each guarded by its admission flag.
    #[test]
    fn every_skipped_republish_is_a_ruled_return_tail_site() {
        let text = production("x64/op_invoke.rs");
        let guarded = text.matches("if !lazy_return_republish {").count()
            + text.matches("if !lazy_ic_hit_republish {").count();
        assert_eq!(
            guarded, 4,
            "static direct, instance direct, PIC hit, MIC hit"
        );
        let asks = text
            .matches("self.sp_lazy_return_republish_admitted(")
            .count();
        assert_eq!(asks, 3, "two direct arms and the inline-cache arm");
    }
}

#[cfg(test)]
mod i59_l2_splice_post_call_exit_tests {
    use super::{
        splice_caller_scope_is_transferable, POST_CALL_OWN_POINT_STUB_TAG,
        SPLICE_POST_CALL_STUB_TAG,
    };
    use crate::deopt::{FrameState, FrameValue, MonitorInfo};

    fn caller(locals: Vec<FrameValue>, stack: Vec<FrameValue>) -> FrameState {
        FrameState {
            method_key: "Caller.run:()I".to_string(),
            bci: 7,
            locals,
            stack,
            monitors: Vec::new(),
            caller: None,
        }
    }

    /// Interpreter round i2 wave 59, lane L2: a caller scope rebuilt at an
    /// exit INSIDE a splice may name only what the spliced body cannot have
    /// moved -- constants, frame words, callee-saved GPRs.
    #[test]
    fn a_caller_scope_is_transferable_only_from_homes_the_splice_keeps() {
        let homes = caller(
            vec![
                FrameValue::StackSlotRef(-16),
                FrameValue::Int(3),
                FrameValue::Undefined,
                FrameValue::RegisterRef(3),
                FrameValue::RegisterLong(12),
                FrameValue::Register(15),
            ],
            vec![FrameValue::StackSlotLong(-24), FrameValue::Object(0)],
        );
        assert!(splice_caller_scope_is_transferable(&homes));
        for clobbered in [
            FrameValue::Register(8),
            FrameValue::RegisterRef(9),
            FrameValue::Register(0),
            FrameValue::XmmDouble(1),
            FrameValue::XmmFloat(0),
            FrameValue::Unsupported,
            FrameValue::VirtualObjectRef(4),
        ] {
            let fs = caller(vec![clobbered.clone()], Vec::new());
            assert!(
                !splice_caller_scope_is_transferable(&fs),
                "{clobbered:?} in a local"
            );
            let fs = caller(Vec::new(), vec![clobbered.clone()]);
            assert!(
                !splice_caller_scope_is_transferable(&fs),
                "{clobbered:?} on the stack"
            );
        }
        let mut locked = caller(vec![FrameValue::StackSlotRef(-16)], Vec::new());
        locked.monitors.push(MonitorInfo {
            object: FrameValue::StackSlotRef(-16),
            lock_depth: 1,
            relock: false,
        });
        assert!(
            !splice_caller_scope_is_transferable(&locked),
            "a held monitor"
        );
        // Wave 62: RSI and RDI are callee-saved local homes on Windows only.
        for reg in [6u8, 7] {
            let fs = caller(vec![FrameValue::RegisterLong(reg)], Vec::new());
            assert_eq!(
                splice_caller_scope_is_transferable(&fs),
                cfg!(target_os = "windows"),
                "register {reg}"
            );
        }
        assert_eq!(
            super::splice_caller_scope_refusal(&caller(vec![FrameValue::Register(8)], Vec::new())),
            Some("local 0 = Register(8)".to_string())
        );
    }

    /// The splice exit's stub tag is its own: tag 13 resolves by bci, 14 by
    /// index, and neither is a deopt reason the stub list already uses.
    #[test]
    fn the_splice_exit_stub_tag_is_distinct() {
        assert_ne!(SPLICE_POST_CALL_STUB_TAG, POST_CALL_OWN_POINT_STUB_TAG);
        assert!(!(2..=12).contains(&SPLICE_POST_CALL_STUB_TAG));
    }
}

#[cfg(test)]
mod nio20_w2_sp_thin_helper_prefix_tests {
    //! nio20 wave 2, lane L2: the single-pass `getClass()` and `Unsafe`
    //! accessor prefixes of the plain instance thin-helper arm.

    use super::*;

    fn has(bytes: &[u8], needle: &[u8]) -> bool {
        bytes.windows(needle.len()).any(|w| w == needle)
    }

    #[test]
    fn the_getclass_prefix_reads_the_word_table_and_emits_nothing_without_one() {
        if crate::x64::zgc_read_barrier_blocks_inline_fields() || !crate::getclass_inline_enabled()
        {
            return;
        }
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.object_get_class = 0x1000; // baked, never executed
        let start = c.buf.pos();
        // No table on this compile: nothing emitted, the call stays alone.
        assert!(c
            .try_emit_sp_getclass_prefix(7, &[StackSlot::Frame(16)])
            .is_none());
        assert_eq!(c.buf.pos(), start);
        c.direct_helpers.getclass_mirror_words = 0x7f00_0000_1000;
        // An XMM receiver is refused before any byte.
        assert!(c
            .try_emit_sp_getclass_prefix(7, &[StackSlot::Xmm(1)])
            .is_none());
        assert_eq!(c.buf.pos(), start);
        assert!(c
            .try_emit_sp_getclass_prefix(7, &[StackSlot::Frame(16)])
            .is_some());
        let emitted = c.buf.as_slice()[start..].to_vec();
        // CMP RAX,[R10] (the capacity word) and MOV RAX,[R10+RAX*8+8] (the
        // class's word): the optimizing tier's two loads, byte for byte.
        assert!(has(&emitted, &[0x49, 0x3B, 0x02]));
        assert!(has(&emitted, &[0x49, 0x8B, 0x44, 0xC2, 0x08]));
        // nio21 wave 1 L5: the primitive-array arm, the optimizing tier's bytes.
        let (arm, _) = crate::ir_lower::getclass_prim_array_lookup_bytes();
        assert_eq!(
            crate::ir_lower::getclass_prim_array_words_enabled(),
            has(&emitted, &arm[..8])
        );
        // nio21 wave 2 L5: the reference-array arm's tag compare,
        // CMP BYTE [RAX+KIND_TAGS], 0x01.
        assert_eq!(
            crate::ir_lower::getclass_ref_array_words_enabled(),
            has(
                &emitted,
                &[
                    0x80,
                    0x78,
                    cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8,
                    0x01
                ]
            )
        );
    }

    #[test]
    fn the_unsafe_prefix_serves_only_admitted_thin_bound_accessors() {
        if !crate::direct_helpers::unsafe_accessor_inline_enabled() {
            return;
        }
        let args = [
            StackSlot::Frame(8),
            StackSlot::Frame(16),
            StackSlot::Frame(24),
        ];
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.unsafe_get_int = 0x2000; // baked, never executed
        c.direct_helpers.unsafe_put_long = 0x3000;
        let start = c.buf.pos();
        // No admission word: nothing.
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x2000, 2, b'I', &args)
            .is_none());
        // Every bit but `getInt`'s (row 3): still nothing.
        c.direct_helpers.unsafe_inline_admitted = 0x3FF & !(1 << 3);
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x2000, 2, b'I', &args)
            .is_none());
        c.direct_helpers.unsafe_inline_admitted = 0x3FF;
        // A helper this prefix does not know, or a shape that does not match
        // the accessor, keeps the call.
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x4000, 2, b'I', &args)
            .is_none());
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x2000, 2, b'J', &args)
            .is_none());
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x2000, 3, b'I', &args)
            .is_none());
        assert_eq!(c.buf.pos(), start);
        // `getInt(Object,long)`: MOVSXD RAX, DWORD [RAX+R11].
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x2000, 2, b'I', &args)
            .is_some());
        let get = c.buf.as_slice()[start..].to_vec();
        assert!(has(&get, &[0x4A, 0x63, 0x04, 0x18]));
        // `putLong(Object,long,long)`: MOV [RAX+R11], RDX.
        let mid = c.buf.pos();
        let put_args = [args[0], args[1], args[2], StackSlot::Frame(32)];
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x3000, 3, b'V', &put_args)
            .is_some());
        let put = c.buf.as_slice()[mid..].to_vec();
        assert!(has(&put, &[0x4A, 0x89, 0x14, 0x18]));
    }

    /// nio21 wave 4 L4: the volatile int/long thin binds take the same prefix,
    /// behind their own bits (10..14), with an alignment test, a plain `MOV`
    /// load and an `XCHG` store -- never the plain `MOV` store.
    #[test]
    fn nio21_w4_the_volatile_rows_test_alignment_and_store_with_xchg() {
        if !crate::direct_helpers::unsafe_accessor_inline_enabled()
            || !crate::direct_helpers::unsafe_volatile_inline_enabled()
        {
            return;
        }
        let args = [
            StackSlot::Frame(8),
            StackSlot::Frame(16),
            StackSlot::Frame(24),
        ];
        let put_args = [args[0], args[1], args[2], StackSlot::Frame(32)];
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.unsafe_get_long_volatile = 0x5000; // baked, never executed
        c.direct_helpers.unsafe_put_int_volatile = 0x6000;
        // The plain rows' bits do not admit the volatile rows.
        c.direct_helpers.unsafe_inline_admitted = 0x3FF;
        let start = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x5000, 2, b'J', &args)
            .is_none());
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x6000, 3, b'V', &put_args)
            .is_none());
        assert_eq!(c.buf.pos(), start);
        c.direct_helpers.unsafe_inline_admitted = 0x3FFF;
        // `getLongVolatile`: TEST R11B, 7 ; JNZ, then MOV RAX, QWORD [RAX+R11].
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x5000, 2, b'J', &args)
            .is_some());
        let get = c.buf.as_slice()[start..].to_vec();
        assert!(has(&get, &[0x41, 0xF6, 0xC3, 0x07, 0x0F, 0x85]));
        assert!(has(&get, &[0x4A, 0x8B, 0x04, 0x18]));
        // `putIntVolatile`: TEST R11B, 3 ; JNZ, then XCHG [RAX+R11], EDX.
        let mid = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x6000, 3, b'V', &put_args)
            .is_some());
        let put = c.buf.as_slice()[mid..].to_vec();
        assert!(has(&put, &[0x41, 0xF6, 0xC3, 0x03, 0x0F, 0x85]));
        assert!(has(&put, &[0x42, 0x87, 0x14, 0x18]));
        assert!(
            !has(&put, &[0x42, 0x89, 0x14, 0x18]),
            "a volatile put must not be a plain MOV"
        );
    }

    /// nio21 wave 5 L3: the `compareAndSet{Int,Long}` thin binds take the RMW
    /// prefix behind their CAS bit (14 / 15): the alignment and synthetic-band
    /// screen, then one `LOCK CMPXCHG` with the result from `SETE`.
    #[test]
    fn nio21_w5_the_cas_rows_emit_one_lock_cmpxchg_behind_their_bit() {
        if !crate::direct_helpers::unsafe_accessor_inline_enabled()
            || !crate::direct_helpers::unsafe_rmw_inline_enabled()
        {
            return;
        }
        let args: Vec<StackSlot> = (1..=5).map(|k| StackSlot::Frame(8 * k)).collect();
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.unsafe_cas_int = 0x7000; // baked, never executed
        c.direct_helpers.unsafe_cas_long = 0x7100;
        // The accessor and volatile bits do not admit a CAS.
        c.direct_helpers.unsafe_inline_admitted = 0x3FFF;
        let start = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7000, 4, b'Z', &args)
            .is_none());
        c.direct_helpers.unsafe_inline_admitted = 0xFFFF;
        // The wrong shape keeps the call.
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7000, 4, b'I', &args)
            .is_none());
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7000, 3, b'Z', &args[..4])
            .is_none());
        assert_eq!(c.buf.pos(), start);
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7000, 4, b'Z', &args)
            .is_some());
        let cas = c.buf.as_slice()[start..].to_vec();
        assert!(
            has(&cas, &[0x41, 0xF6, 0xC3, 0x03, 0x0F, 0x85]),
            "TEST R11B, 3 ; JNZ"
        );
        // nio21 wave 7 L3: the synthetic-band decline only under the
        // natives' old arm order.
        assert_eq!(
            has(
                &cas,
                &[0x49, 0x81, 0xFB, 0x00, 0x00, 0x00, 0x20, 0x0F, 0x83]
            ),
            !crate::direct_helpers::unsafe_array_before_synthetic_enabled()
        );
        assert!(has(
            &cas,
            &[0x49, 0x92, 0xF0, 0x43, 0x0F, 0xB1, 0x14, 0x1A, 0x0F, 0x94, 0xC0]
        ));
        let mid = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7100, 4, b'Z', &args)
            .is_some());
        let cas8 = c.buf.as_slice()[mid..].to_vec();
        assert!(has(&cas8, &[0xF0, 0x4B, 0x0F, 0xB1, 0x14, 0x1A]));
        // The SP row table names both cells.
        assert_eq!(
            sp_thin_prefix_row(&c.direct_helpers, 0x7000, true, 4, b'Z'),
            Some(SpThinPrefix::UnsafeAccess)
        );
    }

    /// nio21 wave 7 L3 (W6-L3-1): with the VM's cell table baked, the CAS
    /// prefix sends a non-array base to the instance-field arm (the kind test
    /// before the array screen, the cell screen after the hit path, a jump
    /// back to the shared RMW); without it, no field arm is emitted.
    #[test]
    fn nio21_w7_the_cas_prefix_has_a_field_arm_only_with_the_cell_table() {
        if !crate::direct_helpers::unsafe_accessor_inline_enabled()
            || !crate::direct_helpers::unsafe_rmw_inline_enabled()
            || crate::direct_helpers::unsafe_field_arm_words(&crate::DirectHelperTable {
                unsafe_field_cells: 0x10_0000,
                ..crate::DirectHelperTable::EMPTY
            })
            .is_none()
        {
            return;
        }
        let args: Vec<StackSlot> = (1..=5).map(|k| StackSlot::Frame(8 * k)).collect();
        let cells_imm = [0x49, 0xBA, 0x00, 0x00, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00];
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.unsafe_cas_long = 0x7100;
        c.direct_helpers.unsafe_inline_admitted = 0xFFFF;
        let start = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7100, 4, b'Z', &args)
            .is_some());
        let without = c.buf.as_slice()[start..].to_vec();
        assert!(!has(&without, &cells_imm), "no table, no field arm");
        c.direct_helpers.unsafe_field_cells = 0x10_0000;
        let mid = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7100, 4, b'Z', &args)
            .is_some());
        let with = c.buf.as_slice()[mid..].to_vec();
        let (kind, _) = crate::direct_helpers::unsafe_inline_not_array_bytes();
        assert!(has(&with, &kind[..kind.len() - 4]), "the kind test");
        assert!(has(&with, &cells_imm), "MOV R10, cells");
        assert!(
            has(&with, &[0x43, 0x8D, 0x14, 0x1B, 0x83, 0xCA, 0x01]),
            "the long key"
        );
        // One LOCK CMPXCHG, shared by both arms.
        let cmpxchg = [0xF0, 0x4B, 0x0F, 0xB1, 0x14, 0x1A];
        assert_eq!(
            with.windows(cmpxchg.len())
                .filter(|w| *w == &cmpxchg[..])
                .count(),
            1
        );
    }

    /// JIT round 20 wave 11, lane pAtom (W7-L3-1 / AT-3): with the VM's cell
    /// table baked, a volatile int get / long put sends a non-array base to
    /// the instance-field arm and joins the array arm's ONE `MOVSXD` / `XCHG`;
    /// without the table (or for a plain accessor) no field arm is emitted.
    #[test]
    fn r20_patom_volatile_accessors_have_a_field_arm_only_with_the_cell_table() {
        if !crate::direct_helpers::unsafe_accessor_inline_enabled()
            || !crate::direct_helpers::unsafe_volatile_inline_enabled()
            || !crate::direct_helpers::unsafe_volatile_field_inline_enabled()
            || crate::direct_helpers::unsafe_field_arm_words(&crate::DirectHelperTable {
                unsafe_field_cells: 0x10_0000,
                ..crate::DirectHelperTable::EMPTY
            })
            .is_none()
        {
            return;
        }
        let args: Vec<StackSlot> = (1..=4).map(|k| StackSlot::Frame(8 * k)).collect();
        let cells_imm = [0x49, 0xBA, 0x00, 0x00, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00];
        let (kind, _) = crate::direct_helpers::unsafe_inline_not_array_bytes();
        let count =
            |hay: &[u8], needle: &[u8]| hay.windows(needle.len()).filter(|w| *w == needle).count();
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.unsafe_get_int_volatile = 0x7200;
        c.direct_helpers.unsafe_put_long_volatile = 0x7300;
        c.direct_helpers.unsafe_get_int = 0x7400;
        c.direct_helpers.unsafe_inline_admitted = 0xFFFF;
        // No table: the volatile get has no field arm.
        let start = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7200, 2, b'I', &args[..3])
            .is_some());
        let without = c.buf.as_slice()[start..].to_vec();
        assert!(!has(&without, &cells_imm), "no table, no field arm");
        c.direct_helpers.unsafe_field_cells = 0x10_0000;
        // `getIntVolatile`: the kind test, the int key, one shared load.
        let mid = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7200, 2, b'I', &args[..3])
            .is_some());
        let get = c.buf.as_slice()[mid..].to_vec();
        assert!(has(&get, &kind[..kind.len() - 4]), "the kind test");
        assert!(has(&get, &cells_imm), "MOV R10, cells");
        assert!(
            !has(&get, &[0x43, 0x8D, 0x14, 0x1B, 0x83, 0xCA, 0x01]),
            "an int key"
        );
        assert_eq!(
            count(&get, &[0x4A, 0x63, 0x04, 0x18]),
            1,
            "one MOVSXD RAX, [RAX+R11]"
        );
        // `putLongVolatile`: the long key, one shared XCHG.
        let mid = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7300, 3, b'V', &args[..4])
            .is_some());
        let put = c.buf.as_slice()[mid..].to_vec();
        assert!(has(&put, &cells_imm), "MOV R10, cells");
        assert!(
            has(&put, &[0x43, 0x8D, 0x14, 0x1B, 0x83, 0xCA, 0x01]),
            "the long key"
        );
        assert_eq!(
            count(&put, &[0x4A, 0x87, 0x14, 0x18]),
            1,
            "one XCHG [RAX+R11], RDX"
        );
        // A plain `getInt` keeps its array-only prefix.
        let mid = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7400, 2, b'I', &args[..3])
            .is_some());
        let plain = c.buf.as_slice()[mid..].to_vec();
        assert!(
            !has(&plain, &cells_imm),
            "a plain accessor has no field arm"
        );
    }

    /// JIT round 20 wave 12, lane qUnsafe (AT-4): the `compareAndSetReference`
    /// thin bind takes the reference-field arm only with the admission bit,
    /// the cell table AND a published gate plan; the arm reads the reference
    /// half and ends in one `LOCK CMPXCHG [R10+R11], RDX`.
    #[test]
    fn r20_qu_ref_cas_thin_bind_needs_bit_table_and_gates() {
        use crate::direct_helpers as dh;
        if !dh::unsafe_accessor_inline_enabled()
            || !dh::unsafe_qu_ref_cas_field_enabled()
            || !sp_thin_prefix_enabled()
            || crate::x64::narrow_oops_block_inline_fields()
            || dh::unsafe_field_arm_words(&crate::DirectHelperTable {
                unsafe_field_cells: 0x10_0000,
                ..crate::DirectHelperTable::EMPTY
            })
            .is_none()
        {
            return;
        }
        let args: Vec<StackSlot> = (1..=5).map(|k| StackSlot::Frame(8 * k)).collect();
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.unsafe_cas_reference = 0x7500;
        c.direct_helpers.unsafe_inline_admitted = 0xFFFF;
        c.direct_helpers.unsafe_field_cells = 0x10_0000;
        let start = c.buf.pos();
        // No bit 18: nothing.
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7500, 4, b'Z', &args)
            .is_none());
        c.direct_helpers.unsafe_inline_admitted |= 1 << dh::UNSAFE_REF_CAS_GATE_BIT;
        // No gate plan on the test helpers: nothing.
        c.helpers.ref_store_pre_gate = 0;
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7500, 4, b'Z', &args)
            .is_none());
        assert_eq!(c.buf.pos(), start, "a refused site emits nothing");
        c.helpers.ref_store_pre_gate = 0x2000;
        c.helpers.ref_store_post_gate = 0x2001;
        c.helpers.ref_store_post_young_floor = 0;
        c.helpers.ref_store_post_skip_mask = usize::from(cratonvm_types::GC_FLAG_OLD_GEN);
        // The wrong shape: nothing.
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7500, 4, b'I', &args)
            .is_none());
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7500, 3, b'Z', &args[..4])
            .is_none());
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7500, 4, b'Z', &args)
            .is_some());
        let bytes = c.buf.as_slice()[start..].to_vec();
        let mut far = vec![0x4F, 0x8B, 0x9C, 0xDA];
        far.extend_from_slice(&dh::UNSAFE_REF_FIELD_CELL_BASE.to_le_bytes());
        assert!(has(&bytes, &far), "the reference half's cell load");
        assert!(
            has(&bytes, &[0xF0, 0x4B, 0x0F, 0xB1, 0x14, 0x1A]),
            "LOCK CMPXCHG [R10+R11], RDX"
        );
        let (gate, _) = crate::ir_lower::vh_ref_store_gate_screen_bytes(
            crate::ir_lower::vh_ref_store_gates(
                Some((0x2000, 0x2001, 0)),
                Some(cratonvm_types::GC_FLAG_OLD_GEN),
            )
            .expect("a mask plan"),
        );
        assert!(
            has(&bytes, &gate[..10]),
            "the vh_const gate screen, byte for byte"
        );
    }

    /// JIT round 23 wave 1, lane L9: a `getAndSetReference` dispatch site
    /// takes the reference-field arm only with admission bit 28, the cell
    /// table and a gate plan; the hit is the gated `XCHG [RAX+R11], RDX`
    /// followed by `MOV RAX, RDX` (the previous value is the result).
    #[test]
    fn r23_l9_ref_get_and_set_dispatch_needs_bit_table_and_gates() {
        use crate::direct_helpers as dh;
        if !dh::unsafe_accessor_inline_enabled()
            || !dh::unsafe_ref_get_and_set_field_enabled()
            || !sp_thin_prefix_enabled()
            || crate::x64::narrow_oops_block_inline_fields()
            || dh::unsafe_field_arm_words(&crate::DirectHelperTable {
                unsafe_field_cells: 0x10_0000,
                ..crate::DirectHelperTable::EMPTY
            })
            .is_none()
        {
            return;
        }
        let info = crate::JitInvokeInfo {
            class_name: "jdk/internal/misc/Unsafe",
            method_name: "getAndSetReference",
            descriptor: "(Ljava/lang/Object;JLjava/lang/Object;)Ljava/lang/Object;",
            num_jit_args: 4,
            return_type: b'L',
            invoke_kind: 0,
            declaring_class_id: 0,
            owner_class_id: 0,
        };
        let mut c = super::super::emit::tests::test_compiler();
        c.stack.clear();
        c.stack.extend((1..=4).map(|k| StackSlot::Frame(8 * k)));
        c.direct_helpers.unsafe_inline_admitted = 0xFFFF;
        c.direct_helpers.unsafe_field_cells = 0x10_0000;
        c.helpers.ref_store_pre_gate = 0x2000;
        c.helpers.ref_store_post_gate = 0x2001;
        c.helpers.ref_store_post_young_floor = 0;
        c.helpers.ref_store_post_skip_mask = usize::from(cratonvm_types::GC_FLAG_OLD_GEN);
        let start = c.buf.pos();
        // No bit 28: nothing.
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &info).is_none());
        c.direct_helpers.unsafe_inline_admitted |= 1 << dh::UNSAFE_REF_GET_AND_SET_GATE_BIT;
        // No gate plan: nothing.
        c.helpers.ref_store_pre_gate = 0;
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &info).is_none());
        assert_eq!(c.buf.pos(), start, "a refused site emits nothing");
        c.helpers.ref_store_pre_gate = 0x2000;
        // The wrong arity: nothing.
        let short = crate::JitInvokeInfo {
            num_jit_args: 3,
            ..info
        };
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &short).is_none());
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &info).is_some());
        let bytes = c.buf.as_slice()[start..].to_vec();
        let mut far = vec![0x4F, 0x8B, 0x9C, 0xDA];
        far.extend_from_slice(&dh::UNSAFE_REF_FIELD_CELL_BASE.to_le_bytes());
        assert!(has(&bytes, &far), "the reference half's cell load");
        assert!(
            has(&bytes, &[0x4A, 0x87, 0x14, 0x18, 0x48, 0x89, 0xD0]),
            "XCHG [RAX+R11], RDX ; MOV RAX, RDX"
        );
        // Off: the site keeps its call.
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_UNSAFE_REF_GET_AND_SET_FIELD", Some("0"))],
            || {
                let mut c = super::super::emit::tests::test_compiler();
                c.stack.clear();
                c.stack.extend((1..=4).map(|k| StackSlot::Frame(8 * k)));
                c.direct_helpers.unsafe_inline_admitted = usize::MAX;
                c.direct_helpers.unsafe_field_cells = 0x10_0000;
                assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &info).is_none());
            },
        );
    }

    #[test]
    fn the_prefix_contract_refuses_compiled_callees_and_register_operands() {
        let mut c = super::super::emit::tests::test_compiler();
        assert!(c.sp_thin_helper_prefix_admitted(false, 0, 0, false, true));
        // A compiled callee (it has a `JitInvokeInfo` and a service range).
        assert!(!c.sp_thin_helper_prefix_admitted(true, 0, 0, false, true));
        // A guarded or judged row, an argument hand-off, no context.
        assert!(!c.sp_thin_helper_prefix_admitted(false, 9, 0, false, true));
        assert!(!c.sp_thin_helper_prefix_admitted(false, 0, 0x10, false, true));
        assert!(!c.sp_thin_helper_prefix_admitted(false, 0, 0, true, true));
        assert!(!c.sp_thin_helper_prefix_admitted(false, 0, 0, false, false));
        // An operand the call's spill would flush to a new home.
        c.stack.push(StackSlot::Scratch(8));
        assert!(!c.sp_thin_helper_prefix_admitted(false, 0, 0, false, true));
        c.stack.clear();
        c.stack.push(StackSlot::Xmm(2));
        assert!(!c.sp_thin_helper_prefix_admitted(false, 0, 0, false, true));
        c.stack.clear();
        c.stack.push(StackSlot::CalleeSaved(12));
        assert!(c.sp_thin_helper_prefix_admitted(false, 0, 0, false, true));
    }

    /// JIT round 21, lane atomics (STATICCAS21-2): with the cell table baked
    /// the CAS prefix's non-array arm screens the static band first (the
    /// static half's address, the mirror proof, the `Long` tag), then the
    /// instance cells, and both join the ONE shared `LOCK CMPXCHG`.
    #[test]
    fn jr21_atomics_the_cas_prefix_has_a_static_arm_with_the_cell_table() {
        use crate::direct_helpers as dh;
        if !dh::unsafe_accessor_inline_enabled()
            || !dh::unsafe_rmw_inline_enabled()
            || dh::unsafe_static_arm_table(&crate::DirectHelperTable {
                unsafe_field_cells: 0x10_0000,
                ..crate::DirectHelperTable::EMPTY
            })
            .is_none()
        {
            return;
        }
        let args: Vec<StackSlot> = (1..=5).map(|k| StackSlot::Frame(8 * k)).collect();
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.unsafe_cas_long = 0x7100;
        c.direct_helpers.unsafe_inline_admitted = 0xFFFF;
        c.direct_helpers.unsafe_field_cells = 0x10_0000;
        let start = c.buf.pos();
        assert!(c
            .try_emit_sp_unsafe_access_prefix(0, 0x7100, 4, b'Z', &args)
            .is_some());
        let with = c.buf.as_slice()[start..].to_vec();
        // The band test up to its (patched) `JA` field.
        let (screen, _, ns) = dh::unsafe_inline_static_cell_bytes(0x10_0000, 8);
        let head = &screen[..ns];
        let at = with
            .windows(head.len())
            .position(|w| w == head)
            .expect("the static band test");
        let mut half = vec![0x49, 0xBA];
        // Cast: an address.
        half.extend_from_slice(&((0x10_0000 + dh::UNSAFE_STATIC_CELL_BASE) as u64).to_le_bytes());
        assert!(
            with.windows(half.len()).any(|w| w == &half[..]),
            "MOV R10, the static half"
        );
        let cells_imm = [0x49, 0xBA, 0x00, 0x00, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00];
        if dh::unsafe_field_arm_words(&c.direct_helpers).is_some() {
            let inst = with
                .windows(cells_imm.len())
                .position(|w| w == &cells_imm[..])
                .expect("the instance screen");
            assert!(at < inst, "the static band is screened first");
        }
        let cmpxchg = [0xF0, 0x4B, 0x0F, 0xB1, 0x14, 0x1A];
        assert_eq!(
            with.windows(cmpxchg.len())
                .filter(|w| *w == &cmpxchg[..])
                .count(),
            1
        );
    }

    /// t1 wave 9, lane ATOM2 (ATOMICS21-1,
    /// `CRATONVM_JIT_UNSAFE_STATIC_VOLATILE_INLINE`, default ON since j27
    /// 2026-10-28): with the switch on and the cell table baked,
    /// `getIntVolatile` / `putLongVolatile` screen the static band (the static
    /// half's address, the `Int` / `Long` key) before the instance cells and
    /// still emit ONE shared `MOVSXD` / `XCHG`; at `=0`, no static screen is
    /// emitted.
    #[test]
    fn t1w9_atom2_volatile_accessors_have_a_static_arm_only_when_opted_in() {
        use crate::direct_helpers as dh;
        let table = crate::DirectHelperTable {
            unsafe_field_cells: 0x10_0000,
            ..crate::DirectHelperTable::EMPTY
        };
        if !dh::unsafe_accessor_inline_enabled()
            || !dh::unsafe_volatile_inline_enabled()
            || dh::unsafe_static_arm_table(&table).is_none()
        {
            return;
        }
        let args: Vec<StackSlot> = (1..=4).map(|k| StackSlot::Frame(8 * k)).collect();
        let mut half = vec![0x49, 0xBA];
        // Cast: an address.
        half.extend_from_slice(&((0x10_0000 + dh::UNSAFE_STATIC_CELL_BASE) as u64).to_le_bytes());
        let count =
            |hay: &[u8], needle: &[u8]| hay.windows(needle.len()).filter(|w| *w == needle).count();
        let emit = |opt_in: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_UNSAFE_STATIC_VOLATILE_INLINE", opt_in)],
                || {
                    let mut c = super::super::emit::tests::test_compiler();
                    c.direct_helpers.unsafe_get_int_volatile = 0x7200;
                    c.direct_helpers.unsafe_put_long_volatile = 0x7300;
                    c.direct_helpers.unsafe_inline_admitted = 0xFFFF;
                    c.direct_helpers.unsafe_field_cells = 0x10_0000;
                    let start = c.buf.pos();
                    assert!(c
                        .try_emit_sp_unsafe_access_prefix(0, 0x7200, 2, b'I', &args[..3])
                        .is_some());
                    let get = c.buf.as_slice()[start..].to_vec();
                    let mid = c.buf.pos();
                    assert!(c
                        .try_emit_sp_unsafe_access_prefix(0, 0x7300, 3, b'V', &args[..4])
                        .is_some());
                    let put = c.buf.as_slice()[mid..].to_vec();
                    (get, put)
                },
            )
        };
        // Default ON since j27 2026-10-28: `=0` is the arm without a screen,
        // and unset screens like `=1`.
        let (get, put) = emit(Some("0"));
        assert_eq!(count(&get, &half), 0, "=0: no static screen in the get");
        assert_eq!(count(&put, &half), 0, "=0: no static screen in the put");
        let (get, put) = emit(None);
        assert_eq!(count(&get, &half), 1, "unset: the static screen (get)");
        assert_eq!(count(&put, &half), 1, "unset: the static screen (put)");
        let (get, put) = emit(Some("1"));
        assert_eq!(count(&get, &half), 1, "MOV R10, the static half (get)");
        assert_eq!(count(&put, &half), 1, "MOV R10, the static half (put)");
        let (get_screen, _, _) = dh::unsafe_inline_static_cell_bytes(0x10_0000, 4);
        let (put_screen, _, _) = dh::unsafe_inline_static_cell_bytes(0x10_0000, 8);
        // The tag compares (`CMP DWORD [RAX + R11], tag`) pick Int / Long.
        let tag_cmp = |screen: &[u8]| screen[screen.len() - 15..screen.len() - 10].to_vec();
        assert_eq!(count(&get, &tag_cmp(&get_screen)), 1, "the Int tag guard");
        assert_eq!(count(&put, &tag_cmp(&put_screen)), 1, "the Long tag guard");
        assert_eq!(count(&get, &[0x4A, 0x63, 0x04, 0x18]), 1, "one MOVSXD RAX, [RAX+R11]");
        assert_eq!(count(&put, &[0x4A, 0x87, 0x14, 0x18]), 1, "one XCHG [RAX+R11], RDX");
    }
}

#[cfg(test)]
mod nio20_w4_sp_unsafe_dispatch_prefix_tests {
    //! nio20 wave 4, lane L3: the dispatch-arm `Unsafe` prefix
    //! (`getChar` / `putChar`, the little-endian `*Unaligned` forms).

    use super::*;

    fn info(name: &'static str, desc: &'static str, args: usize, ret: u8) -> crate::JitInvokeInfo {
        crate::JitInvokeInfo {
            class_name: "jdk/internal/misc/Unsafe",
            method_name: name,
            descriptor: desc,
            num_jit_args: args,
            return_type: ret,
            invoke_kind: 0,
            declaring_class_id: 0,
            owner_class_id: 0,
        }
    }

    #[test]
    fn the_dispatch_prefix_serves_only_the_admitted_frame_operand_shapes() {
        let get_char = info("getChar", "(Ljava/lang/Object;J)C", 3, b'C');
        let mut c = super::super::emit::tests::test_compiler();
        c.stack.clear();
        c.stack.extend([
            StackSlot::Frame(8),
            StackSlot::Frame(16),
            StackSlot::Frame(24),
        ]);
        let start = c.buf.pos();
        // No admission word: nothing.
        c.direct_helpers.unsafe_inline_admitted = 0;
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &get_char).is_none());
        // The getChar bit only (bit 2): admitted, unless a switch is off.
        c.direct_helpers.unsafe_inline_admitted = 1 << 2;
        let on =
            sp_thin_prefix_enabled() && crate::direct_helpers::unsafe_accessor_inline_enabled();
        // An argument-count mismatch, an XMM operand: nothing.
        let wrong = info("getChar", "(Ljava/lang/Object;J)C", 2, b'C');
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &wrong).is_none());
        c.stack[2] = StackSlot::Xmm(1);
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &get_char).is_none());
        // An interface or static row, a big-endian unaligned form, a class
        // other than `Unsafe`: nothing.
        c.stack[2] = StackSlot::Frame(24);
        let mut static_row = info("getChar", "(Ljava/lang/Object;J)C", 3, b'C');
        static_row.invoke_kind = 3;
        assert!(c
            .try_emit_sp_unsafe_dispatch_prefix(4, &static_row)
            .is_none());
        c.direct_helpers.unsafe_inline_admitted = 0b11111;
        c.stack.push(StackSlot::Frame(32));
        let be = info("getIntUnaligned", "(Ljava/lang/Object;JZ)I", 4, b'I');
        // JIT round 20 (lane memory): served only under its opt-in switch.
        assert!(cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_SP_UNSAFE_BIG_ENDIAN_PREFIX", Some("0"))],
            || c.try_emit_sp_unsafe_dispatch_prefix(4, &be).is_none()
        ));
        c.stack.pop();
        let mut other = info("getChar", "(Ljava/lang/Object;J)C", 3, b'C');
        other.class_name = "sun/misc/Unsafe";
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &other).is_none());
        assert_eq!(c.buf.pos(), start);
        // The admitted shape.
        let hit = c.try_emit_sp_unsafe_dispatch_prefix(4, &get_char);
        assert_eq!(hit.is_some(), on);
        // A put needs its own bit (bit 7 for putChar).
        let put_char = info("putChar", "(Ljava/lang/Object;JC)V", 4, b'V');
        let mut c = super::super::emit::tests::test_compiler();
        c.stack.clear();
        c.stack.extend([
            StackSlot::Frame(8),
            StackSlot::Frame(16),
            StackSlot::Frame(24),
            StackSlot::Frame(32),
        ]);
        c.direct_helpers.unsafe_inline_admitted = 1 << 2;
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &put_char).is_none());
        c.direct_helpers.unsafe_inline_admitted = 1 << 7;
        assert_eq!(
            c.try_emit_sp_unsafe_dispatch_prefix(4, &put_char).is_some(),
            on
        );
    }

    /// JIT round 20 (lane memory): the big-endian four-operand forms take the
    /// shared raw access with a run-time swap in both arms.
    #[test]
    fn the_big_endian_unaligned_forms_swap_at_run_time() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_SP_UNSAFE_BIG_ENDIAN_PREFIX", Some("1"))],
            the_big_endian_unaligned_forms_swap_at_run_time_on,
        );
    }

    fn the_big_endian_unaligned_forms_swap_at_run_time_on() {
        fn has(hay: &[u8], needle: &[u8]) -> bool {
            hay.windows(needle.len()).any(|w| w == needle)
        }
        let on = sp_thin_prefix_enabled()
            && crate::direct_helpers::unsafe_accessor_inline_enabled()
            && sp_unsafe_big_endian_prefix_enabled();
        if !on {
            return;
        }
        // getIntUnaligned(Object, long, boolean): [recv, base, offset, order].
        let get = info("getIntUnaligned", "(Ljava/lang/Object;JZ)I", 4, b'I');
        let mut c = super::super::emit::tests::test_compiler();
        c.stack.clear();
        c.stack.extend((1..=4).map(|k| StackSlot::Frame(8 * k)));
        c.direct_helpers.unsafe_inline_admitted = 0b11111;
        let start = c.buf.pos();
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &get).is_some());
        let bytes = c.buf.as_slice()[start..].to_vec();
        assert!(has(&bytes, &[0x4A, 0x8D, 0x14, 0x18]), "LEA RDX, [RAX+R11]");
        assert!(has(&bytes, &[0x8B, 0x02]), "MOV EAX, [RDX]");
        assert!(
            has(&bytes, &[0x85, 0xC9]),
            "TEST ECX, ECX (the order operand)"
        );
        assert!(has(&bytes, &[0x0F, 0xC8]), "BSWAP EAX");
        assert!(
            has(&bytes, &[0x48, 0x63, 0xC0]),
            "MOVSXD RAX, EAX after the swap"
        );
        // putLongUnaligned(Object, long, long, boolean): the value is swapped
        // before the store.
        let put = info("putLongUnaligned", "(Ljava/lang/Object;JJZ)V", 5, b'V');
        let mut c = super::super::emit::tests::test_compiler();
        c.stack.clear();
        c.stack.extend((1..=5).map(|k| StackSlot::Frame(8 * k)));
        c.direct_helpers.unsafe_inline_admitted = 0b11111 << 5;
        let start = c.buf.pos();
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &put).is_some());
        let bytes = c.buf.as_slice()[start..].to_vec();
        assert!(has(&bytes, &[0x48, 0x0F, 0xC8]), "BSWAP RAX");
        assert!(has(&bytes, &[0x48, 0x89, 0x02]), "MOV [RDX], RAX");
    }

    /// JIT round 21, lane atomics (UNSAFE21-2): `compareAndExchangeByte` at
    /// the dispatch arm takes the sub-word arm only with its admission bit and
    /// the cell table, and ends in one `LOCK CMPXCHG` byte and the `MOVSX`.
    #[test]
    fn jr21_atomics_subword_cae_dispatch_prefix_needs_its_bit_and_the_table() {
        use crate::direct_helpers as dh;
        if !sp_thin_prefix_enabled()
            || !dh::unsafe_accessor_inline_enabled()
            || !dh::unsafe_subword_rmw_inline_enabled()
            || dh::unsafe_field_arm_words(&crate::DirectHelperTable {
                unsafe_field_cells: 0x10_0000,
                ..crate::DirectHelperTable::EMPTY
            })
            .is_none()
        {
            return;
        }
        let cae = info(
            "compareAndExchangeByte",
            "(Ljava/lang/Object;JBB)B",
            5,
            b'B',
        );
        let mut c = super::super::emit::tests::test_compiler();
        c.stack.clear();
        c.stack.extend((1..=5).map(|k| StackSlot::Frame(8 * k)));
        // Some other row admitted (a zero word refuses every row first).
        c.direct_helpers.unsafe_inline_admitted = 1;
        c.direct_helpers.unsafe_field_cells = 0x10_0000;
        let start = c.buf.pos();
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &cae).is_none());
        assert_eq!(c.buf.pos(), start, "no admission bit, nothing emitted");
        c.direct_helpers.unsafe_inline_admitted |= 1 << dh::UnsafeSubwordRmw::FIRST_BIT;
        assert!(c.try_emit_sp_unsafe_dispatch_prefix(4, &cae).is_some());
        let out = c.buf.as_slice()[start..].to_vec();
        let cmpxchg_b = [0xF0, 0x43, 0x0F, 0xB0, 0x14, 0x1A, 0x48, 0x0F, 0xBE, 0xC0];
        assert!(out.windows(cmpxchg_b.len()).any(|w| w == &cmpxchg_b[..]));
    }
}

#[cfg(test)]
mod nio21_w3_sp_scoped_access_prefix_tests {
    //! nio21 wave 3, lane L3 (W2L3-3): the single-pass `ScopedMemoryAccess`
    //! prefix and the `Unsafe` prefix's off-heap arm.

    use super::*;

    fn has(hay: &[u8], needle: &[u8]) -> bool {
        hay.windows(needle.len()).any(|w| w == needle)
    }

    #[test]
    fn the_sixteen_scoped_cells_map_to_their_shapes_and_rows() {
        let mut dh = crate::DirectHelperTable::EMPTY;
        dh.scoped_memory_get_int_internal = 0x100;
        dh.scoped_memory_put_long = 0x108;
        dh.scoped_memory_get_char = 0x110;
        dh.scoped_memory_get_short_internal = 0x118;
        let get_int = sp_scoped_access_of(&dh, 0x100).unwrap();
        assert_eq!(
            (get_int.width, get_int.is_put, get_int.ret_type()),
            (4, false, b'I')
        );
        assert_eq!(get_int.num_params(), 4);
        assert_eq!(get_int.unsafe_gate_bit(), 1 << 3);
        let put_long = sp_scoped_access_of(&dh, 0x108).unwrap();
        assert_eq!(
            (put_long.width, put_long.is_put, put_long.ret_type()),
            (8, true, b'V')
        );
        assert_eq!(put_long.num_params(), 5);
        assert_eq!(put_long.unsafe_gate_bit(), 1 << 9);
        assert_eq!(sp_scoped_access_of(&dh, 0x110).unwrap().ret_type(), b'C');
        assert_eq!(sp_scoped_access_of(&dh, 0x118).unwrap().ret_type(), b'S');
        // An unwired cell and an unknown entry.
        assert_eq!(sp_scoped_access_of(&dh, 0), None);
        assert_eq!(sp_scoped_access_of(&dh, 0x120), None);
        // The row: the instance arm with the declared shape only.
        let row = |e, recv, p, r| sp_thin_prefix_row(&dh, e, recv, p, r);
        assert_eq!(row(0x100, true, 4, b'I'), Some(SpThinPrefix::ScopedAccess));
        assert_eq!(row(0x108, true, 5, b'V'), Some(SpThinPrefix::ScopedAccess));
        assert_eq!(row(0x100, false, 4, b'I'), None);
        assert_eq!(row(0x100, true, 5, b'I'), None);
        assert_eq!(row(0x100, true, 4, b'J'), None);
    }

    #[test]
    fn the_scoped_prefix_needs_its_admission_bit_and_frame_operands() {
        let mut c = super::super::emit::tests::test_compiler();
        c.direct_helpers.scoped_memory_get_int_internal = 0x2000; // baked, never executed
        c.direct_helpers.scoped_memory_put_int = 0x3000;
        let get_args: Vec<StackSlot> = (1..=5).map(|k| StackSlot::Frame(8 * k)).collect();
        let start = c.buf.pos();
        // No admission word: nothing.
        c.direct_helpers.unsafe_inline_admitted = 0;
        assert!(c
            .try_emit_sp_scoped_access_prefix(0, 0x2000, &get_args)
            .is_none());
        // Every bit but `getInt`'s: nothing.
        c.direct_helpers.unsafe_inline_admitted = 0x3FF & !(1 << 3);
        assert!(c
            .try_emit_sp_scoped_access_prefix(0, 0x2000, &get_args)
            .is_none());
        c.direct_helpers.unsafe_inline_admitted = 0x3FF;
        // An unknown helper, the wrong operand count, an XMM operand.
        assert!(c
            .try_emit_sp_scoped_access_prefix(0, 0x4000, &get_args)
            .is_none());
        assert!(c
            .try_emit_sp_scoped_access_prefix(0, 0x2000, &get_args[..4])
            .is_none());
        let mut xmm = get_args.clone();
        xmm[3] = StackSlot::Xmm(1);
        assert!(c
            .try_emit_sp_scoped_access_prefix(0, 0x2000, &xmm)
            .is_none());
        assert_eq!(c.buf.pos(), start);
        let on = sp_thin_prefix_enabled() && sp_scoped_access_prefix_enabled();
        let hit = c.try_emit_sp_scoped_access_prefix(0, 0x2000, &get_args);
        assert_eq!(hit.is_some(), on);
        if !on {
            return;
        }
        let get = c.buf.as_slice()[start..].to_vec();
        // The heap arm's address, the int read, its run-time swap and widening.
        assert!(has(&get, &[0x4A, 0x8D, 0x14, 0x18]), "LEA RDX, [RAX+R11]");
        assert!(has(&get, &[0x8B, 0x02]), "MOV EAX, [RDX]");
        assert!(has(&get, &[0x0F, 0xC8]), "BSWAP EAX");
        assert!(has(&get, &[0x48, 0x63, 0xC0]), "MOVSXD RAX, EAX");
        // `test_compiler` has no arena table: a handle declines (JNZ after
        // TEST R11, RAX), a real pointer is used as is.
        assert!(has(&get, &[0x49, 0x85, 0xC3, 0x0F, 0x85]));
        assert!(has(&get, &[0x4C, 0x89, 0xDA]), "MOV RDX, R11");
        // A put: the value is stored at RDX.
        let mid = c.buf.pos();
        let put_args: Vec<StackSlot> = (1..=6).map(|k| StackSlot::Frame(8 * k)).collect();
        assert!(c
            .try_emit_sp_scoped_access_prefix(0, 0x3000, &put_args)
            .is_some());
        let put = c.buf.as_slice()[mid..].to_vec();
        assert!(has(&put, &[0x89, 0x02]), "MOV [RDX], EAX");
    }

    #[test]
    fn the_unsafe_prefix_takes_a_null_base_off_heap_only_under_its_switch() {
        if !crate::direct_helpers::unsafe_accessor_inline_enabled() {
            return;
        }
        let args = [
            StackSlot::Frame(8),
            StackSlot::Frame(16),
            StackSlot::Frame(24),
        ];
        let emit = |offheap: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_SP_UNSAFE_OFFHEAP_PREFIX", offheap)],
                || {
                    let mut c = super::super::emit::tests::test_compiler();
                    c.direct_helpers.unsafe_get_int = 0x2000;
                    c.direct_helpers.unsafe_inline_admitted = 0x3FF;
                    let start = c.buf.pos();
                    let hit = c.try_emit_sp_unsafe_access_prefix(0, 0x2000, 2, b'I', &args);
                    assert!(hit.is_some());
                    c.buf.as_slice()[start..].to_vec()
                },
            )
        };
        let off = emit(Some("0"));
        let on = emit(None);
        // Off: the nio20 bytes, no off-heap arm.
        assert!(!has(&off, &[0x4D, 0x85, 0xDB]), "TEST R11, R11");
        // On: the same heap arm, then the off-heap arm (TEST R11,R11 ; JLE)
        // and its `int` read at RDX.
        assert!(has(&on, &[0x4A, 0x63, 0x04, 0x18]));
        assert!(has(&on, &[0x4D, 0x85, 0xDB, 0x0F, 0x8E]));
        assert!(has(&on, &[0x8B, 0x02, 0x48, 0x63, 0xC0]));
        assert!(on.len() > off.len());
    }
}

#[cfg(test)]
mod nio21_w1_sp_identity_hash_prefix_tests {
    //! nio21 wave 1, lane L5: the dispatch-arm identity-hash prefix.

    use super::*;

    fn info(
        class: &'static str,
        name: &'static str,
        desc: &'static str,
        kind: u8,
    ) -> crate::JitInvokeInfo {
        crate::JitInvokeInfo {
            class_name: class,
            method_name: name,
            descriptor: desc,
            num_jit_args: 1,
            return_type: b'I',
            invoke_kind: kind,
            declaring_class_id: 0,
            owner_class_id: 0,
        }
    }

    /// `System.identityHashCode` (static) emits the optimizing tier's header
    /// read byte for byte; a `Class.hashCode()` site with no `Class` id, a
    /// non-static `identityHashCode` row, another method and an XMM operand
    /// emit nothing.
    #[test]
    fn only_the_identity_hash_sites_take_the_header_read() {
        let on = sp_thin_prefix_enabled()
            && sp_identity_hash_inline_enabled()
            && crate::ir_lower::ir_identity_hash_inline_enabled()
            && !crate::x64::zgc_read_barrier_blocks_inline_fields();
        let ihc = info(
            "java/lang/System",
            "identityHashCode",
            "(Ljava/lang/Object;)I",
            3,
        );
        let mut c = super::super::emit::tests::test_compiler();
        c.stack.clear();
        c.stack.push(StackSlot::Frame(8));
        let start = c.buf.pos();
        // No `Class` id in the test table: the Class arm emits nothing.
        let class_hash = info("java/lang/Class", "hashCode", "()I", 0);
        assert!(c
            .try_emit_sp_identity_hash_dispatch_prefix(4, &class_hash)
            .is_none());
        let virtual_ihc = info(
            "java/lang/System",
            "identityHashCode",
            "(Ljava/lang/Object;)I",
            0,
        );
        assert!(c
            .try_emit_sp_identity_hash_dispatch_prefix(4, &virtual_ihc)
            .is_none());
        let other = info("java/lang/Object", "hashCode", "()I", 0);
        assert!(c
            .try_emit_sp_identity_hash_dispatch_prefix(4, &other)
            .is_none());
        c.stack[0] = StackSlot::Xmm(1);
        assert!(c
            .try_emit_sp_identity_hash_dispatch_prefix(4, &ihc)
            .is_none());
        assert_eq!(c.buf.pos(), start);
        c.stack[0] = StackSlot::Frame(8);
        let hit = c.try_emit_sp_identity_hash_dispatch_prefix(4, &ihc);
        assert_eq!(hit.is_some(), on);
        if on {
            let (read, _) = crate::ir_lower::identity_hash_read_bytes();
            let emitted = c.buf.as_slice()[start..].to_vec();
            // The read's first instructions (MOV EDX,[RAX+MARK]; MOV ECX,EDX;
            // AND ECX,STATE) appear verbatim.
            assert!(emitted.windows(8).any(|w| w == &read[..8]));
        }
    }
}

#[cfg(test)]
mod nio21_w8_sp_box_hash_class_arm_tests {
    //! nio21 wave 8, lane L5: the `Class` arm of the single-pass box-hash
    //! prefix (`docs/feature-designs/jit-ir-optimizations.md`).

    use super::*;

    const FAKE_CLASS_ID: u32 = 0x77;

    /// A well-known-id resolver that knows `java/lang/Class` only, so the
    /// `Integer` and `String` halves stay out of the picture.
    extern "C" fn fake_well_known(_ctx: i64, which: i64) -> i64 {
        if which == crate::ir_lower::WELL_KNOWN_CLASS_CLASS {
            i64::from(FAKE_CLASS_ID)
        } else {
            0
        }
    }

    fn object_hash() -> crate::JitInvokeInfo {
        crate::JitInvokeInfo {
            class_name: "java/lang/Object",
            method_name: "hashCode",
            descriptor: "()I",
            num_jit_args: 1,
            return_type: b'I',
            invoke_kind: 0,
            declaring_class_id: 0,
            owner_class_id: 0,
        }
    }

    fn emit(class_arm: Option<&str>, info: &crate::JitInvokeInfo) -> (Vec<usize>, Vec<u8>, i32) {
        emit_with(class_arm, Some("0"), info)
    }

    /// JIT round 21, lane hash: `identity_arm` is
    /// `CRATONVM_JIT_OBJECT_HASH_IDENTITY_ARM`'s override (the `Class` arm's
    /// own test keeps it off, so its `=0` arm emits nothing).
    fn emit_with(
        class_arm: Option<&str>,
        identity_arm: Option<&str>,
        info: &crate::JitInvokeInfo,
    ) -> (Vec<usize>, Vec<u8>, i32) {
        cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_SP_BOX_HASH_CLASS_ARM", class_arm),
                ("CRATONVM_JIT_OBJECT_HASH_IDENTITY_ARM", identity_arm),
            ],
            || {
                let mut c = super::super::emit::tests::test_compiler();
                c.direct_helpers.well_known_class_id = fake_well_known as *const () as usize;
                c.direct_helpers.static_base_resolver_ctx = 1;
                c.string_layout = None;
                c.stack.clear();
                c.stack.push(StackSlot::Frame(8));
                let start = c.buf.pos();
                let hits = c.try_emit_box_hash_equals_prefix(4, info);
                let cid_off = c.helpers.class_id_offset_in_obj as i32; // Cast: disp32
                (hits, c.buf.as_slice()[start..].to_vec(), cid_off)
            },
        )
    }

    /// An `Object.hashCode()` site gets `CMP DWORD [RAX+cid], Class` and the
    /// optimizing tier's header read; `=0` and a non-`Object` site get
    /// nothing from the arm.
    #[test]
    fn the_object_hash_site_takes_the_class_arm_under_its_switch() {
        let on = sp_identity_hash_inline_enabled()
            && crate::ir_lower::ir_identity_hash_inline_enabled()
            && !crate::x64::zgc_read_barrier_blocks_inline_fields();
        let (hits, bytes, cid_off) = emit(None, &object_hash());
        let mut cmp = vec![0x81, 0xB8];
        cmp.extend_from_slice(&cid_off.to_le_bytes());
        cmp.extend_from_slice(&FAKE_CLASS_ID.to_le_bytes());
        let has_cmp = bytes.windows(cmp.len()).any(|w| w == cmp.as_slice());
        assert_eq!(has_cmp, on);
        assert_eq!(!hits.is_empty(), on);
        if on {
            let (read, _) = crate::ir_lower::identity_hash_read_bytes();
            assert!(bytes.windows(8).any(|w| w == &read[..8]));
        }
        let (hits_off, bytes_off, _) = emit(Some("0"), &object_hash());
        assert!(!bytes_off.windows(cmp.len()).any(|w| w == cmp.as_slice()));
        assert!(hits_off.is_empty());
        // `Number.hashCode()` is an Integer-only site: no Class arm.
        let mut number = object_hash();
        number.class_name = "java/lang/Number";
        let (hits_n, bytes_n, _) = emit(None, &number);
        assert!(hits_n.is_empty() && bytes_n.is_empty());
    }

    /// The profiled class the fake resolver below vouches for.
    const FAKE_PROFILED_ID: u32 = 0x1234;

    /// `fake_well_known` plus the identity-hash query (JIT round 21, lane
    /// hash): `1` for [`FAKE_PROFILED_ID`] only.
    extern "C" fn fake_well_known_identity(ctx: i64, which: i64) -> i64 {
        if which
            == crate::ir_lower::vh_const_query(
                crate::ir_lower::WELL_KNOWN_VH_CONST_IDENTITY_HASH_TAG,
                FAKE_PROFILED_ID,
                0,
            )
        {
            return 1;
        }
        fake_well_known(ctx, which)
    }

    /// JIT round 21, lane hash (NATIVE21-1): an `Object.hashCode()` site gets
    /// the exact-`java/lang/Object` compare (`CMP DWORD [RAX+cid], 0`), and
    /// the inline cache's seeded class when the VM vouches for it; both select
    /// the header read. `CRATONVM_JIT_OBJECT_HASH_IDENTITY_ARM=0` emits
    /// neither, and a seed the VM does not vouch for is not compared.
    #[test]
    fn r21_hash_the_object_hash_site_takes_the_identity_arm() {
        let on = sp_identity_hash_inline_enabled()
            && crate::ir_lower::ir_identity_hash_inline_enabled()
            && !crate::x64::zgc_read_barrier_blocks_inline_fields();
        let run = |identity: Option<&str>, seed: u32| {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    ("CRATONVM_JIT_SP_BOX_HASH_CLASS_ARM", Some("0")),
                    ("CRATONVM_JIT_OBJECT_HASH_IDENTITY_ARM", identity),
                ],
                || {
                    let mut c = super::super::emit::tests::test_compiler();
                    c.direct_helpers.well_known_class_id =
                        fake_well_known_identity as *const () as usize;
                    c.direct_helpers.static_base_resolver_ctx = 1;
                    c.string_layout = None;
                    c.stack.clear();
                    c.stack.push(StackSlot::Frame(8));
                    let mic = Box::new(crate::JitMICSlot::new());
                    mic.prepopulate(seed);
                    c.mic_slots.push((4, &*mic as *const crate::JitMICSlot));
                    c.mic_slots_idx.insert(4, c.mic_slots.len() - 1);
                    let start = c.buf.pos();
                    let hits = c.try_emit_box_hash_equals_prefix(4, &object_hash());
                    let cid_off = c.helpers.class_id_offset_in_obj as i32; // Cast: disp32
                    let bytes = c.buf.as_slice()[start..].to_vec();
                    drop(c);
                    drop(mic);
                    (hits, bytes, cid_off)
                },
            )
        };
        let cmp = |cid_off: i32, id: u32| {
            let mut v = vec![0x81, 0xB8];
            v.extend_from_slice(&cid_off.to_le_bytes());
            v.extend_from_slice(&id.to_le_bytes());
            v
        };
        fn has(bytes: &[u8], pat: &[u8]) -> bool {
            bytes.windows(pat.len()).any(|w| w == pat)
        }

        let (hits, bytes, cid_off) = run(None, FAKE_PROFILED_ID);
        assert_eq!(has(&bytes, &cmp(cid_off, 0)), on);
        assert_eq!(has(&bytes, &cmp(cid_off, FAKE_PROFILED_ID)), on);
        assert_eq!(!hits.is_empty(), on);
        if on {
            let (read, _) = crate::ir_lower::identity_hash_read_bytes();
            assert!(bytes.windows(8).any(|w| w == &read[..8]));
        }
        // A seed the VM does not vouch for: only the exact-Object compare.
        let (_, bytes_u, cid_off) = run(None, 0x4321);
        assert_eq!(has(&bytes_u, &cmp(cid_off, 0)), on);
        assert!(!has(&bytes_u, &cmp(cid_off, 0x4321)));
        // The switch off: nothing at all (no other arm is armed here).
        let (hits_off, bytes_off, _) = run(Some("0"), FAKE_PROFILED_ID);
        assert!(hits_off.is_empty() && bytes_off.is_empty());
    }
}

#[cfg(test)]
mod nio20_w4_sp_current_thread_prefix_tests {
    //! nio20 wave 4, lane L3: the `Thread.currentThread()` row and emitter.

    use super::*;

    /// nio21 wave 3, lane L4: `currentCarrierThread`'s own helper cell takes
    /// the same prefix, at the same static no-argument reference shape.
    #[test]
    fn nio21_the_carrier_thread_row_takes_the_current_thread_prefix() {
        let mut dh = crate::DirectHelperTable::EMPTY;
        dh.thread_current_carrier_thread = 0x98;
        assert_eq!(
            sp_thin_prefix_row(&dh, 0x98, false, 0, b'L'),
            Some(SpThinPrefix::ThreadCurrentThread)
        );
        assert_eq!(sp_thin_prefix_row(&dh, 0x98, true, 0, b'L'), None);
        assert_eq!(sp_thin_prefix_row(&dh, 0x98, false, 1, b'L'), None);
        // An unwired cell never matches.
        assert_eq!(
            sp_thin_prefix_row(&crate::DirectHelperTable::EMPTY, 0x98, false, 0, b'L'),
            None
        );
    }

    #[test]
    fn the_current_thread_row_is_the_static_no_arg_reference_shape() {
        let mut dh = crate::DirectHelperTable::EMPTY;
        dh.thread_current_thread = 0x90;
        assert_eq!(
            sp_thin_prefix_row(&dh, 0x90, false, 0, b'L'),
            Some(SpThinPrefix::ThreadCurrentThread)
        );
        assert_eq!(sp_thin_prefix_row(&dh, 0x90, true, 0, b'L'), None);
        assert_eq!(sp_thin_prefix_row(&dh, 0x90, false, 1, b'L'), None);
        assert_eq!(sp_thin_prefix_row(&dh, 0x90, false, 0, b'I'), None);
        assert_eq!(
            SpThinPrefix::ThreadCurrentThread.enabled(),
            sp_thin_prefix_enabled()
        );
    }

    /// No published offset (the `EMPTY` table, every `--jdk-only` VM) or an
    /// argument: nothing is emitted and the call stands alone.
    #[test]
    fn the_prefix_emits_nothing_without_the_vm_word() {
        let mut c = super::super::emit::tests::test_compiler();
        let start = c.buf.pos();
        c.direct_helpers.thread_java_obj_offset = 0;
        assert!(c.try_emit_sp_current_thread_prefix(3, &[]).is_none());
        c.direct_helpers.thread_java_obj_offset = 0x40;
        assert!(c
            .try_emit_sp_current_thread_prefix(3, &[StackSlot::Frame(16)])
            .is_none());
        assert_eq!(c.buf.pos(), start);
        // With the word, the prefix is emitted only where the TLS mirror
        // displacement exists (else the thread fetch would be a CALL).
        let hit = c.try_emit_sp_current_thread_prefix(3, &[]);
        assert_eq!(hit.is_some(), jit_thread_tls_disp() != 0);
        assert_eq!(hit.is_none(), c.buf.pos() == start);
    }
}

#[cfg(test)]
mod nio20_w3_sp_thin_prefix_table_tests {
    //! nio20 wave 3, lane L3 (W2L2-1/2/4): the one prefix table both plain
    //! direct arms consult, the unbox rows, and the single-pass kill switch.

    use super::*;

    #[test]
    fn each_bound_helper_matches_its_own_row_arm_and_shape() {
        let mut dh = crate::DirectHelperTable::EMPTY;
        dh.integer_value_of = 0x10;
        dh.long_value_of = 0x20;
        dh.object_get_class = 0x30;
        dh.integer_int_value = 0x40;
        dh.long_long_value = 0x50;
        dh.unsafe_get_int = 0x60;
        dh.unsafe_put_long = 0x68;
        let row =
            |entry, receiver, params, ret| sp_thin_prefix_row(&dh, entry, receiver, params, ret);
        use super::SpThinPrefix as P;
        assert_eq!(row(0x10, false, 1, b'L'), Some(P::IntegerValueOfBox));
        assert_eq!(row(0x20, false, 1, b'L'), Some(P::LongValueOfBox));
        assert_eq!(row(0x30, true, 0, b'L'), Some(P::ObjectGetClass));
        assert_eq!(row(0x40, true, 0, b'I'), Some(P::IntegerIntValue));
        assert_eq!(row(0x50, true, 0, b'J'), Some(P::LongLongValue));
        // The `Unsafe` rows leave the shape to their emitter.
        assert_eq!(row(0x60, true, 2, b'I'), Some(SpThinPrefix::UnsafeAccess));
        assert_eq!(row(0x68, true, 3, b'V'), Some(SpThinPrefix::UnsafeAccess));
        // The wrong arm, the wrong shape, an unknown entry, an unwired cell.
        assert_eq!(row(0x10, true, 1, b'L'), None);
        assert_eq!(row(0x30, false, 0, b'L'), None);
        assert_eq!(row(0x30, true, 1, b'L'), None);
        assert_eq!(row(0x40, true, 0, b'J'), None);
        assert_eq!(row(0x70, true, 0, b'I'), None);
        assert_eq!(row(0, true, 2, b'I'), None);
    }

    #[test]
    fn the_single_pass_switch_covers_the_new_rows_and_not_the_box_rows() {
        let on = sp_thin_prefix_enabled();
        assert!(SpThinPrefix::IntegerValueOfBox.enabled());
        assert!(SpThinPrefix::LongValueOfBox.enabled());
        for p in [
            SpThinPrefix::ObjectGetClass,
            SpThinPrefix::UnsafeAccess,
            SpThinPrefix::IntegerIntValue,
            SpThinPrefix::LongLongValue,
        ] {
            assert_eq!(p.enabled(), on);
        }
    }

    #[test]
    fn the_unbox_prefix_emits_nothing_without_a_class_id_or_for_an_xmm_receiver() {
        let mut c = super::super::emit::tests::test_compiler();
        let start = c.buf.pos();
        // `test_compiler` has no well-known-class resolver: no class id.
        let frame = [StackSlot::Frame(16)];
        let xmm = [StackSlot::Xmm(1)];
        assert!(c.try_emit_sp_unbox_prefix(5, false, &frame).is_none());
        assert!(c.try_emit_sp_unbox_prefix(5, true, &frame).is_none());
        assert!(c.try_emit_sp_unbox_prefix(5, false, &xmm).is_none());
        // Not exactly one argument (the receiver).
        assert!(c.try_emit_sp_unbox_prefix(5, false, &[]).is_none());
        assert_eq!(c.buf.pos(), start);
    }
}

/// JIT round 19 proposal wave 8, lane tail8: TAIL7-19-1 (the lazy return-tail
/// republish over a VM-free window) and TAIL7-19-3 (the instance-arm leaf
/// twins and the wide decline compare).
#[cfg(test)]
mod tail8_tests {
    use super::*;

    fn targets(len: usize, hit: &[usize]) -> Vec<bool> {
        let mut t = vec![false; len + 4];
        for &p in hit {
            t[p] = true;
        }
        t
    }

    #[test]
    fn a_vm_free_window_ends_at_its_xreturn() {
        // `x.m(); return this;`
        let code = [0x57u8, 0x2a, 0xb0];
        assert_eq!(lazy_return_window_end(&code, 0, &targets(3, &[])), Some(2));
        // `x.m(); return true;`
        let code = [0x57u8, 0x04, 0xac];
        assert_eq!(lazy_return_window_end(&code, 0, &targets(3, &[])), Some(2));
        // `return x.m() + 1;`
        let code = [0x04u8, 0x60, 0xac];
        assert_eq!(lazy_return_window_end(&code, 0, &targets(3, &[])), Some(2));
        // `return (byte) (x.m() ^ k & 7);` with a two- and a three-byte operand.
        let code = [0x15u8, 0x02, 0x82, 0x11, 0x00, 0x07, 0x7e, 0x91, 0xac];
        assert_eq!(lazy_return_window_end(&code, 0, &targets(9, &[])), Some(8));
        // The zero-length window is the wave-7 rule.
        let code = [0xb1u8];
        assert_eq!(lazy_return_window_end(&code, 0, &targets(1, &[])), Some(0));
    }

    #[test]
    fn a_window_refuses_anything_that_can_enter_the_vm_or_merge() {
        let none =
            |code: &[u8], bt: &[usize]| lazy_return_window_end(code, 0, &targets(code.len(), bt));
        // getfield (implicit null check), ldc (resolution), checkcast (slow
        // arm), idiv / irem (zero-divisor throw), an invoke, stores, iinc, a
        // branch, athrow.
        for op in [
            0xb4u8, 0x12, 0xc0, 0x6c, 0x70, 0xb6, 0x3a, 0x36, 0x84, 0xa7, 0x99, 0xbf,
        ] {
            assert_eq!(
                none(&[0x2a, op, 0x00, 0x00, 0xb0], &[]),
                None,
                "op {op:#04x}"
            );
        }
        // A merge point inside the window, at its start, or on its `xreturn`.
        assert_eq!(none(&[0x57, 0x2a, 0xb0], &[1]), None);
        assert_eq!(none(&[0x57, 0x2a, 0xb0], &[2]), None);
        assert_eq!(none(&[0x57, 0x2a, 0xb0], &[0]), None);
        // Longer than the bound.
        let mut long = vec![0x00u8; LAZY_RETURN_WINDOW_MAX_OPS + 1];
        long.push(0xb1);
        assert_eq!(none(&long, &[]), None);
        let mut fits = vec![0x00u8; LAZY_RETURN_WINDOW_MAX_OPS];
        fits.push(0xb1);
        assert_eq!(none(&fits, &[]), Some(LAZY_RETURN_WINDOW_MAX_OPS));
        // Running off the code.
        assert_eq!(none(&[0x57, 0x2a], &[]), None);
        assert_eq!(none(&[0x11, 0x00], &[]), None);
    }

    #[test]
    fn the_wave_8_switches_are_opt_in() {
        for (key, read) in [
            (
                "CRATONVM_JIT_SP_LAZY_RETURN_REPUBLISH_WINDOW",
                super::sp_lazy_return_republish_window_enabled as fn() -> bool,
            ),
            (
                "CRATONVM_JIT_SP_TAIL_LEAF_HELPERS_WIDE",
                super::sp_tail_leaf_helpers_wide_enabled as fn() -> bool,
            ),
        ] {
            let unset = cratonvm_types::flags::with_thread_overrides(&[(key, None)], read);
            assert!(!unset, "{key}");
        }
    }

    /// Production text of `file` (relative to `jit/src`), cut at its first
    /// `#[cfg(test)]`.
    fn production(file: &str) -> String {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("src")
            .join(file);
        let text = std::fs::read_to_string(&path).expect("source is UTF-8");
        text.split("#[cfg(test)]").next().unwrap_or("").to_string()
    }

    /// The single-pass walk's family of `op`, read from the `let family =
    /// match op {` table of `x64/bytecode_walk.rs`.
    fn walk_family_of(op: u8) -> Option<String> {
        let text = production("x64/bytecode_walk.rs");
        let start = text
            .find("let family = match op {")
            .expect("the family table exists");
        let table = &text[start..];
        let end = table.find("\n            };").unwrap_or(table.len());
        let hex = |t: &str| u8::from_str_radix(t.trim().trim_start_matches("0x"), 16).ok();
        for line in table[..end].lines() {
            let Some((pats, fam)) = line.split_once("=> WalkFamily::") else {
                continue;
            };
            let fam = fam.trim().trim_end_matches(',').to_string();
            for pat in pats.split('|') {
                let pat = pat.trim();
                let hit = match pat.split_once("..=") {
                    Some((a, b)) => {
                        matches!((hex(a), hex(b)), (Some(a), Some(b)) if (a..=b).contains(&op))
                    }
                    None => hex(pat) == Some(op),
                };
                if hit {
                    return Some(fam);
                }
            }
        }
        None
    }

    /// TAIL7-19-1's obligation, pinned: no window bytecode is lowered by
    /// anything that can call. Every row is walked by `walk_local_stack`
    /// (which emits no call of any kind) or by `walk_arith` (whose only call
    /// is the `frem`/`drem` helper, under the `0x72 | 0x73` arm). A new row,
    /// a family remap or a new call in either walker fails here.
    #[test]
    fn every_window_bytecode_is_lowered_without_a_call() {
        let arith: &[u8] = &[
            0x60, 0x64, 0x68, 0x74, 0x78, 0x7a, 0x7c, 0x7e, 0x80, 0x82, 0x91, 0x92, 0x93,
        ];
        for &(op, _) in LAZY_RETURN_WINDOW_OPS {
            let want = if arith.contains(&op) {
                "Arith"
            } else {
                "LocalStack"
            };
            assert_eq!(
                walk_family_of(op).as_deref(),
                Some(want),
                "window op {op:#04x} is no longer walked by the reviewed family"
            );
        }
        let local = production("x64/op_local_stack.rs");
        for needle in [
            "emit_call",
            "self.helpers.",
            "emit_jmp_absolute",
            "0xFF, 0xD0",
            "0xE8]",
        ] {
            assert!(
                !local.contains(needle),
                "`walk_local_stack` grew `{needle}`: prove it cannot reach the VM or \
                 drop its rows from LAZY_RETURN_WINDOW_OPS"
            );
        }
        let arith_text = production("x64/op_arith.rs");
        assert_eq!(
            arith_text.matches("emit_call").count(),
            1,
            "`walk_arith` grew a call: prove it cannot reach the VM or drop its rows \
             from LAZY_RETURN_WINDOW_OPS"
        );
        let frem_arm = arith_text
            .find("0x72 | 0x73 =>")
            .expect("the frem/drem arm exists");
        let call = arith_text.find("emit_call").unwrap();
        assert!(
            call > frem_arm,
            "the one call of walk_arith is the frem/drem helper"
        );
        assert!(
            !production("x64/arith.rs").contains("emit_call"),
            "the arithmetic emitters grew a call"
        );
    }

    /// The window is consulted only inside the one admission function the
    /// four lazy sites ask (tail7's ratchet counts those).
    #[test]
    fn the_window_is_asked_only_by_the_admission_function() {
        let text = production("x64/op_invoke.rs");
        let needle = "lazy_return_window_end(code, pc + invoke_len, branch_targets)";
        assert_eq!(text.matches(needle).count(), 1);
        let admit = text
            .find("fn sp_lazy_return_republish_admitted(")
            .expect("the admission function exists");
        assert!(text.find(needle).unwrap() > admit);
    }

    /// The instance arm's twin site sits after the thin prefixes and BEFORE
    /// anything of the ordinary call (the service copy is the first thing
    /// that call emits), so its decline edge is that call, byte for byte.
    #[test]
    fn the_instance_twin_precedes_the_ordinary_call() {
        let text = production("x64/op_invoke.rs");
        let needle = "self.try_emit_sp_instance_tail_leaf_twin(";
        assert_eq!(text.matches(needle).count(), 1);
        let site = text.find(needle).unwrap();
        let prefix_end = text
            .find("// ===== INTRINSIC REGION END: SP_THIN_HELPER_PREFIX =====")
            .expect("the prefix region exists");
        let service = text[site..]
            .find("self.reserve_direct_call_service_slots(args_frame_top, &arg_slots)")
            .expect("the ordinary call's service copy follows");
        let next_call = text[site..]
            .find("self.emit_call_absolute(callee_entry);")
            .expect("the ordinary call follows");
        assert!(prefix_end < site && service < next_call);
    }

    fn test_compiler() -> Compiler {
        let alloc_result = crate::regalloc::RegAllocResult {
            assignments: Vec::new(),
            xmm_assignments: Vec::new(),
            used_callee_saved: Vec::new(),
            used_xmm_regs: Vec::new(),
            block_live_in: Vec::new(),
        };
        Compiler::new(
            "r19-tail8-test".to_string(),
            crate::ExecutableBuffer::new(4096).expect("test executable buffer"),
            0,
            0,
            8,
            false,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            alloc_result,
            false,
            cratonvm_jit_api::JitRuntimeHelpers::default(),
            0,
            false,
            false,
            false,
            false,
            false,
            Vec::new(),
        )
    }

    fn decline_bytes(decline: i64) -> Vec<u8> {
        let mut c = test_compiler();
        let start = c.buf.pos();
        c.emit_cmp_rax_leaf_twin_decline(decline);
        c.buf.as_slice()[start..c.buf.pos()].to_vec()
    }

    #[test]
    fn the_decline_compare_takes_the_narrowest_exact_encoding() {
        assert_eq!(decline_bytes(-1), vec![0x48, 0x83, 0xF8, 0xFF]);
        assert_eq!(
            decline_bytes(0x1234),
            vec![0x48, 0x81, 0xF8, 0x34, 0x12, 0x00, 0x00]
        );
        let wide = decline_bytes(crate::direct_helpers::LEAF_TWIN_DECLINE_OUTSIDE_INT);
        assert_eq!(&wide[wide.len() - 3..], &[0x4C, 0x39, 0xD8], "CMP RAX, R11");
        let imm = crate::direct_helpers::LEAF_TWIN_DECLINE_OUTSIDE_INT.to_le_bytes();
        assert!(
            wide.windows(8).any(|w| w == imm),
            "the full 64-bit decline is materialized"
        );
        // `0` keeps the wave-7 `TEST RAX, RAX`.
        assert_eq!(decline_bytes(0).len(), 3);
    }

    #[test]
    fn the_tail_shape_test_matches_the_static_arms_table() {
        for (ret, op) in [
            (b'I', 0xac),
            (b'Z', 0xac),
            (b'J', 0xad),
            (b'F', 0xae),
            (b'D', 0xaf),
            (b'L', 0xb0),
            (b'[', 0xb0),
            (b'V', 0xb1),
        ] {
            assert!(tail_return_op_matches(ret, op));
        }
        assert!(!tail_return_op_matches(b'Z', 0xb0));
        assert!(!tail_return_op_matches(b'L', 0xac));
        assert!(!tail_return_op_matches(b'V', 0xac));
        assert!(!tail_return_op_matches(b'I', 0x57));
    }
}

#[cfg(test)]
mod gci_i1sp_zero_dead_arg_sources_tests {
    //! gci i1/sp: `CRATONVM_JIT_SP_ZERO_DEAD_ARG_SOURCES` (g5jm's holder).
    use super::dead_arg_source_offsets;
    use crate::x64::StackSlot;

    /// g5jm's shape at `sp=55`: `new WeakReference<>(chainHead)`, the `dup`
    /// at 72 and the marker at 80 popped from a cursor of 88 to 72, with the
    /// `new` result left at 64. Both popped reference sources are zeroed.
    #[test]
    fn gci_i1sp_the_g5jm_sources_are_the_reclaimed_reference_slots() {
        let slots = [StackSlot::Frame(72), StackSlot::Frame(80)];
        assert_eq!(dead_arg_source_offsets(&slots, &[true, true], 64, 72, 88), vec![72, 80]);
    }

    /// A primitive argument, a register-resident one and a slot outside the
    /// reclaimed range (a deeper word an aliasing operand still owns, a word
    /// below the operand band) are never zeroed; two arguments aliasing one
    /// word give it once; nothing reclaimed means nothing zeroed.
    #[test]
    fn gci_i1sp_only_reclaimed_reference_words_in_the_band_qualify() {
        let slots = [
            StackSlot::Frame(64),
            StackSlot::Frame(80),
            StackSlot::Frame(72),
            StackSlot::CalleeSaved(12),
            StackSlot::Frame(72),
        ];
        let oops = [true, false, true, true, true];
        assert_eq!(dead_arg_source_offsets(&slots, &oops, 64, 72, 88), vec![72]);
        assert_eq!(dead_arg_source_offsets(&slots, &oops, 80, 72, 88), Vec::<i32>::new());
        assert_eq!(dead_arg_source_offsets(&slots, &oops, 64, 88, 88), Vec::<i32>::new());
        assert_eq!(dead_arg_source_offsets(&slots, &oops, 64, 96, 88), Vec::<i32>::new());
        assert_eq!(dead_arg_source_offsets(&[], &[], 64, 72, 88), Vec::<i32>::new());
    }

    /// The store is `MOV qword [rbp - off], 0`: disp8 for a near word, disp32
    /// for a far one, the zero immediate last, and it drops the slot mirror.
    #[test]
    fn gci_i1sp_the_zero_store_encodes_mov_rbp_disp_imm32_zero() {
        let mut c = super::super::emit::tests::test_compiler();
        let start = c.buf.pos();
        c.emit_zero_frame_word(80);
        assert_eq!(
            &c.buf.as_slice()[start..c.buf.pos()],
            &[0x48, 0xC7, 0x45, 0xB0, 0, 0, 0, 0][..]
        );
        assert!(c.slot_mirror.is_none());
        let start = c.buf.pos();
        c.emit_zero_frame_word(200);
        let mut far = vec![0x48, 0xC7, 0x85];
        far.extend_from_slice(&(-200i32).to_le_bytes());
        far.extend_from_slice(&[0, 0, 0, 0]);
        assert_eq!(&c.buf.as_slice()[start..c.buf.pos()], &far[..]);
    }

    /// The call arms that stage their arguments elsewhere -- the two
    /// dispatch-helper arms, the two direct-call arms and (gci i2/sp) the
    /// cycle-edge cell call and the bridged `invokedynamic` -- each ask once.
    #[test]
    fn gci_i1sp_every_staging_arm_offers_the_zeroing() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("src")
            .join("x64/op_invoke.rs");
        let text = std::fs::read_to_string(&path).expect("source is UTF-8");
        let production = text.split("#[cfg(test)]").next().unwrap_or("");
        assert_eq!(production.matches("self.emit_zero_dead_arg_sources(").count(), 6);
    }
}

#[cfg(test)]
mod gci_i2sp_zero_dead_arg_sources_default_tests {
    //! gci i2/sp: `CRATONVM_JIT_SP_ZERO_DEAD_ARG_SOURCES` ships default ON
    //! (`=0` kill), and the two splice call arms zero their popped sources too
    //! (`gci-i1sp-spliced-direct-holder-is-the-splices-own-copy`, C1).
    use super::{dead_arg_source_offsets, sp_zero_dead_arg_sources_enabled};
    use crate::x64::StackSlot;

    const KEY: &str = "CRATONVM_JIT_SP_ZERO_DEAD_ARG_SOURCES";

    /// Unset is ON; the four off words turn it off; `1` keeps it on.
    #[test]
    fn gci_i2sp_zero_dead_arg_sources_is_default_on_with_a_zero_kill() {
        use cratonvm_types::flags::with_thread_overrides;
        assert!(with_thread_overrides(&[(KEY, None)], sp_zero_dead_arg_sources_enabled));
        assert!(with_thread_overrides(&[(KEY, Some("1"))], sp_zero_dead_arg_sources_enabled));
        for off in ["0", "false", "off", "no"] {
            assert!(
                !with_thread_overrides(&[(KEY, Some(off))], sp_zero_dead_arg_sources_enabled),
                "`{KEY}={off}` must turn the zeroing off"
            );
        }
    }

    /// The emitter honours the kill: off the switch it emits no byte and
    /// zeroes nothing; on it, one 8-byte store per reclaimed reference word.
    #[test]
    fn gci_i2sp_the_kill_emits_nothing_and_the_default_emits_the_stores() {
        use cratonvm_types::flags::with_thread_overrides;
        let slots = [StackSlot::Frame(72), StackSlot::Frame(80)];
        let oops = [true, true];
        let mut c = super::super::emit::tests::test_compiler();
        c.base_spill_offset = 64;
        let start = c.buf.pos();
        let off = with_thread_overrides(&[(KEY, Some("0"))], || {
            c.emit_zero_dead_arg_sources(&slots, &oops, 72, 88)
        });
        assert!(off.is_empty());
        assert_eq!(c.buf.pos(), start);
        let on = with_thread_overrides(&[(KEY, None)], || {
            c.emit_zero_dead_arg_sources(&slots, &oops, 72, 88)
        });
        assert_eq!(on, vec![72, 80]);
        assert_eq!(c.buf.pos() - start, 16);
    }

    /// The splice shape: the callee's reserved locals sit at 64..80 (local 0
    /// at 64 holds the spliced callee's parameter), its operands above them.
    /// A call inside the splice pops two reference operands from a cursor of
    /// 96 down to 80: both popped words are zeroed, and a slot naming a
    /// reserved local (below `post_pop_spill`) never is.
    #[test]
    fn gci_i2sp_a_splice_call_zeroes_only_its_popped_operands_not_the_splice_locals() {
        let slots = [StackSlot::Frame(80), StackSlot::Frame(88), StackSlot::Frame(64)];
        let oops = [true, true, true];
        assert_eq!(dead_arg_source_offsets(&slots, &oops, 48, 80, 96), vec![80, 88]);
    }

    /// Both splice call arms (`inlining.rs` `emit_inline_direct_call`, after
    /// `emit_stack_arg_setup`, and `emit_inline_dispatch_call`, after the
    /// buffer loop) ask once each.
    #[test]
    fn gci_i2sp_both_splice_call_arms_offer_the_zeroing() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("src")
            .join("x64/inlining.rs");
        let text = std::fs::read_to_string(&path).expect("source is UTF-8");
        assert_eq!(text.matches("self.emit_zero_dead_arg_sources(").count(), 2);
    }
}

#[cfg(test)]
mod jr21_hash2_sp_class_table_tests {
    //! JIT round 21, lane hash2 (`CRATONVM_JIT_OBJECT_HASH_CLASS_TABLE`): the
    //! single-pass box-hash prefix's identity arm reads the per-VM class
    //! verdict table after its exact-`Object` compare, with the optimizing
    //! tier's bytes (`ir_lower::identity_hash_class_table_test_bytes`).

    use super::*;

    const FAKE_TABLE: i64 = 0x7f00_0000_4000;

    extern "C" fn fake_well_known(_ctx: i64, which: i64) -> i64 {
        if which
            == crate::ir_lower::vh_const_query(
                crate::ir_lower::WELL_KNOWN_VH_CONST_IDENTITY_HASH_TABLE_TAG,
                0,
                0,
            )
        {
            FAKE_TABLE
        } else {
            0
        }
    }

    fn object_hash() -> crate::JitInvokeInfo {
        crate::JitInvokeInfo {
            class_name: "java/lang/Object",
            method_name: "hashCode",
            descriptor: "()I",
            num_jit_args: 1,
            return_type: b'I',
            invoke_kind: 0,
            declaring_class_id: 0,
            owner_class_id: 0,
        }
    }

    fn emit(table: Option<&str>) -> (Vec<usize>, Vec<u8>, i32) {
        cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_SP_BOX_HASH_CLASS_ARM", Some("0")),
                ("CRATONVM_JIT_OBJECT_HASH_CLASS_TABLE", table),
            ],
            || {
                let mut c = super::super::emit::tests::test_compiler();
                c.direct_helpers.well_known_class_id = fake_well_known as *const () as usize;
                c.direct_helpers.static_base_resolver_ctx = 1;
                c.string_layout = None;
                c.stack.clear();
                c.stack.push(StackSlot::Frame(8));
                let start = c.buf.pos();
                let hits = c.try_emit_box_hash_equals_prefix(4, &object_hash());
                let cid_off = c.helpers.class_id_offset_in_obj as i32; // Cast: disp32
                let bytes = c.buf.as_slice()[start..].to_vec();
                (hits, bytes, cid_off)
            },
        )
    }

    fn has(bytes: &[u8], pat: &[u8]) -> bool {
        bytes.windows(pat.len()).any(|w| w == pat)
    }

    /// Default: exact-`Object` compare, then the table test (its class-id
    /// load, baked table address and verdict compare appear verbatim), then
    /// the header read. `=0`: the compare alone, no table bytes.
    #[test]
    fn the_object_hash_site_reads_the_class_table_after_the_exact_compare() {
        let on = sp_identity_hash_inline_enabled()
            && crate::ir_lower::ir_identity_hash_inline_enabled()
            && !crate::x64::zgc_read_barrier_blocks_inline_fields();
        // Cast: the fake address, as the compiler bakes it.
        let (test, _) = crate::ir_lower::identity_hash_class_table_test_bytes(FAKE_TABLE as u64, 0);
        let (hits, bytes, cid_off) = emit(None);
        assert_eq!(!hits.is_empty(), on);
        let (test_here, _) =
            crate::ir_lower::identity_hash_class_table_test_bytes(FAKE_TABLE as u64, cid_off);
        // Everything after the class-id load's displacement (table address,
        // capacity compare, verdict compare) is offset-independent.
        assert_eq!(test[6..], test_here[6..]);
        let table_imm = &test_here[6..16];
        assert_eq!(has(&bytes, table_imm), on, "MOV RDX, table");
        assert_eq!(
            has(&bytes, &[0x80, 0x7C, 0x0A, 0x08, 0x01]),
            on,
            "verdict compare"
        );
        let (_, bytes_off, _) = emit(Some("0"));
        assert!(!has(&bytes_off, table_imm));
        if on {
            // The exact-Object compare stays in both arms.
            let mut cmp0 = vec![0x81, 0xB8];
            cmp0.extend_from_slice(&cid_off.to_le_bytes());
            cmp0.extend_from_slice(&0u32.to_le_bytes());
            assert!(has(&bytes, &cmp0) && has(&bytes_off, &cmp0));
        }
    }
}

#[cfg(test)]
mod jr21_hashlock_sp_equals_arm_tests {
    //! JIT round 21, lane hashlock (HASH2-21-1,
    //! `CRATONVM_JIT_OBJECT_EQUALS_IDENTITY_ARM`): the single-pass box-hash
    //! prefix answers an `Object.equals(Object)` site as `this == arg` for an
    //! exact `java/lang/Object`, a vouched seeded class, or a PROVEN verdict
    //! byte of the per-VM equals table; `=0` emits nothing when no `Integer`
    //! half exists.

    use super::*;

    const FAKE_TABLE: i64 = 0x7f00_0000_8000;
    const FAKE_PROFILED_ID: u32 = 0x2345;

    extern "C" fn fake_well_known(_ctx: i64, which: i64) -> i64 {
        if which
            == crate::ir_lower::vh_const_query(
                crate::ir_lower::WELL_KNOWN_VH_CONST_IDENTITY_EQUALS_TABLE_TAG,
                0,
                0,
            )
        {
            FAKE_TABLE
        } else if which
            == crate::ir_lower::vh_const_query(
                crate::ir_lower::WELL_KNOWN_VH_CONST_IDENTITY_EQUALS_TAG,
                FAKE_PROFILED_ID,
                0,
            )
        {
            1
        } else {
            0
        }
    }

    fn object_equals() -> crate::JitInvokeInfo {
        crate::JitInvokeInfo {
            class_name: "java/lang/Object",
            method_name: "equals",
            descriptor: "(Ljava/lang/Object;)Z",
            num_jit_args: 2,
            return_type: b'Z',
            invoke_kind: 0,
            declaring_class_id: 0,
            owner_class_id: 0,
        }
    }

    fn emit(arm: Option<&str>, info: &crate::JitInvokeInfo) -> (Vec<usize>, Vec<u8>, i32) {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_OBJECT_EQUALS_IDENTITY_ARM", arm)],
            || {
                let mut c = super::super::emit::tests::test_compiler();
                c.direct_helpers.well_known_class_id = fake_well_known as *const () as usize;
                c.direct_helpers.static_base_resolver_ctx = 1;
                c.string_layout = None;
                c.stack.clear();
                c.stack.push(StackSlot::Frame(8));
                c.stack.push(StackSlot::Frame(16));
                let mic = Box::new(crate::JitMICSlot::new());
                mic.prepopulate(FAKE_PROFILED_ID);
                c.mic_slots.push((4, &*mic as *const crate::JitMICSlot));
                c.mic_slots_idx.insert(4, c.mic_slots.len() - 1);
                let start = c.buf.pos();
                let hits = c.try_emit_box_hash_equals_prefix(4, info);
                let cid_off = c.helpers.class_id_offset_in_obj as i32; // Cast: disp32
                let bytes = c.buf.as_slice()[start..].to_vec();
                drop(c);
                drop(mic);
                (hits, bytes, cid_off)
            },
        )
    }

    fn has(bytes: &[u8], pat: &[u8]) -> bool {
        bytes.windows(pat.len()).any(|w| w == pat)
    }

    fn cmp(cid_off: i32, id: u32) -> Vec<u8> {
        let mut v = vec![0x81, 0xB8];
        v.extend_from_slice(&cid_off.to_le_bytes());
        v.extend_from_slice(&id.to_le_bytes());
        v
    }

    /// Default: the seeded-class compare, the exact-`Object` compare, the
    /// table test (class-id load + baked table address) and the answer
    /// `CMP RAX, RDX ; SETE AL ; MOVZX EAX, AL`. `=0`: nothing at all.
    #[test]
    fn the_object_equals_site_takes_the_identity_arm() {
        let on = !crate::x64::zgc_read_barrier_blocks_inline_fields();
        let (hits, bytes, cid_off) = emit(None, &object_equals());
        assert_eq!(!hits.is_empty(), on);
        assert_eq!(
            has(&bytes, &cmp(cid_off, FAKE_PROFILED_ID)),
            on,
            "seeded class"
        );
        assert_eq!(has(&bytes, &cmp(cid_off, 0)), on, "exact Object");
        // `ir_lower::identity_hash_class_table_test_bytes`: MOV ECX,
        // [RAX+cid_off] (6 bytes) then MOV RDX, imm64 table (10 bytes).
        let (test, _) = crate::ir_lower::identity_hash_class_table_test_bytes(
            // Cast: the fake table address is positive.
            FAKE_TABLE as u64,
            cid_off,
        );
        assert_eq!(has(&bytes, &test[..16]), on, "table test");
        assert_eq!(
            has(
                &bytes,
                &[0x48, 0x39, 0xD0, 0x0F, 0x94, 0xC0, 0x0F, 0xB6, 0xC0]
            ),
            on,
            "this == arg"
        );
        let (hits_off, bytes_off, _) = emit(Some("0"), &object_equals());
        assert!(hits_off.is_empty() && bytes_off.is_empty());
    }

    /// Only an `Object`-declared `equals` takes the arm: a `Number`-typed
    /// site (an Integer-only site, and no `Integer` id here) emits nothing.
    #[test]
    fn other_sites_do_not_take_the_equals_arm() {
        let mut number = object_equals();
        number.class_name = "java/lang/Number";
        let (hits_n, bytes_n, _) = emit(None, &number);
        assert!(hits_n.is_empty() && bytes_n.is_empty());
    }
}

/// JIT round 21, lane spg1vh (G1VHSOFT21-1 of
/// `docs/internal/proposals/jit/tier2/jit-r21-g1vhsoft-proposals.md`): the single-pass
/// constant-`VarHandle` prefix's G1 plan. Its screens and access are the
/// optimizing tier's bytes (executed by `ir_lower`'s
/// `jr21_g1vh_vh_const_g1_tests`); these pin the single-pass half: which plan
/// a reference write is built against, and that the post edge is the access
/// followed by the single-pass `putfield`'s own G1 post barrier.
#[cfg(all(test, target_arch = "x86_64"))]
mod jr21_spg1vh_sp_vh_const_g1_tests {
    use super::*;
    use crate::direct_helpers::UnsafeRmwOp;
    use crate::ir_lower::{VhConstCore, VhConstOp, VhG1Gates, VhRefValueCheck, VhStoreBarriers};
    use std::sync::atomic::AtomicUsize;

    /// Never executed: out of rel32 reach of every buffer, so the barrier's
    /// call is the position-independent `MOV RAX, imm64 ; CALL RAX` form and
    /// two compilers' bytes compare equal.
    const FAR_BARRIER: usize = 0x4000_0000_0000_0000;

    /// `JIT_G1_BARRIER`'s shape, live: arena base, length, region mask.
    fn table() -> Box<[AtomicUsize; 5]> {
        Box::new([
            AtomicUsize::new(0x1000_0000),
            AtomicUsize::new(1 << 20),
            AtomicUsize::new(!0xF_FFFF),
            AtomicUsize::new(0),
            AtomicUsize::new(0),
        ])
    }

    /// Every switch the G1 plan reads, as if unset (default ON), plus `ours`
    /// for `CRATONVM_JIT_SP_VH_CONST_G1`; no edge filter (no resolver here).
    fn with_switches<R>(ours: Option<&str>, f: impl FnOnce() -> R) -> R {
        crate::x64::licm::G1_INLINE_BARRIER_FORCED.with(|c| c.set(Some(true)));
        let r = cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_SP_VH_CONST_G1", ours),
                ("CRATONVM_JIT_VH_CONST_G1_REF", None),
                ("CRATONVM_JIT_IR_G1_REF_STORE", None),
                ("CRATONVM_JIT_IR_G1_GATED_REF_STORE", None),
                ("CRATONVM_JIT_G1_EDGE_FILTER", Some("0")),
            ],
            f,
        );
        crate::x64::licm::G1_INLINE_BARRIER_FORCED.with(|c| c.set(None));
        r
    }

    fn g1_compiler(table: &[AtomicUsize; 5]) -> Compiler {
        let mut c = super::super::emit::tests::test_compiler();
        c.helpers.g1_barrier_addr = table.as_ptr() as usize; // Cast: the table's address
        c.helpers.ref_store_pre_gate = 0x2000; // baked, never executed
        c.helpers.g1_post_write_barrier = FAR_BARRIER;
        c.heap_local_offset = 16;
        c
    }

    #[test]
    fn under_g1_a_reference_write_is_built_against_the_g1_plan() {
        let t = table();
        let addr = t.as_ptr() as usize; // Cast: the table's address
        let mut c = g1_compiler(&t);
        let on = with_switches(None, || c.sp_vh_const_store_barriers());
        assert_eq!(
            on,
            VhStoreBarriers::G1(VhG1Gates {
                pre: 0x2000,
                table: addr,
                post_call: true,
            }),
            "the optimizing tier's plan, with the post edge"
        );
        // The kill switch: the published gates (none under G1), i.e. the call.
        let off = with_switches(Some("0"), || c.sp_vh_const_store_barriers());
        assert!(!matches!(off, VhStoreBarriers::G1(_)), "{off:?}");
        // No VM-context slot: a cross-region value declines to the call.
        c.heap_local_offset = 0;
        let no_ctx = with_switches(None, || c.sp_vh_const_store_barriers());
        assert_eq!(
            no_ctx,
            VhStoreBarriers::G1(VhG1Gates {
                pre: 0x2000,
                table: addr,
                post_call: false,
            })
        );
        // A collector that publishes gates keeps them (ZGC / Generational).
        c.heap_local_offset = 16;
        c.helpers.ref_store_post_gate = 0x2001;
        c.helpers.ref_store_post_young_floor = 0;
        c.helpers.ref_store_post_skip_mask = usize::from(cratonvm_types::GC_FLAG_OLD_GEN);
        let gen = with_switches(None, || c.sp_vh_const_store_barriers());
        assert_eq!(
            gen,
            VhStoreBarriers::Gates(
                Some((0x2000, 0x2001, 0)),
                Some(cratonvm_types::GC_FLAG_OLD_GEN)
            )
        );
        drop(t);
    }

    fn core(op: VhConstOp, table: usize) -> VhConstCore {
        VhConstCore {
            op,
            kind: b'L',
            disp: 16,
            class_id: 0x2468,
            receiver_display: None,
            cid_off: 0,
            expected_check: VhRefValueCheck::Admitted,
            value_check: VhRefValueCheck::Admitted,
            result_check: VhRefValueCheck::Admitted,
            gates: None,
            g1: Some(VhG1Gates {
                pre: 0x2000,
                table,
                post_call: true,
            }),
        }
    }

    /// The post edge is the access, then exactly the bytes the single-pass
    /// `putfield` emits for its G1 post barrier (operands reloaded, the
    /// null / same-region filter, `jit_g1_post_write_barrier`), with the
    /// result kept above the callee's home area when the site has one.
    #[test]
    fn the_post_edge_is_the_access_then_the_putfield_barrier() {
        let t = table();
        let addr = t.as_ptr() as usize; // Cast: the table's address
        let (recv, value) = (StackSlot::Frame(8), StackSlot::Frame(16));
        let cases = [
            (VhConstOp::Set { volatile: false }, false),
            (VhConstOp::Set { volatile: true }, false),
            (VhConstOp::Rmw(UnsafeRmwOp::Cas), true),
            (VhConstOp::Rmw(UnsafeRmwOp::Cae), true),
            (VhConstOp::Rmw(UnsafeRmwOp::GetAndSet), true),
        ];
        for (op, keep) in cases {
            let k = core(op, addr);
            let (got, want) = with_switches(None, || {
                let mut c = g1_compiler(&t);
                let start = c.buf.pos();
                let _ = c.emit_sp_vh_g1_post_edge(&k, keep, recv, value);
                let got = c.buf.as_slice()[start..].to_vec();
                let mut r = g1_compiler(&t);
                let start = r.buf.pos();
                r.buf.emit(&crate::ir_lower::vh_const_access_bytes(&k).0);
                if keep {
                    r.buf.emit(&SP_VH_G1_KEEP_RESULT);
                }
                r.load_slot_to_reg(RAX, recv);
                r.load_slot_to_reg(RDX, value);
                r.emit_g1_post_write_barrier_regs(RAX, RDX, RCX, recv, value);
                if keep {
                    r.buf.emit(&SP_VH_G1_RESTORE_RESULT);
                }
                (got, r.buf.as_slice()[start..].to_vec())
            });
            assert_eq!(got, want, "{op:?}");
            let (access, _) = crate::ir_lower::vh_const_access_bytes(&k);
            assert!(got.starts_with(&access), "{op:?}: the access first");
            assert_eq!(
                got.ends_with(&SP_VH_G1_RESTORE_RESULT),
                keep,
                "{op:?}: the result restored last"
            );
            // The barrier's call: MOV RAX, imm64 FAR_BARRIER ; CALL RAX.
            let mut call = vec![0x48, 0xB8];
            call.extend_from_slice(&(FAR_BARRIER as u64).to_le_bytes()); // Cast: address
            assert!(
                got.windows(call.len()).any(|w| w == call.as_slice()),
                "{op:?}: jit_g1_post_write_barrier"
            );
        }
        drop(t);
    }

    /// The two encodings: 48 bytes off RSP (16-byte aligned), the word at
    /// RSP+32 (above a Win64 callee's 32-byte home area), undone in reverse.
    #[test]
    fn the_result_is_kept_above_the_home_area() {
        // SUB RSP, 0x30 ; MOV [RSP+0x20], RAX
        assert_eq!(&SP_VH_G1_KEEP_RESULT[..4], &[0x48, 0x83, 0xEC, 0x30]);
        assert_eq!(&SP_VH_G1_KEEP_RESULT[4..], &[0x48, 0x89, 0x44, 0x24, 0x20]);
        // MOV RAX, [RSP+0x20] ; ADD RSP, 0x30
        assert_eq!(
            &SP_VH_G1_RESTORE_RESULT[..5],
            &[0x48, 0x8B, 0x44, 0x24, 0x20]
        );
        assert_eq!(&SP_VH_G1_RESTORE_RESULT[5..], &[0x48, 0x83, 0xC4, 0x30]);
    }

    /// The prefix builds every reference write against the store-barrier
    /// choice above and takes the post edge (a text pin on the production
    /// body, which needs a VM-filed plan to run).
    #[test]
    fn the_prefix_takes_the_g1_plan_and_its_post_edge() {
        let text = include_str!("op_invoke.rs");
        let production = text.split("#[cfg(test)]").next().unwrap_or("");
        let start = production
            .find("    fn emit_sp_vh_const_prefix(")
            .expect("the prefix");
        let end = production[start..]
            .find("    fn sp_vh_const_store_barriers(")
            .expect("the plan choice follows it");
        let body = &production[start..start + end];
        assert!(body.contains("self.sp_vh_const_store_barriers(),"));
        assert!(body.contains("crate::ir_lower::vh_const_core_bytes_post(&core)"));
        // j27 wave 4 (lane VHCARD): `keep` = `shape.ret != b'V'`; the same
        // edge now also serves the generational card edge.
        assert!(body.contains("let keep = shape.ret != b'V';"));
        assert!(body.contains("self.emit_sp_vh_g1_post_edge(&core, keep, ops[1], value)"));
        assert!(body.contains("self.emit_sp_vh_gen_card_edge(&core, keep, ops[1], expected, value)"));
        assert!(body.contains("self.emit_jmp_back_to(hit_at);"));
        // The edge's own access screens decline to the call too.
        assert!(body.contains("decline.extend(edge_declines);"));
        assert!(
            !body.contains("VhStoreBarriers::Gates("),
            "one choice, not two"
        );
    }
}

#[cfg(test)]
mod j27_t1disp20_sp_ref_array_arm_tests {
    //! j27 wave 6, lane T1DISP20 (DISP20-8,
    //! `CRATONVM_JIT_UNSAFE_REF_ARRAY_INLINE`, default ON since 2026-10-28
    //! (j27 WARNING flip; =0 restores)): the single-pass
    //! `compareAndSetReference` and `getReferenceVolatile` thin binds take the
    //! reference-array element arm with no field cell table at all, only with
    //! the switch AND the row's admission bit; the arm is the array screen
    //! followed by the row's one access on `[base + offset]`.

    use super::*;
    use crate::unsafe_ref_array_arm as ra;

    const KEY: &str = "CRATONVM_JIT_UNSAFE_REF_ARRAY_INLINE";
    const RV: &str = "CRATONVM_JIT_UNSAFE_REF_VOLATILE_FIELD";

    fn has(bytes: &[u8], pat: &[u8]) -> bool {
        bytes.windows(pat.len()).any(|w| w == pat)
    }

    /// Where the screen template starts in `bytes`, its rel32 decline fields
    /// (zero in the template, patched to the decline edge once the emitter
    /// finishes) matching anything. j27 TRIC: a plain byte compare can never
    /// match emitted code, so the test failed on a correct arm.
    fn find_screen(bytes: &[u8], (pat, edges): &(Vec<u8>, Vec<usize>)) -> Option<usize> {
        let free = |i: usize| edges.iter().any(|&e| (e..e + 4).contains(&i));
        bytes
            .windows(pat.len())
            .position(|w| w.iter().zip(pat).enumerate().all(|(i, (a, b))| free(i) || a == b))
    }

    fn skip() -> bool {
        use crate::direct_helpers as dh;
        !dh::unsafe_accessor_inline_enabled()
            || !dh::unsafe_qu_ref_cas_field_enabled()
            || !sp_thin_prefix_enabled()
            || crate::x64::narrow_oops_block_inline_fields()
    }

    /// `(cas, get)`: what the two thin binds emit (`None` = nothing) under
    /// `switch` with admission `bits` and a published gate plan.
    fn emit(switch: Option<&str>, bits: usize) -> (Option<Vec<u8>>, Option<Vec<u8>>) {
        cratonvm_types::flags::with_thread_overrides(&[(KEY, switch), (RV, None)], || {
            let args: Vec<StackSlot> = (1..=5).map(|k| StackSlot::Frame(8 * k)).collect();
            let mut c = super::super::emit::tests::test_compiler();
            c.direct_helpers.unsafe_cas_reference = 0x7500;
            c.direct_helpers.unsafe_get_reference_volatile = 0x7600;
            c.direct_helpers.unsafe_inline_admitted = 0xFFFF | bits;
            c.direct_helpers.unsafe_field_cells = 0;
            c.helpers.ref_store_pre_gate = 0x2000;
            c.helpers.ref_store_post_gate = 0x2001;
            c.helpers.ref_store_post_young_floor = 0;
            c.helpers.ref_store_post_skip_mask = usize::from(cratonvm_types::GC_FLAG_OLD_GEN);
            let start = c.buf.pos();
            let cas = c
                .try_emit_sp_unsafe_access_prefix(0, 0x7500, 4, b'Z', &args)
                .map(|_| c.buf.as_slice()[start..].to_vec());
            let mid = c.buf.pos();
            let get = c
                .try_emit_sp_unsafe_access_prefix(0, 0x7600, 2, b'L', &args[..3])
                .map(|_| c.buf.as_slice()[mid..].to_vec());
            (cas, get)
        })
    }

    #[test]
    fn ref_array_arm_needs_switch_and_bit_and_emits_screen_then_access() {
        if skip() {
            return;
        }
        let both = (1usize << ra::UNSAFE_REF_ARRAY_CAS_GATE_BIT)
            | (1usize << ra::UNSAFE_REF_ARRAY_GET_GATE_BIT)
            | (1usize << crate::direct_helpers::UNSAFE_REF_CAS_GATE_BIT);
        // Off (`=0`; default ON since 2026-10-28): no field table and no
        // array arm -- nothing, as before.
        assert_eq!(emit(Some("0"), both), (None, None));
        // On, but no admission bits: nothing.
        let (cas, get) = emit(Some("1"), 1usize << crate::direct_helpers::UNSAFE_REF_CAS_GATE_BIT);
        assert!(cas.is_none() && get.is_none());
        // Unset is the default ON: the same bytes as `=1`.
        assert_eq!(emit(None, both), emit(Some("1"), both), "unset is on");
        // On with the bits: both rows take the array arm.
        let (cas, get) = emit(Some("1"), both);
        let screen = ra::unsafe_ref_array_screen_bytes();
        let cas = cas.expect("the CAS row takes the array arm");
        let screen_at = find_screen(&cas, &screen).expect("the array screen, byte for byte");
        assert!(
            has(&cas, &[0xF0, 0x4B, 0x0F, 0xB1, 0x14, 0x1A]),
            "LOCK CMPXCHG [R10+R11], RDX"
        );
        let (gate, _) = crate::ir_lower::vh_ref_store_gate_screen_bytes(
            crate::ir_lower::vh_ref_store_gates(
                Some((0x2000, 0x2001, 0)),
                Some(cratonvm_types::GC_FLAG_OLD_GEN),
            )
            .expect("a mask plan"),
        );
        let gate_at = cas.windows(10).position(|w| w == &gate[..10]).expect("the gate screen");
        assert!(gate_at < screen_at, "the barrier gates are decided before the screen");
        let get = get.expect("the get row takes the array arm");
        assert!(find_screen(&get, &screen).is_some(), "the get's array screen");
        assert!(has(&get, &[0x4A, 0x8B, 0x04, 0x18]), "MOV RAX, [RAX+R11]");
        assert!(!has(&get, &gate[..10]), "a get owes no barrier");
    }

    /// j27 wave 7 (IN16-3): the indy bridge's published spill is opt-in and
    /// read per call (no latch).
    #[test]
    fn indy_bridge_published_spill_is_opt_in_and_unlatched() {
        const SPILL: &str = "CRATONVM_JIT_SP_INDY_BRIDGE_SPILL_PUBLISHED";
        cratonvm_types::flags::with_thread_overrides(&[(SPILL, None)], || {
            assert!(!sp_indy_bridge_spill_published_enabled());
        });
        cratonvm_types::flags::with_thread_overrides(&[(SPILL, Some("1"))], || {
            assert!(sp_indy_bridge_spill_published_enabled());
        });
        cratonvm_types::flags::with_thread_overrides(&[(SPILL, Some("0"))], || {
            assert!(!sp_indy_bridge_spill_published_enabled());
        });
    }

    /// j27 wave 7 (SA6-3): the self-recursion question and the driver's
    /// `has_indy_trap` are one predicate over the 0xba arm's three terms.
    #[test]
    fn indy_trap_rows_are_the_negation_of_the_bridged_predicate() {
        const BRIDGE: usize = 0x7000;
        for (site, entry, ret) in [
            (0x9000usize, BRIDGE, b'L'),
            (0, BRIDGE, b'L'),
            (0x9000, 0, b'L'),
            (0x9000, BRIDGE, b'V'),
        ] {
            let row = (3usize, 0usize, ret, Vec::new(), site);
            assert_eq!(
                crate::indy_rows_have_trap(&[row], entry),
                !indy_site_is_bridged(site, entry, ret),
                "site={site:#x} entry={entry:#x} ret={ret}"
            );
        }
    }
}

/// j27 wave 9 (lane W9RPL; OOM21-2): the single-pass half of the opt-in
/// constant-`putstatic` caller rule (`CRATONVM_JIT_OWNED_ARGS_CONST_STATIC_STORES`).
#[cfg(test)]
mod j27_w9rpl_sp_const_static_tests {
    use super::{caller_replay_to_call_is_exact_with_statics as replay, sp_static_row_is_plain};

    // storeCaller: 0 iload_0; 1 newarray byte; 3 astore_1; 4 aconst_null;
    // 5 putstatic; 8 aload_1; 9 iload_0; 10 invokestatic; 13 ireturn
    const STORE: &[u8] = &[
        0x1a, 0xbc, 0x08, 0x4c, 0x01, 0xb3, 0x00, 0x02, 0x2b, 0x1a, 0xb8, 0x00, 0x03, 0xac,
    ];
    const ROWS: &[(usize, u32, usize, u8, bool)] = &[(5, 7, 0, b'L', false)];
    const VOLATILE: &[(usize, u32, usize, u8, bool)] = &[(5, 7, 0, b'L', true)];
    const UNRESOLVED: &[(usize, u32, usize, u8, bool)] = &[(5, 0, 0, b'L', false)];

    #[test]
    fn a_resolved_non_volatile_row_is_plain() {
        assert!(sp_static_row_is_plain(ROWS, 5));
        assert!(!sp_static_row_is_plain(VOLATILE, 5), "volatile");
        assert!(!sp_static_row_is_plain(UNRESOLVED, 5), "class 0: not resolved");
        assert!(!sp_static_row_is_plain(ROWS, 4), "no row at that pc");
    }

    #[test]
    fn the_single_pass_rule_admits_a_constant_store_only_under_the_switch() {
        let key = "CRATONVM_JIT_OWNED_ARGS_CONST_STATIC_STORES";
        cratonvm_types::flags::with_thread_overrides(&[(key, Some("1"))], || {
            assert!(replay(STORE, STORE.len(), 10, &[], ROWS));
            assert!(!replay(STORE, STORE.len(), 10, &[], VOLATILE));
            assert!(!replay(STORE, STORE.len(), 10, &[], &[]));
        });
        cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            assert!(!replay(STORE, STORE.len(), 10, &[], ROWS), "opt-in");
        });
    }
}
